insert into public.themen (id, name, beschreibung) values
  (1, 'Arzttermine', 'Lange Wartezeiten und schwer erreichbare Praxen.'),
  (2, 'Miete', 'Hohe Mieten und schwierige Wohnungssuche.'),
  (3, 'Energiepreise', 'Hohe Kosten für Strom und Heizung.'),
  (4, 'Schule', 'Unterrichtsausfall, fehlende Lehrkräfte und marode Schulgebäude.'),
  (5, 'Arbeitsplätze', 'Unsichere Jobs, Stellenabbau und schwache Wirtschaft.'),
  (6, 'Zuwanderung und Integration', 'Probleme bei Aufnahme, Integration und Rückführung von Zugewanderten.'),
  (7, 'Rente', 'Niedrige Renten und Sorge um die Altersvorsorge.'),
  (8, 'Bus und Bahn', 'Seltene Verbindungen, Ausfälle, Verspätungen und teure Tickets.'),
  (9, 'Sicherheit', 'Sich im Alltag unsicher fühlen oder Opfer von Kriminalität werden.'),
  (10, 'Pflege', 'Pflegeplatz oder Pflegedienst finden, hohe Kosten, überlastete Angehörige.'),
  (11, 'Preise und Löhne', 'Lebensmittel und Dinge des Alltags sind teuer geworden, der Lohn reicht kaum.'),
  (12, 'Straßen und Brücken', 'Kaputte Straßen, gesperrte Brücken, lange Umwege und gefährliche Radwege.'),
  (13, 'Internet und Mobilfunk', 'Langsames Internet zu Hause und Funklöcher unterwegs.'),
  (14, 'Behördengänge', 'Lange Wartezeiten auf Termine und Bescheide, viel Papier, dieselben Angaben immer wieder.'),
  (15, 'Autofahren', 'Teures Tanken, wenige Lademöglichkeiten und teure Elektroautos.'),
  (16, 'Heizungstausch', 'Unsicherheit und hohe Kosten, wenn die Heizung erneuert werden muss oder soll.'),
  (17, 'Kita-Betreuung', 'Familien finden keinen passenden Betreuungsplatz oder erleben, dass die Betreuung zu wenig Personal hat, ausfällt oder zu viel kostet.')
on conflict (id) do update set name = excluded.name, beschreibung = excluded.beschreibung;

