  (101, 1, 'Zu wenige Hausarztpraxen, besonders auf dem Land: Viele Ärztinnen und Ärzte gehen bald in den Ruhestand, zu wenige lassen sich als Hausarzt nieder', 'https://idw-online.de/de/news769524', 'bund'),
  (102, 1, 'Termine und Wege durch das Gesundheitssystem werden kaum gesteuert; knappes Personal wird nicht gezielt eingesetzt', 'https://www.svr-gesundheit.de/publikationen/gutachten-2024/', 'bund'),
