  (1002, 10, 'Steigende Eigenanteile im Heim für Pflege, Ausbildung, Unterkunft und Verpflegung (mit Investitionskosten im ersten Jahr im Schnitt 3.364 Euro im Monat)', 'https://www.vdek.com/presse/pressemitteilungen/2026/stationaere-pflege-eigenanteile-juli-2026.html', 'bund'),
  (1003, 10, 'Die Zahl der Pflegebedürftigen steigt stärker als durch die Alterung allein, auch wegen des 2017 weiter gefassten Pflegebedürftigkeitsbegriffs', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2024/12/PD24_478_224.html', 'bund'),
  (1004, 10, 'Pflegende Angehörige tragen die Hauptlast; Entlastungsangebote werden wenig genutzt', 'https://www.zqp.de/thema/entlastung-pflegende/', 'bund'),
  (1005, 10, 'Die Länder fördern die Investitionskosten der Heime kaum; Bewohner zahlen dafür im Schnitt über 500 Euro im Monat', 'https://www.iges.com/kunden/gesundheit/forschungsergebnisse/2024/investitionskosten-von-pflegeeinrichtungen/index_ger.html', 'land'),
  (1101, 11, 'Lebensmittelpreise hängen stark an den Energiekosten in Landwirtschaft, Transport, Lagerung und Dünger; nach dem Preisschub ab 2021 steigen sie mit dem Energiepreisschock 2026 voraussichtlich erneut', 'https://publikationen.bundesbank.de/publikationen-de/berichte-studien/monatsberichte/monatsbericht-juni-2026-998608?article=deutschland-prognose-energiepreisschock-treibt-teuerung-an-und-bremst-die-konjunkturerholung-998836', 'bund'),
  (1102, 11, 'Der Lebensmittelhandel ist stark konzentriert: Vier Handelsgruppen haben rund 87 % des Umsatzes, und die Preisaufschläge in der Lieferkette sind zeitgleich mit der Konzentration gestiegen', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Sondergutachten/Monopolkommission-Sondergutachten-84-2025-Wettbewerb-in-der-Lebensmittellieferkette.pdf#page=12', 'bund'),
  (1103, 11, 'Die Löhne hielten mit den Preisen lange nicht mit: Die Reallöhne sanken von 2020 bis 2023 und erreichten 2025 erst wieder fast das Niveau von 2019', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/02/PD26_068_62321.html', 'bund'),
  (1104, 11, 'Hohe Steuern und Sozialabgaben auf Arbeit: Bei einem alleinstehenden Durchschnittsverdiener gehen 49,3 % der Arbeitskosten an Staat und Sozialversicherung, der zweithöchste Wert in der OECD (2025)', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2026/04/taxing-wages-2026-country-notes_491a0e97/germany_649f0784/ca03c391-en.pdf', 'bund'),
  (1105, 11, 'Rund 6,3 Millionen Jobs (16 %) liegen im Niedriglohnbereich, vor allem in Gastgewerbe, Landwirtschaft und Kultur (April 2025)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/12/PD25_434_623.html', 'bund'),
  (1201, 12, 'Viele Autobahnbrücken sind marode, ihre Modernisierung liegt weit hinter dem Plan: Bis Ende 2024 war nur 40 % des Vorgesehenen geschafft; der Autobahn GmbH fehlen Personal und Mittel', 'https://www.bundesrechnungshof.de/SharedDocs/Kurzmeldungen/DE/2025/brueckenmodernisierung/kurzmeldung.html', 'bund'),
  (1202, 12, 'Die Kommunen schieben bei Straßen und Verkehrswegen einen Sanierungsstau von rund 54 Mrd. Euro vor sich her', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land'),
  (1203, 12, 'Bauvorhaben kommen schleppend voran: Kommunen setzen nur rund zwei Drittel ihrer geplanten Investitionen um; es fehlt Personal, Genehmigung und Vergabe sind aufwendig', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land'),
  (1204, 12, 'Radfahren ist gefährlicher geworden: 2025 starben 462 Radfahrende, 20,6 % mehr als 2015, vor allem Ältere auf Pedelecs; Unfallgegner ist meist ein Auto', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/04/PD26_N025_461.html', 'land'),
  (1301, 13, 'Glasfaser reicht erst zu rund 43 % der Haushalte (2025); wo sich der Ausbau nicht lohnt, vor allem auf dem Land, braucht es Förderung, die teuer ist und privaten Ausbau teils verdrängt', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'bund'),
  (1302, 13, 'Rund 2 % der Fläche haben gar keinen Mobilfunk mit 4G oder 5G, vor allem in Wäldern, Höhenlagen, Schutz- und Grenzgebieten', 'https://bmds.bund.de/aktuelles/pressemitteilungen/detail/mobilfunkversorgung-uebersicht-zu-weissen-flecken', 'bund'),
  (1401, 14, 'Online-Angebote der Verwaltung sind schwer zu finden und oft nicht durchgängig digital: Digitale Anträge werden nicht schneller bearbeitet, nur 15 % sehen ihre Erwartungen erfüllt (2025)', 'https://initiatived21.de/presse/egovernment-monitor-2025-wie-die-digitale-verwaltung-helfen-kann-staatsvertrauen-zurueckzugewinnen', 'land'),
  (1402, 14, 'Der Verwaltung fehlt Personal: Bis 2030 geht fast ein Drittel der Beschäftigten im öffentlichen Dienst in den Ruhestand', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=35', 'land'),
  (1403, 14, 'Behörden tauschen Daten kaum aus: Register sind nicht vernetzt, Menschen müssen dieselben Angaben und Nachweise immer wieder einreichen', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=55', 'bund'),
  (1404, 14, 'Die Verwaltung ist mit Aufgaben und kleinteiligen Vorschriften überladen: Die Kommunen beklagen einen ungebremsten Aufgabenanstieg und zu viele Detailvorschriften', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=49', 'bund'),
  (1501, 15, 'Der Spritpreis hängt am Weltmarkt für Rohöl: Mit dem Krieg im Iran und der zeitweisen Sperrung der Straße von Hormus stiegen die Preise 2026 binnen Wochen teils um mehr als ein Drittel', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=2', 'bund'),
  (1502, 15, 'Steuern und Abgaben machen einen großen Teil des Spritpreises aus: Energiesteuer (65,45 Cent je Liter Benzin, 47,04 Cent Diesel), CO₂-Preis und Mehrwertsteuer', 'https://www.bundestag.de/resource/blob/834634/dfae7d2604f66510d0469c84eee9e6b5/WD-4-030-21-pdf-data.pdf', 'bund'),
  (1503, 15, 'Wenig Wettbewerb bei Raffinerien und Großhandel: Preissenkungen kommen nicht vollständig an der Zapfsäule an, in Deutschland stiegen die Preise 2026 besonders stark', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'bund'),
  (1504, 15, 'Elektroautos sind für viele noch zu teuer: Gut die Hälfte der Haushalte ohne Elektroauto nennt den Preis als Hindernis (2026: 52 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=23', 'bund'),
  (1505, 15, 'Wer in einem Mehrparteienhaus wohnt, kann oft nicht zu Hause laden: Die rund 9 Millionen Stellplätze an 21 Millionen Wohnungen sind bisher nur unzureichend mit Lademöglichkeiten ausgestattet', 'https://www.bmv.de/SharedDocs/DE/Pressemitteilungen/2026/021-schnieder-500-millionen-foerderung-ladeinfrastruktur-mehrfamilienhaeuser.html', 'bund'),
  (1601, 16, 'Viele halten den Umstieg für nicht lohnend oder können ihn nicht bezahlen: 43 % der Interessierten zweifeln an der Wirtschaftlichkeit einer Wärmepumpe, 32 % fehlt das Geld (2026)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=19', 'bund'),
  (1602, 16, 'Die Regeln für neue Heizungen wurden in wenigen Jahren mehrfach grundlegend geändert (zuletzt Gebäudemodernisierungsgesetz, Juli 2026), dazu kommt ab 2028 ein europäischer CO₂-Preis für Heizöl und Gas', 'https://www.bundesregierung.de/breg-de/aktuelles/neues-gebaeudemodernisierungsgesetz-2430284', 'bund'),
  (1603, 16, 'Viele wissen noch nicht, ob Fernwärme oder ein Wärmenetz kommt: Erst 26 % der Gemeinden haben ihre Wärmeplanung abgeschlossen (Juni 2026)', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'land'),
  (1604, 16, 'Mieterinnen und Mieter können über die Heizung nicht entscheiden, tragen aber die Heizkosten: Sie nutzen fast viermal seltener klimafreundliche Technik als Eigenheimbesitzer (15 % zu 59 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=5', 'bund'),
  (1701, 17, 'Der Betreuungsbedarf der Eltern übersteigt das Angebot bei unter Dreijährigen: 2025 wünschten 49,3 % einen Platz, 37,8 % nutzten ein Angebot (Lücke im Westen 12,7, im Osten 5,8 Prozentpunkte)', 'https://www.akjstat.tu-dortmund.de/themen/kindertagesbetreuung-bis-zum-schuleintritt/weiterhin-ungedeckte-platzbedarfe-kindertagesbetreuung-kompakt-ausbaustand-und-bedarf-2025-erschienen', 'land'),
  (1702, 17, 'Das Personal reicht oft nicht für die Kinderzahl: Mehr als jede zweite Kita-Leitung befürchtet, dass Personalmangel gute Betreuung erschwert, fast 80 % nennen Fehlzeiten als Einschränkung (2024)', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1677-gut-ausgebildet-und-gestresst.html', 'land'),
  (1703, 17, 'Der Personalschlüssel liegt oft unter wissenschaftlichen Empfehlungen: 2022 wurden in Ostdeutschland fast 90 % der Kita-Kinder in nicht kindgerecht besetzten Gruppen betreut (Westen: 62 %)', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'land'),
  (1704, 17, 'Kitas schließen immer wieder ungeplant: 2023/24 erlebten 43 % der Familien mit Kita-Kindern unerwartete Schließtage, bei rund 13 % summierten sie sich auf mehr als eine Woche im Kita-Jahr', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1730-unerwartete-kita-schliessungen-gehen-mit-verstaerkten-zweifeln-an-der-qualitaet-einher.html', 'land'),
  (1705, 17, 'Viele Eltern sehen bei den Kosten Verbesserungsbedarf: Bei unter Dreijährigen nennen 37 % „viel Bedarf“ bei den Elternbeiträgen, bei Älteren 24 % (Erhebung 2022)', 'https://doi.org/10.36189/DJI202606', 'land')
on conflict (id) do update set thema_id = excluded.thema_id, beschreibung = excluded.beschreibung,
  quelle_url = excluded.quelle_url, ebene = excluded.ebene;

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf) values
  (2001, 2, 11, null, 'Bauordnungsrecht entschlacken, Gebäudetyp E, befristete Ausnahmen vom Planungsrecht in angespannten Wohnungsmärkten', '{201,203,205}', 2, 2, null, 'Senkt Baukosten und beschleunigt Planung; Bauordnungen sind Ländersache, die Wirkung hängt daher auch von den Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true),
  (2002, 2, 11, null, 'Mehr Bauland: Brach- und Konversionsflächen sowie bundeseigene Grundstücke für den Wohnungsbau nutzen', '{201,205}', 2, 2, null, 'Mehr verfügbare Flächen erleichtern Neubau in Wachstumsregionen; Umfang und Tempo hängen von Kommunen und Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true),
  (2003, 2, 11, null, 'Keine neuen kostentreibenden Standards (Baukostenmoratorium), Genehmigungsverfahren digitalisieren und beschleunigen', '{203}', 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true),
  (2004, 2, 11, null, 'Höhere befristete Sonderabschreibung und degressive Abschreibung für bezahlbaren Mietwohnungsbau in angespannten Märkten', '{201}', 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true),
  (2005, 2, 11, null, 'Sozialen Wohnungsbau solide fördern und Wohngeld regelmäßig anpassen', '{201,202,206}', 1, 3, null, 'Hält bestehende Instrumente aufrecht, ohne Umfang oder Ausbau zu beziffern; Wohngeld entlastet, schafft aber keine Wohnungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'belegt', '2026-09-27', false, true),
  (2006, 2, 11, null, 'Steuerliche Nachteile für Vermieter abschaffen, die weniger als die ortsübliche Vergleichsmiete verlangen', '{202}', 1, 3, null, 'Setzt einen kleinen Anreiz für günstige Mieten, vor allem bei privaten Vermietern; die Wirkung auf das Mietniveau ist begrenzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-09-27', false, true),
  (2011, 2, 12, null, 'Mietpreisbremse unbefristet verlängern, auf Wohnungen bis Baujahr 2019 ausweiten und Umgehung über möblierte oder befristete Angebote verhindern', '{202}', 2, 2, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen. Eine unbefristete Geltung ist verfassungsrechtlich weniger abgesichert als die befristete.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-27', false, true),
  (2012, 2, 12, null, 'Mieterhöhungen im Bestand in angespannten Märkten auf 6 % in drei Jahren begrenzen, Indexmieten deckeln', '{204}', 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt Mieterhöhungen im Bestand."}}'::jsonb, 'Begrenzt Erhöhungen in laufenden Mietverträgen spürbar, vor allem in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'gemischt', '2026-09-27', false, true),
  (2013, 2, 12, null, 'Sozialen Wohnungsbau stärken; Wohnungsgesellschaften und Genossenschaften über einen Deutschlandfonds mit Eigenkapital ausstatten', '{201,206}', 2, 2, null, 'Mehr Kapital für gemeinwohlorientierte Bauherren kann das Angebot günstiger Wohnungen erhöhen; erfordert erhebliche öffentliche Mittel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'offen', '2026-09-27', false, true),
  (2014, 2, 12, null, 'Baukosten senken: Gebäudetyp E weiterentwickeln, serielles und modulares Bauen fördern, Bauverwaltung digitalisieren', '{203}', 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'gemischt', '2026-09-27', false, true),
  (2015, 2, 12, null, 'Neue bundeseigene Wohnungsgesellschaft gründen', '{201}', 1, 2, null, 'Schafft zusätzliche Wohnungen, laut Programm vor allem für Beschäftigte des Bundes; die Wirkung auf den allgemeinen Markt ist begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-09-27', false, true),
  (2021, 2, 13, null, 'Mietpreisbremse verlängern, Ausnahmen abschaffen, auf Wohnungen älter als fünf Jahre anwenden und Schlupflöcher (möbliert, Ferienwohnung) schließen', '{202}', 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true),
  (2022, 2, 13, null, 'Mietenstopp in angespannten Wohnungsmärkten ermöglichen und Kappungsgrenzen senken', '{204}', 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true),
  (2023, 2, 13, null, 'Mehr Wohnraum im Bestand: Aufstockung, Umwandlung von Büros, Dachausbau; Baurecht vereinfachen, Verfahren digitalisieren, Standards zurückführen', '{201,203,205}', 2, 2, null, 'Nutzt vorhandene Gebäude und senkt Kosten durch einfachere Regeln; wie viele Wohnungen so entstehen, ist unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'gemischt', '2026-09-30', false, true),
  (2024, 2, 13, null, 'Fördermittel für sozialen und gemeinnützigen Wohnungsbau erhöhen, Miet- und Belegungsbindungen unbefristet', '{201,206}', 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', null, 'belegt', '2026-09-27', false, true),
  (2031, 2, 14, null, 'Steuerliche Abschreibungen im Wohnungsbau verbessern, Sonderabschreibung fortführen', '{201}', 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-27', false, true),
  (2032, 2, 14, null, 'Baukostenmoratorium, Bau-Auflagen auf Mindeststandards reduzieren, serielles Bauen mit bundesweiten Standards', '{203}', 2, 2, null, 'Setzt an Vorschriften als Kostentreiber an; Mindeststandards bei Gebäudeenergie sind teils durch EU-Recht vorgegeben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true),
  (2033, 2, 14, null, 'Genehmigungsfiktion für Bauanträge, durchgehend digitale Planung, einfachere Ausweisung neuer Bauflächen', '{201}', 2, 2, null, 'Beschleunigt Verfahren und erweitert das Flächenangebot; Personalmangel in Bauämtern bleibt ein Engpass.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'offen', '2026-09-27', false, true),
  (2034, 2, 14, null, 'Mietpreisbremse auslaufen lassen, um Anreize für Neubau zu setzen', '{201}', 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true),
  (2041, 2, 15, null, 'Gebäudeenergiegesetz abschaffen und kostentreibende EU-Bauvorschriften ablehnen', '{203}', 1, 1, null, 'Senkt einzelne Anforderungen an Neubauten; das Gesetz setzt zum Teil EU-Recht um, eine Abschaffung wäre daher nur eingeschränkt möglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', null, 'offen', '2026-09-27', false, true),
  (2042, 2, 15, null, 'Mehr Wohngeld und zusätzliches kommunales Wohngeld statt sozialem Wohnungsbau', '{202,206}', 1, 2, null, 'Entlastet Haushalte mit geringem Einkommen direkt; schafft keine zusätzlichen Wohnungen, der Verzicht auf sozialen Wohnungsbau verringert das Angebot günstiger Wohnungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=38', null, 'belegt', '2026-09-30', false, true),
  (2043, 2, 15, null, 'Mietpreisbremse und Mietendeckel ablehnen, um Investitionshemmnisse abzubauen', '{201}', 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=39', null, 'gemischt', '2026-09-27', false, true),
  (2051, 2, 16, null, 'Bundesweiter Mietendeckel; besonders hohe Mieten in angespannten Märkten absenken', '{202}', 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true),
  (2052, 2, 16, null, 'Mieterhöhungen bundesweit für sechs Jahre ausschließen; Staffel- und Indexmieten verbieten', '{204}', 2, 1, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen vollständig; ein bundesweiter Stopp über sechs Jahre wirft erhebliche verfassungsrechtliche Fragen auf.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true),
  (2053, 2, 16, null, '20 Milliarden Euro im Jahr für gemeinnützigen Wohnungsbau, Sozialbindung dauerhaft, Investitionen von der Schuldenbremse ausnehmen', '{201,206,205}', 2, 1, null, 'Würde das Angebot dauerhaft günstiger Wohnungen deutlich erhöhen; die Ausnahme von der Schuldenbremse erfordert eine Verfassungsänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'belegt', '2026-09-30', false, true),
  (2054, 2, 16, null, 'Wohnungsbestände von Konzernen mit mehr als 3.000 Wohnungen vergesellschaften', '{202}', 1, 1, null, 'Kann Mieten im übernommenen Bestand dämpfen, schafft aber keine neuen Wohnungen; Entschädigung unter Marktwert ist rechtlich umstritten und teuer.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true),
  (2055, 2, 16, null, 'Leerstand erfassen und mit einer Abgabe von 10 Euro pro Quadratmeter belegen', '{201}', 1, 2, null, 'Kann leerstehende Wohnungen auf den Markt bringen; in angespannten Märkten ist der Leerstand gering, ein großer Teil liegt in schrumpfenden Regionen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true),
  (2056, 2, 16, null, 'Regulierungen beim Neubau überprüfen, soweit sie nur die Preise treiben', '{203}', 1, 3, null, 'Setzt an Vorschriften als Kostentreiber an, bleibt aber allgemein und nennt keine konkreten Regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true),
  (2061, 2, 17, null, 'Gemeinnützigen und kommunalen Wohnungsbau stärken: zinsvergünstigte Kredite, großes Wohnungsbauprogramm, dauerhafte Sozialbindung', '{201,206,205}', 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'belegt', '2026-09-30', false, true),
  (2062, 2, 17, null, 'Bundesweiter Mietendeckel statt Mietpreisbremse', '{202}', 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true),
  (2063, 2, 17, null, 'Mieten in Regionen mit knappem bezahlbarem Wohnraum bis Ende des Jahrzehnts einfrieren; Sanierungskosten tragen die Vermieter', '{204}', 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true),
  (2064, 2, 17, null, 'Bauvorhaben beschleunigen: serielles Bauen vereinfachen, vereinfachtes Genehmigungsverfahren für sozialen Wohnungsbau, überzogene Bauvorschriften prüfen', '{201,203}', 2, 2, null, 'Setzt an Verfahrensdauer und Vorschriften an; wie stark die Kosten sinken, hängt von der Umsetzung in den Ländern ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true),
  (4001, 4, 11, null, 'Entwicklungsstand aller Drei- bis Vierjährigen nach einheitlichen Standards erfassen', '{404}', 1, 2, null, 'Eine frühe Diagnose ist Voraussetzung für Förderung, bewirkt allein aber noch keine. Einheitliche Standards brauchen die Zustimmung der Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true),
  (4002, 4, 11, null, 'Kinder mit Sprachförderbedarf zu einem Vorschulprogramm verpflichten; Bundesprogramm Sprach-Kitas neu starten', '{404}', 2, 2, null, 'Verbindliche Förderung vor der Einschulung setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Die Pflicht müssen die Länder regeln, das Bundesprogramm ist finanzierbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true),
  (4003, 4, 11, null, 'Verbindliche Vergleichsarbeiten und Lernstandserhebungen; bundesweit vergleichbares Abitur', '{403}', 1, 1, null, 'Lernstandserhebungen machen Rückstände sichtbar, beheben sie aber nicht selbst; die Forschung zu Wirkungen von Leistungsvergleichen ist uneinheitlich. Das regeln allein die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true),
  (4004, 4, 11, null, 'Ganztagsangebote für Grundschulkinder ausbauen, mit Schwerpunkt auf Lesen, Schreiben und Rechnen', '{403,405}', 1, 3, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert den Ausbau bereits.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true),
  (4011, 4, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit allen Ländern: mehr Ausbildungsplätze, Quereinstieg, multiprofessionelle Teams', '{401}', 2, 2, null, 'Mehr Ausbildungskapazität und Quereinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Braucht eine Vereinbarung mit allen Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true),
  (4012, 4, 12, null, 'Entwicklungsstand aller Kinder mit vier Jahren und bei der Einschulung feststellen, bei Bedarf verbindliche Förderung', '{404}', 2, 2, null, 'Frühe Feststellung mit verbindlichem Förderangebot setzt direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true),
  (4013, 4, 12, null, 'Startchancenprogramm an Schulen schrittweise ausbauen und eines für Kitas in benachteiligten Lagen schaffen', '{405,403}', 2, 2, null, 'Geld gezielt nach sozialer Lage zu verteilen setzt an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Programms läuft noch, internationale Erfahrungen sind gemischt. Ausbau braucht zusätzliche Mittel von Bund und Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true),
  (4014, 4, 12, null, 'Schuldenregel reformieren, damit Investitionen etwa in Schulgebäude möglich werden; auch Länder sollen Kredite aufnehmen dürfen', '{402}', 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Reform erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', null, 'belegt', '2026-09-28', false, true),
  (4015, 4, 12, null, 'Gesundes, kostenloses Mittagessen für alle Kita-Kinder und Schülerinnen und Schüler, gemeinsam mit den Ländern', '{405}', 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=27', null, 'gemischt', '2026-09-28', false, true),
  (4021, 4, 13, null, '„Zukunftsinvestitionsprogramm Bildung“ mit Ländern und Kommunen, unter anderem für moderne, sanierte Schulgebäude', '{402}', 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'belegt', '2026-09-28', false, true),
  (4022, 4, 13, null, 'Mehr Stellen für Schulsozialarbeit, Schulpsychologie und Inklusion; Schwerpunkt auf Basiskompetenzen', '{403}', 2, 1, null, 'Ein Fokus auf Basiskompetenzen und Unterstützung durch Fachpersonal setzt an Lernrückständen an; die Wirkung multiprofessioneller Teams ist unterschiedlich belegt. Stellen schaffen die Länder, und Fachpersonal ist knapp.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true),
  (4023, 4, 13, null, 'Länder bei der Lehrkräftegewinnung unterstützen: duale Studiengänge, Ein-Fach-Lehrkräfte, Wege für Quer- und Seiteneinstieg', '{401}', 2, 2, null, 'Neue Zugangswege erhöhen das Angebot an Lehrkräften, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true),
  (4024, 4, 13, null, 'Bildungsmittel nach tatsächlichem Bedarf statt nach Königsteiner Schlüssel verteilen; Bildungsoffensive für mehr Schulen', '{405}', 2, 2, null, 'Bedarfsorientierte Verteilung lenkt Mittel zu Schulen mit vielen benachteiligten Kindern; internationale Erfahrungen damit sind gemischt. Braucht Einigung mit den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true),
  (4025, 4, 13, null, 'Sprachförderung als durchgängiger Prozess von der Kita bis in die Ausbildung', '{404}', 1, 2, null, 'Durchgängige Sprachbildung setzt am Förderbedarf an, das Programm nennt aber kein konkretes Instrument wie Tests oder verbindliche Förderung. Umsetzung liegt bei den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'gemischt', '2026-09-28', false, true),
  (4031, 4, 14, null, 'Bundesweit verpflichtende Sprachtests im Vorschulalter; bei Förderbedarf verpflichtende Sprachförderung zwei Jahre vor der Schule', '{404}', 2, 2, null, 'Verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte, ein späterer Schuleintritt ist umstritten. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true),
  (4032, 4, 14, null, 'Startchancen-Programm für Kitas mit vielen sozial benachteiligten Kindern', '{405}', 2, 2, null, 'Gezielte Mittel für Kitas in benachteiligten Lagen setzen früh an der Kopplung von Herkunft und Bildungserfolg an; die Evidenz zu solchen Programmen ist gemischt. Braucht Mittel und Einigung mit den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true),
  (4033, 4, 14, null, 'Sanierung der Schulgebäude; Digitalpakt 2.0 von Bund und Ländern', '{402}', 2, 1, null, 'Die Forderung setzt am Sanierungsstau an, nennt aber weder Umfang noch Finanzierung. Schulbau ist Aufgabe von Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'belegt', '2026-09-28', false, true),
  (4034, 4, 14, null, 'Lehrberuf attraktiver machen: bessere Arbeitsbedingungen, leistungsorientierte Bezahlung, duales Lehramtsstudium, Mobilitätsgarantie', '{401}', 2, 2, null, 'Attraktivere Bedingungen und ein praxisnäheres Studium können mehr Menschen für den Beruf gewinnen, wirken aber erst mittelfristig; die Mobilitätsgarantie verteilt vorhandene Lehrkräfte nur um. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true),
  (4035, 4, 14, null, 'Bundesweit einheitliche Qualitätsstandards von der Kita bis zum Abschluss, Deutschland-Abitur und Notenpflicht ab Klasse 3', '{403}', 1, 1, null, 'Einheitliche Standards und Prüfungen machen Leistungen vergleichbar, beheben Rückstände aber nicht selbst; die Wirkung ist in der Forschung umstritten. Braucht eine Reform des Bildungsföderalismus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'gemischt', '2026-09-28', false, true),
  (4036, 4, 14, null, 'Mehr Eigenständigkeit für Schulen mit frei einsetzbarem Chancenbudget', '{403}', 1, 2, null, 'Mehr Autonomie kann Schulen helfen, auf Rückstände zu reagieren; Studien zeigen positive Effekte vor allem zusammen mit Leistungsvergleichen. Das Budget ist nicht nach sozialer Lage gezielt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true),
  (4041, 4, 15, null, 'Bedarfsorientierte Vorschule, damit alle Kinder dem Unterricht folgen können', '{404}', 2, 2, null, 'Eine Vorschule für Kinder mit Rückständen setzt direkt am Sprachförderbedarf an; Studien zu Vorschulprogrammen zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=160', null, 'gemischt', '2026-09-28', false, true),
  (4042, 4, 15, null, 'Verpflichtender Deutschunterricht für Kinder, die nicht genug Deutsch für den Regelunterricht sprechen', '{404}', 2, 2, null, 'Gezielter Deutschunterricht setzt am Sprachförderbedarf an; ob getrennter oder integrierter Unterricht besser wirkt, ist in der Forschung umstritten. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', null, 'gemischt', '2026-09-28', false, true),
  (4043, 4, 15, null, 'Klassenstärken an allen Schulformen verringern', '{403}', 1, 1, null, 'Kleinere Klassen helfen laut Studien vor allem in den ersten Schuljahren, sonst sind die Effekte gering. Sie brauchen deutlich mehr Lehrkräfte, die schon jetzt fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'gemischt', '2026-09-28', false, true),
  (4044, 4, 15, null, 'Bildungsstandards aller Schulformen anheben statt Leistungsanforderungen zu senken', '{403}', 1, 1, null, 'Höhere Standards benennen ein Ziel, sagen aber nicht, wie Rückstände aufgeholt werden. Die Standards legen allein die Länder in der Kultusministerkonferenz fest.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'offen', '2026-09-28', false, true),
  (4051, 4, 16, null, 'Vertretungsreserve von zehn Prozent; Anerkennung zugewanderter Lehrkräfte und Ausbildung von Quer- und Seiteneinsteigern', '{401}', 2, 2, null, 'Anerkennung und Quereinstieg erhöhen das Angebot an Lehrkräften; eine Vertretungsreserve setzt voraus, dass zusätzliche Lehrkräfte gefunden werden. Umsetzung liegt bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true),
  (4052, 4, 16, null, '100-Milliarden-Euro-Sondervermögen des Bundes für Sanierung und Modernisierung von Bildungseinrichtungen, später Vermögensteuer', '{402}', 2, 1, null, 'Ein großes Investitionsprogramm setzt direkt am Sanierungsstau an. Ein kreditfinanziertes Sondervermögen und die Vermögensteuer sind rechtlich und politisch mit großen Hürden verbunden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'belegt', '2026-09-28', false, true),
  (4053, 4, 16, null, 'Kostenlose Lernmittel, Verpflegung und Schülerbeförderung', '{405}', 1, 2, null, 'Kostenfreiheit entlastet benachteiligte Familien; Wirkungen auf den Schulerfolg sind meist klein. Braucht Mittel von Bund, Ländern und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true),
  (4054, 4, 16, null, 'Hausaufgaben abschaffen, Üben findet in der Schule statt', '{405}', 1, 1, null, 'Üben in der Schule kann Unterschiede durch häusliche Unterstützung verringern; Hausaufgaben haben laut Studien in höheren Klassen aber positive Effekte. Regelungen dazu treffen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true),
  (4055, 4, 16, null, 'Eine ganztägige Gemeinschaftsschule für alle statt des gegliederten Schulsystems', '{405}', 2, 1, null, 'Längeres gemeinsames Lernen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true),
  (4056, 4, 16, null, 'Mehr Pädagoginnen und Pädagogen pro Klasse; Schulpsychologie und Sozialarbeit an jeder Schule', '{403}', 2, 1, null, 'Mehr Personal pro Klasse ermöglicht individuelle Förderung; die Wirkung ist unterschiedlich belegt. Es braucht zusätzliches Personal, das schon jetzt fehlt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true),
  (4057, 4, 16, null, 'Bundesprogramm für Lehrkräfte in Deutsch als Zweitsprache und Sprachkurse auch für Eltern und Geschwister', '{404}', 2, 2, null, 'Mehr qualifizierte Sprachförderung in Schulen und für Familien setzt am Förderbedarf an; Studien zeigen unterschiedlich starke Effekte. Ein Bundesprogramm ist mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true),
  (4061, 4, 17, null, 'Länder bei der Ausbildung von mehr Lehrkräften unterstützen; duale Lehrerausbildung; bessere Bedingungen für Seiteneinsteiger; Entlastung durch Unterstützungsteams', '{401}', 2, 2, null, 'Mehr Ausbildung und Seiteneinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Seiteneinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (4062, 4, 17, null, 'Investitionen unter anderem in Schulen aus der Schuldenbremse ausklammern', '{402}', 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'belegt', '2026-09-29', false, true),
  (4063, 4, 17, null, 'Investitionsprogramm „Kinder und Bildung“ für marode Bildungs- und Betreuungseinrichtungen in Städten und Gemeinden', '{402}', 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'belegt', '2026-09-29', false, true),
  (4064, 4, 17, null, 'Verpflichtender Deutschtest ab drei Jahren; bei Defiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung', '{404}', 2, 2, null, 'Frühe verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4065, 4, 17, null, 'Ganztagsschulen sowie Hort- und Hausaufgabenbetreuung ausbauen, damit Kinder weniger von der Unterstützung der Eltern abhängen', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert bisher nur den Ganztag an Grundschulen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4066, 4, 17, null, 'Längeres gemeinsames Lernen und ein durchlässiges Schulsystem statt früher Aufteilung nach Klasse 4', '{405}', 2, 1, null, 'Später aufzuteilen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4067, 4, 17, null, 'Grundschule auf Lesen, Schreiben und Rechnen konzentrieren; Handys und Tablets bis Ende der Grundschule aus dem Unterricht', '{403}', 1, 1, null, 'Ein Fokus auf Basiskompetenzen setzt an Lernrückständen an; zur Wirkung von Geräteverboten ist die Forschung uneinheitlich. Das regeln allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4068, 4, 17, null, 'Kostenloses, gesundes Mittagessen in Kitas und Schulen', '{405}', 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (4101, 4, 11, 'ST', 'Verbindliche Sprachstandsfeststellung im vierten Lebensjahr; letztes Kita-Jahr als Vorschuljahr mit Förderung', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (4102, 4, 11, 'ST', 'Unterricht in Mathematik und Deutsch an Grundschulen ausbauen', '{403}', 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (4103, 4, 11, 'ST', 'Schulen in sozial herausfordernden Lagen mit zusätzlichem Personal, Förderangeboten und Ausstattung unterstützen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
  (4104, 4, 11, 'ST', 'Schulen dürfen Vertretungspersonal und Unterstützungskräfte einstellen; Unterstützung in Unterricht und Verwaltung ausbauen', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (4105, 4, 11, 'ST', 'Duales Lehramtsstudium verstetigen und zum Standard ausbauen; Hochschulen an Absolventenzahlen messen', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4106, 4, 11, 'ST', 'Zulage für Referendare außerhalb der Oberzentren; Stipendium für Lehramtsstudierende; Wege für Seiteneinsteiger', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4107, 4, 11, 'ST', 'Klare Aus- und Fortbildungswege für Seiteneinsteigerinnen und Seiteneinsteiger', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4111, 4, 12, 'ST', 'Landesschulbauprogramm', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'belegt', '2026-09-29', false, true),
  (4112, 4, 12, 'ST', 'Mehr Zeit im Stundenplan für Rechnen, Lesen, Vorlesen, Üben und Wiederholen', '{403}', 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (4113, 4, 12, 'ST', 'Duales Studium und Praxisanteile in der Lehramtsausbildung ausbauen; 1.200 Studienplätze halten', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (4114, 4, 12, 'ST', 'Seiteneinsteigende qualifiziert begleiten und fair bezahlen', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (4115, 4, 12, 'ST', 'Multiprofessionelle Teams mit Fachkräften für Verwaltung und digitale Ausstattung', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (4116, 4, 12, 'ST', 'Frühere Schuleingangsuntersuchungen und stärkere Sprachförderung', '{404}', 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true),
  (4117, 4, 12, 'ST', 'Gezielte sachliche und personelle Unterstützung für Schulen mit besonderen sozialen Herausforderungen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=19', null, 'gemischt', '2026-09-29', false, true),
  (4118, 4, 12, 'ST', 'Schulsozialarbeit dauerhaft aus Landesmitteln finanzieren und ausbauen', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (4119, 4, 12, 'ST', 'Mittelfristig zwei weiterführende Schulformen: Gymnasium und Gemeinschaftsschule', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'offen', '2026-09-29', false, true),
  (4121, 4, 13, 'ST', 'Umfassendes Schulbauprogramm für Sanierungen; Sofortprogramm für Schultoiletten', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'belegt', '2026-09-29', false, true),
  (4122, 4, 13, 'ST', 'Landesspezifischer Schulsozialindex für die gezielte Verteilung zusätzlicher Mittel', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true),
  (4123, 4, 13, 'ST', 'Landesweit verbindliche Sprachstandsfeststellung in Kitas', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', null, 'gemischt', '2026-09-29', false, true),
  (4124, 4, 13, 'ST', 'Seiteneinsteiger berufsbegleitend qualifizieren; Ein-Fach-Lehrkräfte zulassen', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true),
  (4125, 4, 13, 'ST', 'Lehramtsstudiengänge dauerhaft ausbauen; duales Lehramtsstudium an beiden Universitäten', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true),
  (4126, 4, 13, 'ST', 'Gehaltszuschläge für Lehrkräfte in strukturschwachen Regionen, belasteten Schulformen und Mangelfächern', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true),
  (4127, 4, 13, 'ST', 'Multiprofessionelle Teams und flächendeckend wieder Schulsekretariate', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', null, 'gemischt', '2026-09-29', false, true),
  (4128, 4, 13, 'ST', 'Gemeinsame Grundschulzeit bis Klasse 6; Gemeinschaftsschulen statt Sekundarschulen', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'offen', '2026-09-29', false, true),
  (4129, 4, 13, 'ST', 'Alle allgemeinbildenden Schulen zu Ganztagsschulen; kostenfreie Lernmittel und Mittagessen', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (4130, 4, 13, 'ST', 'An jeder Schule mindestens eine fest angestellte Schulsozialarbeiterin oder ein Schulsozialarbeiter', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true),
  (4131, 4, 14, 'ST', 'Verbindliche Sprachstandsfeststellung mit drei Jahren; Defizite bis Schulbeginn aufholen', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4132, 4, 14, 'ST', 'Verbindliches 1,5-jähriges Qualifizierungsprogramm für Seiteneinsteiger', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (4133, 4, 14, 'ST', 'Zugang zum Lehramtsstudium erweitern, etwa mit Fachhochschulreife; Bewerber mit Berufserfahrung zulassen', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (4134, 4, 14, 'ST', 'Weiterhin Unterstützungskräfte einstellen, um Lehrkräfte zu entlasten', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (4135, 4, 14, 'ST', 'Public-Private-Partnership-Modelle für Bau und Sanierung von Schulen', '{402}', 1, 2, null, 'Private Partner können Bau und Sanierung beschleunigen; Rechnungshöfe fanden solche Projekte aber oft teurer als konventionelle. Das Land kann Kommunen dabei unterstützen, zusätzliches Geld nennt das Programm nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (4136, 4, 14, 'ST', 'Datengestützte Förderung: Lern- und Entwicklungsstände früh erkennen und in Förderung übersetzen', '{403}', 1, 3, null, 'Regelmäßige Lernstandserhebungen machen Rückstände sichtbar; ob sie wirken, hängt von der Förderung danach ab, die Forschung ist uneinheitlich. Das Land kann das selbst einführen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true),
  (4137, 4, 14, 'ST', 'Landeseinheitlicher Schülerkostensatz, der auch einen Sozialindex berücksichtigt', '{405}', 1, 2, null, 'Ein einheitlicher Kostensatz je Schüler mit Sozialindex kann Mittel gerechter verteilen; wie stark er Schulen in schwieriger Lage besserstellt, lässt das Programm offen. Das Land kann das regeln, Mehrkosten sind möglich.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=28', null, 'offen', '2026-09-29', false, true),
  (4141, 4, 15, 'ST', 'Pensionierte und bald pensionierte Lehrkräfte ansprechen, damit sie weiter unterrichten', '{401}', 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true),
  (4142, 4, 15, 'ST', 'Bundesweite Anwerbekampagne für Lehrkräfte; Schulbetrieb entbürokratisieren', '{401}', 1, 2, null, 'Eine Anwerbekampagne kann Lehrkräfte aus anderen Ländern gewinnen; sie konkurrieren aber alle um dieselben knappen Lehrkräfte, die Gesamtzahl steigt nicht. Für das Land umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true),
  (4143, 4, 15, 'ST', 'Pädagogische Hochschule für die Ausbildung aller Grund- und Sekundarschullehrkräfte', '{401}', 1, 2, null, 'Eine Pädagogische Hochschule bündelt die Ausbildung, schafft aber für sich genommen keine zusätzlichen Studienplätze; ob sie mehr Absolventen bringt, ist offen. Die Gründung braucht mehrere Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=84', null, 'offen', '2026-09-29', false, true),
  (4144, 4, 15, 'ST', 'Verbindliche Schullaufbahnempfehlung nach Klasse 4 auf Basis zentraler Klassenarbeiten', '{403}', 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=73', null, 'offen', '2026-09-29', false, true),
  (4145, 4, 15, 'ST', 'Smartphone-Nutzung bis einschließlich Klasse 10 untersagen', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=79', null, 'gemischt', '2026-09-29', false, true),
  (4146, 4, 15, 'ST', 'Mehr Vorlesen in der vorschulischen Bildung', '{404}', 1, 3, null, 'Vorlesen fördert die Sprachentwicklung; ohne Feststellung des Förderbedarfs erreicht es Kinder mit Sprachförderbedarf aber nicht gezielt. Das Land kann das in den Bildungsplan aufnehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=20', null, 'offen', '2026-09-29', false, true),
  (4151, 4, 16, 'ST', 'Lehramtsausbildung in Magdeburg um 200 Erstsemesterplätze erweitern, auch dual mit Bindung ans Land', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (4152, 4, 16, 'ST', 'Seiteneinstieg unterstützen: Entlastung im ersten Jahr, mehr Fortbildung, Vorbereitungsdienst auch mit einem Fach', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (4153, 4, 16, 'ST', 'Schulverwaltungs- und Digitalassistenzen bedarfsdeckend einsetzen', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (4154, 4, 16, 'ST', 'Seminare für den Vorbereitungsdienst in der Fläche; Anwärtersonderbezüge', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (4155, 4, 16, 'ST', 'Schulbauprogramm des Landes und deutlich höhere Finanzzuweisungen an Kommunen für Bau und Sanierung', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=33', null, 'belegt', '2026-09-29', false, true),
  (4156, 4, 16, 'ST', 'Sprachförderung ab der Kita', '{404}', 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', null, 'gemischt', '2026-09-29', false, true),
  (4157, 4, 16, 'ST', 'Schulsozialarbeit gesetzlich verankern: eine Stelle je 150 Schüler, rund 1.200 Vollzeitstellen', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (4158, 4, 16, 'ST', 'Mittelfristig ein Schulsystem aus Gemeinschaftsschulen und Gymnasien', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=31', null, 'offen', '2026-09-29', false, true),
  (4159, 4, 16, 'ST', 'Ganztagsangebote an allen weiterführenden Schulen ausbauen', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (4161, 4, 17, 'ST', 'Mehr Lehramtsstudienplätze; Praxisbezug und duales Lehramtsstudium ausbauen', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true),
  (4162, 4, 17, 'ST', 'Allen Lehramtsabsolventen ein Stellenangebot im Schuldienst machen', '{401}', 1, 3, null, 'Ein sicheres Stellenangebot kann Absolventen im Land halten; die Zahl der Absolventen steigt dadurch nicht. Für das Land umsetzbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true),
  (4163, 4, 17, 'ST', 'Multiprofessionelle Teams mit Verwaltungspersonal, IT-Unterstützung und Lehrerassistenzen als Standard', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (4164, 4, 17, 'ST', 'Verbindliche Sprachstandserhebungen vor Schuleintritt; frühzeitige Sprachförderung ausbauen', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (4165, 4, 17, 'ST', 'Verbindliches Smartphone-Verbot im Schulalltag', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (4166, 4, 17, 'ST', 'Längeres gemeinsames Lernen bis Klasse 6, perspektivisch bis Klasse 8', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'offen', '2026-09-29', false, true),
  (4167, 4, 17, 'ST', 'Mindestens eine Schulsozialarbeiterstelle an jeder Schule', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4168, 4, 17, 'ST', 'Landeseigenes Ganztagsförderprogramm und Qualitätsoffensive „Ganztag 2030“', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (4169, 4, 17, 'ST', 'Kostenfreie, gesunde Verpflegung in Kitas und Schulen', '{405}', 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=49', null, 'gemischt', '2026-09-29', false, true),
  (4201, 4, 11, 'MV', 'Verpflichtende Sprachstandsfeststellung mit vier bis fünf Jahren; bei Bedarf verpflichtende Förderung in Kita oder Vorschulklasse', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (4202, 4, 11, 'MV', 'Ressourcen an Grundschulen nach Problemlagen zuweisen, Schulen in benachteiligten Gebieten stärken', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4203, 4, 11, 'MV', 'Lehrkräfte im Ruhestand für den Wiedereinstieg motivieren', '{401}', 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4204, 4, 11, 'MV', 'Pädagogische Fachkräfte und multiprofessionelle Teams ausbauen; Schulverwaltungsassistenzen', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4205, 4, 11, 'MV', 'Modellstudiengang „Duales Lehramt“; mehr Praxisphasen ab dem ersten Semester', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=55', null, 'gemischt', '2026-09-29', false, true),
  (4206, 4, 11, 'MV', 'Seiten- und Quereinstieg erleichtern, verpflichtende Qualifizierung beibehalten', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=56', null, 'gemischt', '2026-09-29', false, true),
  (4207, 4, 11, 'MV', 'Private Smartphone-Nutzung bis Klasse zehn auf dem gesamten Schulgelände untersagen', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', null, 'gemischt', '2026-09-29', false, true),
  (4208, 4, 11, 'MV', 'Schulsozialarbeit verstetigen und an sozialen Brennpunkten ausbauen', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=50', null, 'gemischt', '2026-09-29', false, true),
  (4209, 4, 11, 'MV', 'Zugang zum Gymnasium nur mit mindestens befriedigenden Leistungen oder Potenzialtest', '{403}', 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true),
  (4210, 4, 11, 'MV', 'Zusätzliche Landesmittel für Schulsanierung neben den laufenden Programmen', '{402}', 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (4211, 4, 12, 'MV', 'Schulbauprogramm (400 Mio. Euro) ausbauen, 600 Mio. Euro aus dem Sondervermögen; bis 2035 möglichst alle Schulen saniert', '{402}', 3, 3, null, 'Ein Schulbauprogramm mit benannter Finanzierung setzt direkt am Sanierungsstau an; ob bis 2035 wirklich alle Schulen saniert sind, hängt von Baukapazitäten und Kommunen ab. Die Mittel aus Landesprogramm und Sondervermögen des Bundes sind eingeplant.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'belegt', '2026-09-29', false, true),
  (4212, 4, 12, 'MV', 'Landeseigener Sozialindex: Personal und Geld dorthin, wo Schüler mehr Unterstützung brauchen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true),
  (4213, 4, 12, 'MV', 'Quer- und Seiteneinstieg in Kooperation mit den Hochschulen ausbauen', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true),
  (4214, 4, 12, 'MV', 'Schulleitungen und Pädagogen durch zusätzliches Verwaltungsfachpersonal entlasten', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true),
  (4215, 4, 12, 'MV', 'Zusätzliche Stunden für Deutsch und Mathematik und das Leseband fortsetzen und ausbauen', '{403}', 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true),
  (4216, 4, 12, 'MV', 'Sprachliche Bildung in Kitas stärken, Sprach-Kitas erhalten und ausbauen', '{404}', 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'gemischt', '2026-09-29', false, true),
  (4217, 4, 12, 'MV', 'Schulen in Gebieten mit besonderen Herausforderungen vorrangig zu gebundenen Ganztagsschulen', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true),
  (4221, 4, 13, 'MV', 'Multiprofessionelle Teams an allen Schulen, auch mit Assistenz für Verwaltungsarbeiten', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene-mv.de/?wpdmdl=33772#page=40', null, 'gemischt', '2026-09-29', false, true),
  (4222, 4, 13, 'MV', 'Mehr Lehramtsabsolventen: Studium praxisnäher, bessere Betreuung im Vorbereitungsdienst', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true),
  (4223, 4, 13, 'MV', 'Stipendienprogramm für Lehramtsstudierende in Mangelfächern', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true),
  (4224, 4, 13, 'MV', 'Längeres gemeinsames Lernen bis Klasse 6, möglichst an einem Standort', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', null, 'offen', '2026-09-29', false, true),
  (4225, 4, 13, 'MV', 'Land beteiligt sich an den Kosten einer hochwertigen Kita- und Schulverpflegung', '{405}', 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', null, 'gemischt', '2026-09-29', false, true),
  (4231, 4, 14, 'MV', 'Lehramtsstudium für alle MINT-Fächer an der Universität Greifswald', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=88', null, 'gemischt', '2026-09-29', false, true),
  (4232, 4, 14, 'MV', 'Schulsanierungen nach landesweiter Priorisierung; kommunale Investitionen beschleunigen', '{402}', 1, 3, null, 'Eine Priorisierung und schnellere Verfahren setzen das vorhandene Geld gezielter ein; zusätzliches Geld für den Sanierungsstau sieht das Programm nicht vor. Für das Land umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=85', null, 'gemischt', '2026-09-29', false, true),
  (4233, 4, 14, 'MV', 'Frühzeitige Sprachförderung für alle Kinder mit Sprachdefiziten, mehr Vorlesen in Kitas', '{404}', 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', null, 'gemischt', '2026-09-29', false, true),
  (4234, 4, 14, 'MV', 'Ressourcen auf Brennpunktschulen, Eingangsklassen und Sprachlernphasen konzentrieren', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true),
  (4235, 4, 14, 'MV', 'An jeder Schule eine Kraft für Schulsozialarbeit', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true),
  (4236, 4, 14, 'MV', 'Haupt- und Realschulen wieder einführen statt Regionaler Schule', '{403}', 1, 2, null, 'Ein stärker gegliedertes Schulangebot soll passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=86', null, 'offen', '2026-09-29', false, true),
  (4241, 4, 15, 'MV', 'Rund 400 abgeordnete Lehrerstellen aus Ministerium, Schulämtern und Institut zurück an die Schulen', '{401}', 2, 2, null, 'Abgeordnete Lehrkräfte zurück in den Unterricht zu holen, erhöht das Angebot sofort spürbar; ihre bisherigen Aufgaben in Verwaltung und Fortbildung müssten dann andere übernehmen. Für das Land umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4242, 4, 15, 'MV', 'Schulverwaltungsassistenten gegen Verwaltungslast', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (4243, 4, 15, 'MV', 'Kurzfristig geeignete Seiteneinsteiger einsetzen', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (4244, 4, 15, 'MV', 'Pädagogische Hochschule mit vergüteter Ausbildung und Übernahmeperspektive', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (4245, 4, 15, 'MV', 'Vorschule mit verbindlichem Lehrplan im letzten Kindergartenjahr', '{404}', 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (4246, 4, 15, 'MV', 'Vorschaltklassen für Kinder ohne ausreichende Deutschkenntnisse', '{404}', 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true),
  (4247, 4, 15, 'MV', 'Aufnahme ins Gymnasium bei Noten schlechter als 2,5 nur über einen Eignungstest', '{403}', 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'offen', '2026-09-29', false, true),
  (4248, 4, 15, 'MV', 'Private Handynutzung bis Klasse 7 per Verordnung unterbinden', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (4249, 4, 15, 'MV', 'Schulsozialarbeit als Landesaufgabe; mehr Schulpsychologen', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (4251, 4, 16, 'MV', '500 Alltagshilfen, 100 Verwaltungsfachkräfte, 100 Psychologen und 300 pädagogische Fachkräfte zusätzlich an Schulen', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true),
  (4252, 4, 16, 'MV', 'Flächendeckende Sprachstandsfeststellung mit viereinhalb Jahren, zusätzliche Sprachfachkräfte, verbindliches Vorschuljahr', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true),
  (4253, 4, 16, 'MV', 'Schulsozialarbeit an jeder Schule', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true),
  (4254, 4, 16, 'MV', '300-Millionen-Euro-Bildungspaket für Personal und individuelle Förderung', '{403}', 1, 2, null, 'Zusätzliches Geld für Personal und individuelle Förderung kann Rückstände verringern; wofür genau es eingesetzt wird, lässt das Programm offen. Die Finanzierung muss das Land im Haushalt sichern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true),
  (4271, 4, 17, 'MV', 'Verbindliche Sprachstandsfeststellung ab vier Jahren mit gezielter Förderung; verpflichtendes Vorschuljahr', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (4272, 4, 17, 'MV', 'Praxisnäheres Lehramtsstudium in Richtung duales Studium, Entlastung im Referendariat, Hilfe bei der Wohnungssuche', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4273, 4, 17, 'MV', 'Multiprofessionelle Teams mit Sozialarbeit, Schulpsychologie und IT-Support', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (4274, 4, 17, 'MV', 'Handys und Tablets aus den Klassenzimmern der Grundschulen verbannen', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (4275, 4, 17, 'MV', 'Kleinere Klassen mit höchstens 24 Schülerinnen und Schülern', '{403}', 1, 2, null, 'Kleinere Klassen können das Lernen verbessern; Studien finden eher kleine Effekte, größere vor allem in den ersten Schuljahren. Braucht zusätzliche Lehrkräfte, sinkende Schülerzahlen helfen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (4276, 4, 17, 'MV', 'Förderunterricht und Kursangebote für Kinder aus benachteiligten Milieus ausbauen', '{405}', 1, 2, null, 'Zusätzlicher Förderunterricht für benachteiligte Kinder kann Rückstände verringern; Studien zu gezielter Förderung in kleinen Gruppen zeigen positive Effekte, das Programm nennt aber keinen Umfang. Braucht zusätzliche Lehrkräftestunden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (4277, 4, 17, 'MV', 'Zugang zum Gymnasium über bindende Laufbahnempfehlung oder Aufnahmeprüfung', '{403}', 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true),
  (4301, 4, 11, 'BE', 'Schulbauoffensive fortführen; Programm für kleinteilige Sanierungen', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=59', null, 'belegt', '2026-09-29', false, true),
  (4302, 4, 11, 'BE', 'Berufsbegleitende Qualifizierung von Quereinsteigern; Ein-Fach-Lehrkraft, Tandemlehrer, Flex-Master', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (4303, 4, 11, 'BE', 'Lehrkräfte verbeamten', '{401}', 1, 2, null, 'Verbeamtung macht den Lehrerberuf im Wettbewerb der Länder attraktiver; die Gesamtzahl der Lehrkräfte steigt dadurch nicht, und die Pensionslasten sind hoch.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (4304, 4, 11, 'BE', 'Freiwillige Ferienschulen zum Aufholen von Rückständen in Lesen, Schreiben und Rechnen', '{403}', 2, 3, null, 'Ferienschulen können Lernrückstände gezielt aufholen; Studien zu Lernferien finden positive Effekte, freiwillige Angebote erreichen aber nicht alle Kinder mit Bedarf. Das Land kann sie selbst organisieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=55', null, 'gemischt', '2026-09-29', false, true),
  (4305, 4, 11, 'BE', 'Vorschule (Kita-Chancenjahr) mit Schwerpunkt Sprachförderung', '{404}', 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', null, 'gemischt', '2026-09-29', false, true),
  (4306, 4, 11, 'BE', 'Landesprogramm Schulsozialarbeit stärken', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (4311, 4, 12, 'BE', 'Verpflichtende Sprachstandsfeststellungen, gezielte Förderung vor der Einschulung', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'gemischt', '2026-09-29', false, true),
  (4312, 4, 12, 'BE', 'Personalzuschlag für Schülerinnen und Schüler nicht deutscher Herkunftssprache wieder einführen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (4313, 4, 12, 'BE', 'Schulbauoffensive fortsetzen, Schwerpunkt auf Sanierung der Bestandsgebäude', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'belegt', '2026-09-29', false, true),
  (4314, 4, 12, 'BE', 'Nichtpädagogisches Personal ausbauen: Verwaltungsleitungen, IT-Personal, Hausmeister', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (4315, 4, 12, 'BE', 'Anerkennung von Lehrkräften mit internationalen Qualifikationen erleichtern', '{401}', 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (4316, 4, 12, 'BE', 'Handyverbot an allen Grundschulen', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (4317, 4, 12, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=39', null, 'offen', '2026-09-29', false, true),
  (4318, 4, 12, 'BE', 'Landesprogramm Schulstationen; mindestens eine Schulsozialarbeiterstelle je Schule', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (4319, 4, 12, 'BE', 'Flex-Ganztag an Grundschulen bis Klasse 6 ausbauen', '{405}', 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (4321, 4, 13, 'BE', 'Nach Hamburger Vorbild verbindliche Förderung nach der Sprachstandserhebung bei Vierjährigen', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=183', null, 'gemischt', '2026-09-29', false, true),
  (4322, 4, 13, 'BE', 'Lehrkräften mit internationalen Abschlüssen den Zugang erleichtern: Ein-Fach-Lehrkraft, einfachere Anerkennung, kostenlose Deutschkurse', '{401}', 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true),
  (4323, 4, 13, 'BE', 'Stipendium für Lehramtsstudierende, die fünf Jahre an unterversorgten Schulen arbeiten', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true),
  (4324, 4, 13, 'BE', 'Teams aus verschiedenen Professionen an allen Schulen', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', null, 'gemischt', '2026-09-29', false, true),
  (4325, 4, 13, 'BE', 'Einstellungskontingente und Mindestausstattung mit qualifizierten Lehrkräften für Schulen in herausfordernden Lagen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true),
  (4326, 4, 13, 'BE', 'Sanierung alter Schulgebäude vorantreiben', '{402}', 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=192', null, 'gemischt', '2026-09-29', false, true),
  (4327, 4, 13, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=187', null, 'offen', '2026-09-29', false, true),
  (4328, 4, 13, 'BE', 'Mehr Schulsozialarbeiterinnen und Schulsozialarbeiter', '{405}', 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=189', null, 'gemischt', '2026-09-29', false, true),
  (4331, 4, 14, 'BE', 'Schulpflichtiges Vorschuljahr in der Kita; verbindliche Sprachstandstests mit drei bis vier Jahren', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', null, 'gemischt', '2026-09-29', false, true),
  (4332, 4, 14, 'BE', 'Personal für die Schulverwaltung verbessern, um Lehrkräfte zu entlasten', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', null, 'gemischt', '2026-09-29', false, true),
  (4333, 4, 14, 'BE', 'Fester Schultag im Lehramtsstudium; langfristig alle Lehramtsstudiengänge dual', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (4334, 4, 14, 'BE', 'Anreize wie Aufstiegsmöglichkeiten für ausgebildete Lehrkräfte an Brennpunktschulen', '{405}', 1, 3, null, 'Anreize für voll ausgebildete Lehrkräfte an Brennpunktschulen setzen an der ungleichen Verteilung an; wie viele Lehrkräfte sich dadurch umentscheiden, ist offen. Für das Land umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (4341, 4, 15, 'BE', 'Pflicht zur Sprachstandsfeststellung und Sprachförderung im Kita-Alter konsequenter umsetzen', '{404}', 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (4342, 4, 15, 'BE', 'Spezialklassen für Kinder mit Sprachförderbedarf („Deutsch-Garantie-Klassen“) ausweiten', '{404}', 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (4343, 4, 15, 'BE', 'Keine weitere Verschiebung geplanter Schulsanierungen und Schulneubauten', '{402}', 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (4344, 4, 15, 'BE', 'Grundschule bildschirmfrei, Smartphone-Verbot', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (4345, 4, 15, 'BE', 'Stipendien für Lehramtsstudienanfänger in Mangelfächern mit Verpflichtung für Berlin', '{401}', 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=38', null, 'gemischt', '2026-09-29', false, true),
  (4346, 4, 15, 'BE', 'Einphasige Lehrerausbildung als duales Studium', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (4347, 4, 15, 'BE', 'Vollständige Lernmittelfreiheit, kostenloses Schulmittagessen beibehalten', '{405}', 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (4351, 4, 16, 'BE', 'Zusätzliche Mittel für die Lehrkräftebildung, Ziel 3.000 Absolventen im Jahr; Kapazitäten gesetzlich am Bedarf ausrichten', '{401}', 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=225', null, 'gemischt', '2026-09-29', false, true),
  (4352, 4, 16, 'BE', 'Quereinstieg öffnen, auch mit nur einem Fach', '{401}', 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=228', null, 'gemischt', '2026-09-29', false, true),
  (4353, 4, 16, 'BE', 'Ausländische Lehramtsabschlüsse leichter anerkennen, Einstellung mit einem Fach, Sprachanforderung C1', '{401}', 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true),
  (4354, 4, 16, 'BE', 'Je Schule eine volle Stelle für Verwaltungsleitung und IT-Administration; mehr Unterrichtshilfen und Schulassistenz', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true),
  (4355, 4, 16, 'BE', 'Schulbauoffensive fortsetzen und beschleunigen', '{402}', 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=169', null, 'belegt', '2026-09-29', false, true),
  (4356, 4, 16, 'BE', 'Handyfreier Schultag bis Klasse 9 als Grundsatz', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=167', null, 'gemischt', '2026-09-29', false, true),
  (4357, 4, 16, 'BE', 'Allen Kindern mindestens 24 Monate Kita vor der Einschulung ermöglichen', '{404}', 1, 2, null, 'Ein längerer Kitabesuch verbessert nachweislich die Sprachkenntnisse bei der Einschulung; ohne Pflicht und gezielte Förderung erreicht er aber nicht sicher alle Kinder mit Bedarf. Braucht zusätzliche Kitaplätze und Fachkräfte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', null, 'gemischt', '2026-09-29', false, true),
  (4358, 4, 16, 'BE', 'Ergänzungsbudget für Schulen in schwieriger Lage fortsetzen, Startchancen-Mittel zielgenau einsetzen', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=157', null, 'gemischt', '2026-09-29', false, true),
  (4359, 4, 16, 'BE', 'Gemeinschaftsschulen deutlich ausbauen, mindestens zwei neue je Bezirk bis 2031', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'offen', '2026-09-29', false, true),
  (4360, 4, 16, 'BE', 'Lernmittelfreiheit und kostenloses Mittagessen auf Mittel- und Oberstufe ausweiten', '{405}', 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'gemischt', '2026-09-29', false, true),
  (4361, 4, 17, 'BE', 'Verbindliche Vorschulphase mit Sprachbildung', '{404}', 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (4362, 4, 17, 'BE', 'Mehrjähriges Förderprogramm für Schulen in Brennpunktlagen mit Mitteln und voll ausgebildetem Personal', '{405}', 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (4363, 4, 17, 'BE', 'Breites Angebot an Gemeinschaftsschulen', '{405}', 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=15', null, 'offen', '2026-09-29', false, true),
  (4364, 4, 17, 'BE', 'Multiprofessionelle Teams mit Fachkräften für IT und Verwaltung', '{401}', 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true),
  (4365, 4, 17, 'BE', 'Smartphones im Unterricht grundsätzlich nicht nutzen und wegschließen', '{403}', 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true),
  (4366, 4, 17, 'BE', 'Sanierungen in klaren Fristen, Hausmeisterwesen für die Wartung', '{402}', 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true),
  (5001, 5, 11, null, 'Stromsteuer für alle senken und Netzentgelte reduzieren', '{501}', 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-29', false, true),
  (5002, 5, 11, null, 'Unternehmensbesteuerung schrittweise auf höchstens 25 Prozent auf einbehaltene Gewinne senken', '{501}', 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=16', null, 'gemischt', '2026-09-29', false, true),
  (5003, 5, 11, null, 'Menschen in Helfertätigkeiten auf dem Weg zur Fachkraft fördern; Anreize für berufliche Qualifikation', '{502}', 1, 2, null, 'Qualifizierung von Geringqualifizierten verbessert ihre Chancen im Strukturwandel; das Programm nennt aber kein konkretes Instrument. Umsetzbar über die Arbeitsförderung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (5004, 5, 11, null, 'Jährliche Gesetze zum Bürokratieabbau, Bürokratiebremse „One in, two out“, Lieferkettengesetz abschaffen', '{505}', 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=17', null, 'gemischt', '2026-09-29', false, true),
  (5005, 5, 11, null, 'Hinzuverdienstgrenzen und Transferentzugsraten reformieren, damit sich Arbeit mehr lohnt', '{506}', 2, 2, null, 'Geringere Anrechnung von Hinzuverdienst setzt direkt an der Ursache an; das ifo/ZEW-Gutachten für das Arbeitsministerium erwartet mehr Beschäftigung. Die Reform ist Bundesrecht, Kosten und Ausgestaltung sind offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'belegt', '2026-09-29', false, true),
  (5011, 5, 12, null, 'Übertragungsnetzentgelte auf 3 Cent pro Kilowattstunde deckeln; abgesenkte Stromsteuer entfristen', '{501}', 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'belegt', '2026-09-29', false, true),
  (5012, 5, 12, null, '„Made in Germany“-Investitionsprämie für bestehende Unternehmen und Neuansiedlungen', '{501}', 1, 2, null, 'Eine Investitionsprämie kann Investitionen vorziehen, setzt aber nicht an den vom Sachverständigenrat genannten Gründen an; Studien finden teils Mitnahmeeffekte. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=8', null, 'gemischt', '2026-09-29', false, true),
  (5013, 5, 12, null, 'Echte Mitbestimmung der Betriebsräte bei Personalplanung und betrieblicher Weiterbildung', '{502}', 1, 3, null, 'Mehr Mitsprache bei Weiterbildung kann Qualifizierung im Betrieb voranbringen, schafft aber selbst keine Weiterbildungsangebote. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (5014, 5, 12, null, 'Mindestlohn spätestens ab 2026 auf 15 Euro; Tarifbindung besonders in Ostdeutschland stärken', '{503}', 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'belegt', '2026-09-29', false, true),
  (5015, 5, 12, null, 'Deutschlandfonds mit anfangs 100 Milliarden Euro für öffentliche und private Investitionen, im Rahmen der Schuldenregel', '{504}', 2, 2, null, 'Ein Investitionsfonds setzt an der Investitionslücke an; wie viel privates Kapital er tatsächlich mobilisiert, ist offen. Über finanzielle Transaktionen ohne Grundgesetzänderung umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=8', null, 'gemischt', '2026-09-29', false, true),
  (5016, 5, 12, null, 'Dokumentations- und Berichtspflichten zusammenführen, vereinfachen und digitalisieren; Praxischeck für neue Gesetze', '{505}', 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=9', null, 'gemischt', '2026-09-29', false, true),
  (5017, 5, 12, null, 'Bundestariftreuegesetz; Allgemeinverbindlicherklärung erleichtern; Verbandsklagerecht für Gewerkschaften', '{507}', 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (5021, 5, 13, null, 'Netzentgelte für überregionale Stromleitungen aus dem Deutschlandfonds zahlen; Stromsteuer auf EU-Minimum senken', '{501}', 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-29', false, true),
  (5022, 5, 13, null, 'Befristete Investitionsprämie von 10 Prozent für alle Unternehmen', '{501}', 1, 2, null, 'Eine Investitionsprämie kann Investitionen vorziehen, setzt aber nicht an den vom Sachverständigenrat genannten Gründen an; Studien finden teils Mitnahmeeffekte. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (5023, 5, 13, null, 'Qualifizierungsgeld weiterentwickeln; selbst gewählte berufliche Weiterbildung sozial absichern', '{502}', 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=19', null, 'gemischt', '2026-09-29', false, true),
  (5024, 5, 13, null, 'Mindestlohn schrittweise erhöhen, zunächst 15 Euro, auch für unter 18-Jährige', '{503}', 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'belegt', '2026-09-29', false, true),
  (5025, 5, 13, null, 'Deutschlandfonds für Investitionen von Bund, Ländern und Kommunen; Reform der Schuldenbremse', '{504}', 2, 2, null, 'Ein Investitionsfonds setzt an der Investitionslücke an; Umfang und Mobilisierung privaten Kapitals sind offen. Der Fonds ist ohne Grundgesetzänderung möglich, die Reform der Schuldenbremse nicht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (5026, 5, 13, null, 'Praxischeck ausweiten; Verwaltungsleistungen für Unternehmen bündeln, Daten nur einmal einreichen (Once-Only)', '{505}', 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (5027, 5, 13, null, 'Steuergutschriften für niedrige Einkommen, auch für Menschen, die mit Bürgergeld aufstocken', '{506}', 1, 2, null, 'Steuergutschriften auf Arbeitseinkommen können Arbeit lohnender machen; wie sie mit der Anrechnung im Bürgergeld zusammenspielen, lässt das Programm offen. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'gemischt', '2026-09-29', false, true),
  (5028, 5, 13, null, 'Allgemeinverbindlicherklärung von Tarifverträgen erleichtern', '{507}', 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'gemischt', '2026-09-29', false, true),
  (5031, 5, 14, null, 'Stromsteuer auf EU-Mindestmaß senken; Netzentgelte umfassend reformieren', '{501}', 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'belegt', '2026-09-29', false, true),
  (5032, 5, 14, null, 'Unternehmenssteuerbelastung unter 25 Prozent: Solidaritätszuschlag abschaffen, Körperschaftsteuer senken', '{501}', 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (5033, 5, 14, null, '„Lebenschancen-BAföG“ für Kursgebühren und bildungsbedingte Auszeiten; Freiraumkonto für Weiterbildung', '{502}', 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (5034, 5, 14, null, 'Steuersenkungen, Bürokratieabbau, Reallabore und Wirtschaftsförderung für kleine und mittlere Unternehmen in Ostdeutschland', '{503}', 1, 2, null, 'Stärkere Unternehmen im Osten können langfristig höhere Löhne ermöglichen; ob allgemeine Entlastungen die Lohnlücke verringern, ist offen. Umsetzbar, Finanzierung offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=12', null, 'gemischt', '2026-09-29', false, true),
  (5035, 5, 14, null, 'Infrastruktur im Rahmen der Schuldenbremse finanzieren, etwa über einen Finanzierungskreislauf Straße', '{504}', 1, 2, null, 'Das Programm erkennt den Investitionsbedarf an, nennt aber weder Umfang noch ein Instrument jenseits der Straße. Im Rahmen der Schuldenbremse umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (5036, 5, 14, null, 'Dreijähriges Bürokratie-Moratorium; ein bürokratiefreies Jahr ohne Berichtspflichten für Betriebe', '{505}', 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=12', null, 'gemischt', '2026-09-29', false, true),
  (5037, 5, 14, null, 'Hinzuverdienstregeln in Grundsicherung und Wohngeld so reformieren, dass sich Arbeit spürbar mehr lohnt', '{506}', 2, 2, null, 'Geringere Anrechnung von Hinzuverdienst setzt direkt an der Ursache an; das ifo/ZEW-Gutachten für das Arbeitsministerium erwartet mehr Beschäftigung. Die Reform ist Bundesrecht, Kosten und Ausgestaltung sind offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=20', null, 'belegt', '2026-09-29', false, true),
  (5041, 5, 15, null, 'CO₂-Abgabe abschaffen, Energiesteuer reduzieren, Stromsteuer auf das Minimum senken', '{501}', 2, 2, null, 'Niedrigere Steuern und Abgaben senken die Energiekosten; die Industrie zahlt ihren CO₂-Preis aber vor allem im EU-Emissionshandel, den Deutschland nicht allein abschaffen kann. Die Gegenfinanzierung ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (5042, 5, 15, null, 'Kohlekraftwerke länger laufen lassen, Wiedereinstieg in die Kernenergie, Nord-Stream-Pipelines reparieren und nutzen', '{501}', 2, 1, null, 'Mehr Angebot und günstigeres Gas könnten Energiekosten senken; neue Kernkraftwerke wirken erst nach vielen Jahren. EU-Sanktionen, die EU-Regeln zum Ausstieg aus russischem Gas und lange Bauzeiten stehen entgegen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (5043, 5, 15, null, 'Unternehmenssteuern auf ein international konkurrenzfähiges Niveau senken', '{501}', 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (5044, 5, 15, null, 'Intensive Beratung, Weiterbildung und Vermittlung schon während des Arbeitslosengeldbezugs', '{502}', 1, 2, null, 'Frühe Beratung und Weiterbildung verbessern die Chancen nach einem Stellenverlust; das Programm nennt aber kein neues Instrument. Umsetzbar über die Arbeitsförderung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
  (5045, 5, 15, null, 'Straßen, Schienen und Brücken planvoll sanieren; Planungs- und Genehmigungsverfahren vereinfachen', '{504}', 1, 2, null, 'Schnellere Verfahren und Sanierung setzen an der Investitionslücke an; das Programm nennt aber keinen Umfang und keine Finanzierung. Umsetzbar per Bundesgesetz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (5046, 5, 15, null, 'Lieferkettengesetz, EU-Lieferkettenrichtlinie und Verpackungsgesetz abschaffen, Nachhaltigkeitsberichte abbauen, Pflichten drastisch reduzieren', '{505}', 2, 1, null, 'Wegfall von Berichtspflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Ein Teil der genannten Pflichten beruht auf EU-Recht, das Deutschland nicht allein ändern kann.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (5047, 5, 15, null, 'Bürgergeldempfänger nach sechs Monaten zu gemeinnütziger Arbeit heranziehen („Aktivierende Grundsicherung“)', '{506}', 1, 2, null, 'Arbeitspflichten erhöhen den Druck, machen zusätzliche Arbeit aber nicht lohnender; Studien zu Arbeitsgelegenheiten finden kaum Effekte auf reguläre Beschäftigung. Umsetzbar per Bundesgesetz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=26', null, 'gemischt', '2026-09-29', false, true),
  (5051, 5, 16, null, 'Neue Netzentgeltstruktur; Stromsteuer auf europäischen Mindeststeuersatz senken', '{501}', 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'belegt', '2026-09-29', false, true),
  (5052, 5, 16, null, 'Industriestrompreis für energieintensive Betriebe aus einem auf 65 Milliarden Euro jährlich ausgebauten Klima- und Transformationsfonds', '{501}', 2, 2, null, 'Ein Industriestrompreis senkt die Energiekosten energieintensiver Betriebe direkt; Ökonominnen und Ökonomen streiten über Kosten und Fehlanreize. Braucht eine beihilferechtliche Genehmigung der EU.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (5053, 5, 16, null, 'Weiterqualifizierungsgeld von 90 Prozent des letzten Gehalts beim Wechsel von Beruf oder Branche', '{502}', 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (5054, 5, 16, null, 'Mindestlohn auf mindestens 15 Euro, spätestens 2026 auf 16 Euro; Tarifbindung stärken – gleicher Lohn in Ost und West', '{503}', 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'belegt', '2026-09-29', false, true),
  (5055, 5, 16, null, 'Schuldenbremse abschaffen, um in Bildung, Brücken, Bus und Bahn und die Wirtschaft zu investieren', '{504}', 2, 1, null, 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=4', null, 'belegt', '2026-09-29', false, true),
  (5056, 5, 16, null, 'Aktionsplan für Tarifbindung, Bundestariftreuegesetz, Allgemeinverbindlicherklärung auch ohne Zustimmung der Arbeitgeberseite', '{507}', 2, 2, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen; die Wirkung ist in Studien begrenzt belegt. Eine Erklärung gegen den Willen der Arbeitgeberseite ist verfassungsrechtlich umstritten (Tarifautonomie).', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'gemischt', '2026-09-29', false, true),
  (5061, 5, 17, null, 'Mit Russland über günstiges Erdgas durch den verbliebenen Nord-Stream-Strang verhandeln', '{501}', 2, 1, null, 'Günstigeres Pipelinegas aus Russland würde Energiekosten senken; die Versorgung wäre aber von einem einzelnen Lieferanten abhängig. EU-Sanktionen, die EU-Regeln zum Ausstieg aus russischem Gas und die fehlende Zertifizierung der Leitung stehen entgegen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (5062, 5, 17, null, 'CO₂-Preis abschaffen', '{501}', 1, 1, null, 'Die Industrie zahlt ihren CO₂-Preis vor allem im EU-Emissionshandel, den Deutschland nicht allein abschaffen kann; die Wirkung auf die Industriekosten ist deshalb gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (5063, 5, 17, null, 'Instandhaltung und Ausbau der Energienetze aus öffentlichen Mitteln statt über den Strompreis finanzieren', '{501}', 2, 1, null, 'Netzentgelte aus dem Strompreis zu nehmen senkt die Energiekosten direkt und deutlich. Die Netzkosten liegen bei vielen Milliarden Euro im Jahr; die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'belegt', '2026-09-29', false, true),
  (5064, 5, 17, null, 'Gesetzlichen Mindestlohn unverzüglich auf 15 Euro anheben', '{503}', 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'belegt', '2026-09-29', false, true),
  (5065, 5, 17, null, 'Investitionen in Infrastruktur aus der Schuldenbremse ausklammern; großes Investitionsprogramm', '{504}', 2, 1, null, 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'belegt', '2026-09-29', false, true),
  (5066, 5, 17, null, 'Nachhaltigkeitsberichterstattung aussetzen, Lieferkettengesetz reformieren, kleine und mittlere Unternehmen von Berichtspflichten befreien', '{505}', 2, 1, null, 'Wegfall von Berichtspflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Ein Teil der genannten Pflichten beruht auf EU-Recht, das Deutschland nicht allein ändern kann.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (5067, 5, 17, null, 'Öffentliche Aufträge und Subventionen nur an Unternehmen mit Tariflohn; Allgemeinverbindlicherklärung erleichtern', '{507}', 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6001, 6, 11, null, 'Asylsuchende an den deutschen Grenzen zurückweisen, wenn sie aus einem EU- oder Schengen-Staat einreisen', '{601,605}', 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6002, 6, 11, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, freiwillige Aufnahmeprogramme beenden', '{601}', 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6003, 6, 11, null, 'Berufsanerkennung vereinfachen, Deutschlernen „on the job“ stärken', '{603}', 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6004, 6, 11, null, 'Arbeitsvermittlung nicht wegen laufender Sprach- oder Integrationskurse aufschieben; Spracherwerb berufsbegleitend', '{603}', 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6005, 6, 11, null, 'Weitere Länder als sichere Herkunftsstaaten einstufen', '{602}', 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6006, 6, 11, null, 'Mehr Rücknahmeabkommen mit den Hauptherkunftsländern', '{604,606}', 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6007, 6, 11, null, 'Unterstützung des Bundes für die Länder bei Reisepapieren und Rückführungen ausbauen', '{604,606}', 2, 3, null, 'Fehlende Reisepapiere sind ein Haupthindernis für Abschiebungen und ein häufiger Grund für lange Duldungen. Der Bund hilft den Ländern dabei schon heute und kann das ausbauen; ob die Herkunftsstaaten Papiere ausstellen, bleibt aber offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6008, 6, 11, null, 'Zentrale Asylverfahren für beschleunigte Verfahren und Bundesausreisezentren', '{602,604}', 1, 2, null, 'Zentrale Einrichtungen können Verfahren und Rückführungen bündeln; ob sie schneller sind, ist nicht untersucht, und an fehlenden Papieren ändern sie nichts. Der Bund müsste die Einrichtungen mit den Ländern aufbauen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-29', false, true),
  (6009, 6, 11, null, 'Bundespolizei darf Ausreisepflichtige in Haft oder Ausreisegewahrsam nehmen', '{604}', 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6010, 6, 11, null, 'Asylverfahren in sicheren Drittstaaten außerhalb Europas', '{601,605}', 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=44', null, 'offen', '2026-09-29', false, true),
  (6011, 6, 12, null, 'Asylverfahren beim Bundesamt und an den Verwaltungsgerichten durch Digitalisierung beschleunigen, Entscheidung in sechs Monaten', '{602}', 2, 2, null, 'Digitalisierung und Verwaltungsmodernisierung setzen an der Verfahrensdauer an; wie viel sie bringen, hängt von der Umsetzung ab. Das Bundesamt steuert der Bund, die Verwaltungsgerichte die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true),
  (6012, 6, 12, null, 'Ausländerbehörden stärken, Datenaustausch verbessern, Verfahren aus einer Hand', '{601}', 1, 2, null, 'Setzt an der Überlastung der Ausländerbehörden an, nennt aber weder Umfang noch Finanzierung. Die Behörden gehören zu Ländern und Kommunen, der Bund kann Datenaustausch und Digitalisierung beisteuern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true),
  (6013, 6, 12, null, 'Integrationskurse ausbauen und ausreichend finanzieren', '{603}', 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true),
  (6014, 6, 12, null, 'Spurwechsel in die Fachkräfteeinwanderung für integrierte, straffreie Menschen ohne Schutzstatus', '{606}', 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true),
  (6015, 6, 12, null, 'Migrationsabkommen mit festen Vereinbarungen zur Rückführung Ausreisepflichtiger', '{604,606}', 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', null, 'gemischt', '2026-09-29', false, true),
  (6016, 6, 12, null, 'Solidarische Verteilung von Schutzsuchenden unter allen EU-Staaten', '{605}', 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-09-29', false, true),
  (6021, 6, 13, null, 'Kommunen mit einer Integrationsoffensive stärker und verlässlicher finanziell unterstützen', '{601}', 1, 2, null, 'Mehr Geld für die Kommunen setzt an der Kapazitätsseite an; das Programm nennt aber weder Umfang noch Weg der Finanzierung. Der Bund beteiligt sich bereits an den Kosten und kann mehr beisteuern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'gemischt', '2026-09-29', false, true),
  (6022, 6, 13, null, 'Ausfinanzierte Integrations- und Sprachkurse direkt nach der Ankunft', '{603}', 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true),
  (6023, 6, 13, null, 'Arbeitsverbote abschaffen; arbeitsbezogene Genehmigungen gelten nach kurzer Frist als erteilt', '{603}', 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true),
  (6024, 6, 13, null, 'Spurwechsel ausgestalten; auf das Chancen-Aufenthaltsrecht weitere Reformen folgen lassen', '{606}', 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=127', null, 'belegt', '2026-09-29', false, true),
  (6025, 6, 13, null, 'Migrationsabkommen: geregelte Migrationswege, dafür nehmen Partnerländer Ausreisepflichtige zurück', '{604,606}', 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=131', null, 'gemischt', '2026-09-29', false, true),
  (6026, 6, 13, null, 'Ausreisepflichtige nach schweren Straftaten vorrangig zurückführen', '{604}', 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'gemischt', '2026-09-29', false, true),
  (6027, 6, 13, null, 'Faire, verbindliche und solidarische Verteilung von Schutzsuchenden in Europa', '{605}', 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'offen', '2026-09-29', false, true),
  (6031, 6, 14, null, 'Zuständigkeit für Abschiebungen beim Bund zentralisieren', '{604}', 1, 1, null, 'Setzt an Vollzugsproblemen in den Ländern an; die Haupthindernisse (fehlende Papiere, Herkunftsstaaten) bleiben. Eine Bundeszuständigkeit für den Vollzug müsste neu geschaffen werden, mit Zustimmung des Bundesrats und je nach Ausgestaltung einer Grundgesetzänderung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true),
  (6032, 6, 14, null, 'Asylverfahren auch in Drittstaaten', '{601,605}', 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true),
  (6033, 6, 14, null, 'Geordnetes Verfahren, um mehr sichere Herkunftsstaaten festzustellen', '{602}', 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6034, 6, 14, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, Aufnahmeprogramme pausieren', '{601}', 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6035, 6, 14, null, 'Zurückweisungen an den deutschen Grenzen modellhaft erproben', '{601,605}', 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6036, 6, 14, null, 'EU-Migrationsabkommen für mehr Rücknahmebereitschaft; bilaterale Migrationspartnerschaften', '{604,606}', 2, 1, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind gemischt. Der Schwerpunkt liegt auf EU-Abkommen, die Deutschland nicht allein schließen kann.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6037, 6, 14, null, 'Spurwechsel für gut integrierte Schutzsuchende, die ohne Transferleistungen leben können', '{606}', 1, 3, null, 'Ein Spurwechsel beendet die Duldung für die, die ihn schaffen; die Bedingung, dass die ganze Familie ohne Transferleistungen lebt, erfüllen aber nur wenige Geduldete. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6038, 6, 14, null, 'Anerkennung ausländischer Abschlüsse beschleunigen und durchgehend digitalisieren', '{603}', 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-29', false, true),
  (6039, 6, 14, null, 'Sprach- und Integrationskurse trennen; Sprachkurse modular und leistungsdifferenziert', '{603}', 1, 3, null, 'Modulare, berufsbegleitende Kurse können den Einstieg in Arbeit erleichtern; dass eine Trennung von Sprach- und Integrationskurs schneller zum Ziel führt, ist nicht untersucht. Die Kurse regelt der Bund.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, 'offen', '2026-09-29', false, true),
  (6040, 6, 14, null, 'Wohnsitzauflage stärker nutzen', '{601}', 1, 3, null, 'Die Wohnsitzauflage verteilt Geflüchtete gleichmäßiger auf die Kommunen und kann Ballungsräume entlasten; Studien finden aber, dass sie die Aufnahme von Arbeit verzögern kann. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true),
  (6041, 6, 15, null, 'Grenzen selbst kontrollieren, illegal Einreisende an der Grenze zurückweisen', '{601,605}', 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'gemischt', '2026-09-29', false, true),
  (6042, 6, 15, null, 'Asylanträge künftig außerhalb Deutschlands stellen und bearbeiten', '{601,605}', 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-09-29', false, true),
  (6043, 6, 15, null, 'Zahl der sicheren Herkunftsstaaten deutlich ausweiten', '{602}', 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true),
  (6044, 6, 15, null, 'Asylverfahren vor den Verwaltungsgerichten straffen, mehr Personal zum Abbau von Altfällen', '{602}', 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'gemischt', '2026-09-29', false, true),
  (6045, 6, 15, null, 'Druck auf nicht rücknahmebereite Herkunftsländer über Wirtschaftssanktionen, Entwicklungshilfe und Visa', '{604,606}', 2, 1, null, 'Druck auf Herkunftsstaaten setzt an deren fehlender Mitwirkung an, einem Haupthindernis für Abschiebungen; die Erfahrungen damit sind gemischt. Wirtschaftssanktionen und der Visahebel liegen bei der EU, nur die Entwicklungshilfe kann Deutschland allein kürzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true),
  (6046, 6, 15, null, 'Haft- und Gewahrsamsplätze in Grenznähe und an Flughäfen ausbauen', '{604}', 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true),
  (6047, 6, 15, null, 'Grundsätzlichen Anspruch auf Familiennachzug zu subsidiär Schutzberechtigten streichen', '{601}', 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true),
  (6048, 6, 15, null, 'Asylsuchende für die Dauer des Verfahrens in zentralen Aufnahmeeinrichtungen unterbringen', '{601}', 1, 2, null, 'Entlastet die Kommunen bei der Unterbringung, verlagert die Last aber auf die Erstaufnahme der Länder; ob die Plätze reichen, ist offen. Die Wohnpflicht regelt der Bund, die Plätze schaffen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'offen', '2026-09-29', false, true),
  (6049, 6, 15, null, 'Bundesprogramme zur Förderung der freiwilligen Rückkehr ausweiten', '{604,606}', 1, 3, null, 'Rückkehrförderung kann Ausreisen erleichtern, auch bei fehlenden Papieren; Studien finden eher begrenzte Effekte. Der Bund finanziert solche Programme bereits.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=109', null, 'gemischt', '2026-09-29', false, true),
  (6050, 6, 15, null, 'Pflicht zum Spracherwerb auf B2-Niveau in der Regel binnen zwei Jahren; Kosten abgebrochener Kurse erstatten', '{603}', 1, 2, null, 'Pflichten und Rückforderungen können den Abschluss von Kursen fördern, verkürzen aber keine Wartezeiten auf Kursplätze; eine Wirkung ist nicht untersucht. Per Bundesgesetz umsetzbar, Rückforderungen sind verwaltungsaufwendig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=110', null, 'offen', '2026-09-29', false, true),
  (6051, 6, 16, null, 'Fonds für Willkommenskommunen; der Bund erstattet die Unterbringungskosten vollständig pro Person', '{601}', 2, 2, null, 'Mehr Bundesgeld setzt an der Kapazitätsseite an, vor allem bei der Unterbringung; Geld allein schafft aber nicht sofort Wohnraum und Personal. Der Bund beteiligt sich bereits mit einer Pauschale, eine volle Erstattung wäre deutlich teurer, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'gemischt', '2026-09-29', false, true),
  (6052, 6, 16, null, 'Uneingeschränkte Arbeitserlaubnis für alle Geflüchteten ab dem Tag der Ankunft', '{603}', 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true),
  (6053, 6, 16, null, 'Flächendeckend kostenlose Sprachkurse für Geflüchtete', '{603}', 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true),
  (6054, 6, 16, null, 'Legalisierung für Menschen ohne Aufenthaltsstatus; wirksame Bleiberechtsregelungen bei Kettenduldungen', '{606}', 2, 3, null, 'Bleiberechtsregelungen beenden lange Duldungen direkt; das Chancen-Aufenthaltsrecht von 2022 zeigt, dass solche Regelungen genutzt werden. Wer genau ein Bleiberecht bekommen soll, lässt das Programm offen. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'belegt', '2026-09-29', false, true),
  (6055, 6, 16, null, 'Europäische Fluchtumlage: EU-Geld für aufnahmebereite Länder, Regionen und Städte', '{605}', 1, 1, null, 'Geld aus EU-Mitteln für aufnahmebereite Regionen könnte die Verteilung freiwillig verbessern; an den gescheiterten Überstellungen setzt es nur indirekt an. Umsetzbar nur mit einem Beschluss auf EU-Ebene.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-09-29', false, true),
  (6061, 6, 17, null, 'Job-Turbo für Ukrainer und andere Geflüchtete mit Schutzstatus umsetzen', '{603}', 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true),
  (6062, 6, 17, null, 'Wer aus einem sicheren Drittstaat einreist, bekommt kein Asylverfahren und keinen Aufenthalt', '{601,605}', 1, 0, null, 'Würde Einreisen über Nachbarstaaten praktisch ausschließen, wenn diese die Menschen zurücknehmen. Die Dublin-Verordnung und das neue europäische Asylsystem verlangen aber eine Prüfung, welcher Staat zuständig ist; ein genereller Ausschluss ist mit dem EU-Recht nicht vereinbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true),
  (6063, 6, 17, null, 'Behörden und Gerichte vorrangig mit Personal ausstatten, Asylverfahren in drei Monaten', '{602}', 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (6064, 6, 17, null, 'Straftäter ausweisen und abschieben, Verfahren dazu vorrangig betreiben', '{604}', 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (6065, 6, 17, null, 'Erwachsenenbildung zum Nachholen von Schulabschlüssen und Nachqualifikation bei abweichenden Berufsausbildungen', '{603}', 2, 2, null, 'Nachqualifizierung setzt an einer Hürde an, die das IAB nennt (Abschlüsse passen nicht zum deutschen System); Studien zeigen positive Effekte. Erwachsenenbildung ist weitgehend Ländersache, der Bund kann über die Arbeitsförderung beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (6066, 6, 17, null, 'Asylverfahren möglichst außerhalb der EU in sicheren Drittstaaten', '{601,605}', 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=38', null, 'offen', '2026-09-29', false, true),
  (6123, 6, 11, 'ST', 'Bezahlkarte für Asylsuchende dauerhaft beibehalten und weiterentwickeln', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true),
  (6124, 6, 11, 'ST', 'Zentrale Erstaufnahme dauerhaft absichern', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true),
  (6125, 6, 11, 'ST', 'Leistungsfähige Ausländerbehörden absichern und weiterentwickeln', '{601}', 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true),
  (6126, 6, 11, 'ST', 'Auf Bundesebene: Asylverfahren an den EU-Außengrenzen, Aufnahmeprogramme beenden, Familiennachzug zu subsidiär Schutzberechtigten weiter aussetzen', '{601}', 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'gemischt', '2026-09-29', false, true),
  (6127, 6, 12, 'ST', 'Kommunen für die Erstintegration ausstatten', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=11', null, 'gemischt', '2026-09-29', false, true),
  (6128, 6, 13, 'ST', 'Ausländerbehörden besser ausstatten und zu Migrationszentren weiterentwickeln', '{601}', 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'offen', '2026-09-29', false, true),
  (6129, 6, 13, 'ST', 'Geflüchtete zügig in private Wohnungen vermitteln', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true),
  (6130, 6, 14, 'ST', 'Ausländerbehörden bei der Digitalisierung unterstützen; Arbeitserlaubnis binnen vier Wochen', '{601}', 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=10', null, 'offen', '2026-09-29', false, true),
  (6131, 6, 15, 'ST', 'Über den Bundesrat stärkere Grenzkontrollen und Zurückweisungen durchsetzen', '{601}', 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6132, 6, 15, 'ST', 'Aufnahme von Personen verweigern, die aus einem sicheren Drittstaat eingereist sind', '{601}', 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'offen', '2026-09-29', false, true),
  (6133, 6, 15, 'ST', 'Aufnahmestopp des Landes als Ultima Ratio', '{601}', 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=31', null, 'offen', '2026-09-29', false, true),
  (6134, 6, 15, 'ST', 'Zuzugsstopps für überforderte Kommunen verhängen (negative Wohnsitzauflage)', '{601}', 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (6135, 6, 15, 'ST', 'Asylbewerber in zentralen Unterkünften unterbringen', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=33', null, 'offen', '2026-09-29', false, true),
  (6136, 6, 15, 'ST', 'Sachleistungsprinzip konsequent anwenden', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=35', null, 'offen', '2026-09-29', false, true),
  (6137, 6, 16, 'ST', 'Aufnahmegesetz reformieren; Integrationsbudget mit Mitteln für die Kommunen', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=97', null, 'gemischt', '2026-09-29', false, true),
  (6138, 6, 17, 'ST', 'Unterbringungskosten der Kommunen durch den Bund übernehmen lassen', '{601}', 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', null, 'gemischt', '2026-09-29', false, true),
  (6139, 6, 11, 'MV', 'Missbrauch der Bezahlkarte beenden', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=37', null, 'offen', '2026-09-29', false, true),
  (6140, 6, 13, 'MV', 'Gemeinschaftsunterkünfte reduzieren, dezentrales Wohnen stärken', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6141, 6, 14, 'MV', 'Menschen ohne Bleibeperspektive in den Erstaufnahmeeinrichtungen belassen', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true),
  (6142, 6, 14, 'MV', 'Landesweit einheitliche Bezahlkarte umsetzen und beibehalten', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=143', null, 'offen', '2026-09-29', false, true),
  (6143, 6, 14, 'MV', 'Ausländerbehörden personell und organisatorisch stärken', '{601}', 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true),
  (6144, 6, 15, 'MV', 'Landesweiten Aufnahmestopp als Option', '{601}', 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true),
  (6145, 6, 15, 'MV', 'Den Bund zu echtem Grenzschutz drängen', '{601}', 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (6146, 6, 15, 'MV', 'Asylbewerber in wenigen großen Unterkünften unterbringen', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true),
  (6147, 6, 15, 'MV', 'Sachleistungsprinzip maximal ausweiten', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=52', null, 'offen', '2026-09-29', false, true),
  (6148, 6, 16, 'MV', 'Dezentrale Unterbringung priorisieren; Kommunen bei der Wohnraumversorgung Geflüchteter unterstützen', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (6149, 6, 17, 'MV', 'Geflüchtete nach der tatsächlichen Leistungsfähigkeit der Kommunen verteilen', '{601}', 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true),
  (6150, 6, 17, 'MV', 'Unterbringung verlässlich durch Land und Bund finanzieren', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true),
  (6151, 6, 17, 'MV', 'Asylverfahren an den EU-Außengrenzen oder in sicheren Drittstaaten unterstützen', '{601}', 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=73', null, 'gemischt', '2026-09-29', false, true),
  (6152, 6, 11, 'BE', 'Asylbewerber vom ersten Tag bis zur Entscheidung über den Asylantrag in zentralen Einrichtungen unterbringen', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true),
  (6153, 6, 11, 'BE', 'Bezahlkarte dauerhaft etablieren', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true),
  (6154, 6, 12, 'BE', 'Weg von Notunterkünften: dezentrales Wohnen, Geflüchtetenwohnen ausbauen, alle Bezirke beteiligen', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true),
  (6155, 6, 12, 'BE', 'Gemeinschaftspauschale je Geflüchteten und Bezirk stärken', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true),
  (6156, 6, 13, 'BE', 'Unterbringung vorrangig in Wohnungen und kleineren Gemeinschaftsunterkünften in allen Bezirken', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=145', null, 'gemischt', '2026-09-29', false, true),
  (6157, 6, 13, 'BE', 'Jährliche Pauschale je Unterbringungsplatz für die Bezirke', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6158, 6, 13, 'BE', 'Senatskommission Unterbringung soll neue Standorte zügig festlegen', '{601}', 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'gemischt', '2026-09-29', false, true),
  (6159, 6, 13, 'BE', 'Landesamt für Einwanderung stärken, digitales Antragssystem für alle Aufenthaltstitel', '{601}', 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'offen', '2026-09-29', false, true),
  (6160, 6, 14, 'BE', 'Bezahlkarte für Geflüchtete sofort einführen', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'offen', '2026-09-29', false, true),
  (6161, 6, 14, 'BE', 'Bei guter Bleibeprognose dezentrale Unterbringung in Wohnungen („Leverkusener Modell“)', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'gemischt', '2026-09-29', false, true),
  (6162, 6, 15, 'BE', 'Sofortiger Aufnahmestopp für Asylbewerber in Berlin', '{601}', 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=22', null, 'offen', '2026-09-29', false, true),
  (6163, 6, 15, 'BE', 'Umstellung auf reine Sachleistungen', '{601}', 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true),
  (6164, 6, 15, 'BE', 'Freie Plätze in bestehenden Unterkünften voll belegen; zentrale Unterbringung von Personen mit geringen Anerkennungschancen', '{601}', 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true),
  (6165, 6, 16, 'BE', 'Bezirke verpflichten, Flächen für Gemeinschaftsunterkünfte bereitzustellen; leer stehende Gebäude aktivieren', '{601}', 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true),
  (6166, 6, 16, 'BE', 'Mehr Geflüchtete über Kooperationsverträge mit landeseigenen Wohnungsbaugesellschaften in eigenen Wohnraum vermitteln', '{601}', 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true),
  (6167, 6, 16, 'BE', 'Infrastrukturprämien für die Bezirke je untergebrachter Person', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true),
  (6168, 6, 16, 'BE', 'Vom Bund eine Personenpauschale für die Unterbringungskosten fordern', '{601}', 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=285', null, 'gemischt', '2026-09-29', false, true),
  (6169, 6, 17, 'BE', 'Grenzkontrollen und Zurückweisungen an den deutschen Grenzen unterstützen', '{601}', 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6170, 6, 17, 'BE', 'Asylbewerber stärker auf die umliegenden Bundesländer verteilen', '{601}', 1, 1, null, 'Eine andere Verteilung zwischen den Ländern würde Berlin entlasten, verschiebt den Bedarf aber nur; den Verteilschlüssel (Königsteiner Schlüssel) legen Bund und Länder gemeinsam fest, Berlin kann ihn nicht allein ändern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'offen', '2026-09-29', false, true),
  (6171, 6, 17, 'BE', 'Bezirke, die bisher am meisten geleistet haben, bei der Verteilung entlasten', '{601}', 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6172, 6, 17, 'BE', 'Ansiedlung mit einem Infrastrukturzuschuss für den Bezirk verbinden', '{601}', 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6183, 7, 11, null, 'Aktivrente: Arbeitslohn nach Erreichen der Regelaltersgrenze bis 2.000 Euro im Monat steuerfrei', '{701}', 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6184, 7, 11, null, 'Kleine und mittlere Arbeitgeber beim Abschluss von Betriebsrenten unterstützen', '{703}', 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6185, 7, 11, null, 'Frühstart-Rente: 10 Euro im Monat vom 6. bis 18. Lebensjahr in ein kapitalgedecktes Altersvorsorgedepot', '{703}', 1, 3, null, '10 Euro im Monat ergeben bis zum Rentenalter nur einen kleinen Zusatzbetrag, und die Wirkung setzt erst in Jahrzehnten ein; das Depot kann aber den Einstieg in eigene Vorsorge erleichtern. Per Bundesgesetz umsetzbar, die Kosten sind überschaubar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6186, 7, 11, null, 'Verbindliche Altersvorsorge für nicht ausreichend abgesicherte Selbstständige', '{702}', 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6187, 7, 12, null, 'Rentenniveau dauerhaft bei mindestens 48 Prozent sichern', '{701}', 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6188, 7, 12, null, 'Weiterarbeit nach Rentenbeginn: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6189, 7, 12, null, 'Langfristig alle Erwerbstätigen in die gesetzliche Rente einbeziehen', '{701}', 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6190, 7, 12, null, 'Zunächst alle Selbstständigen absichern', '{702}', 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6191, 7, 12, null, 'Steuerliche Förderung der Betriebsrente für Geringverdiener ausbauen', '{703}', 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6192, 7, 12, null, 'Förderung privater Vorsorge nur für Produkte mit gedeckelten Kosten, konzentriert auf kleine und mittlere Einkommen', '{703}', 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true),
  (6193, 7, 12, null, 'Mindestlohn spätestens 2026 auf 15 Euro', '{702}', 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6194, 7, 13, null, 'Rentenniveau bei mindestens 48 Prozent halten', '{701}', 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true),
  (6195, 7, 13, null, 'Grundrente zu einer Garantierente nach 30 Versicherungsjahren weiterentwickeln', '{702}', 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true),
  (6196, 7, 13, null, 'Mehr Beitragszahlende durch höhere Erwerbstätigkeit von Frauen und qualifizierte Zuwanderung', '{701}', 2, 2, null, 'Eine höhere Erwerbstätigkeit, vor allem von Frauen, und Zuwanderung in Arbeit gelten in Studien als wichtigste Hebel gegen das sinkende Verhältnis von Beitragszahlenden zu Rentnern; das Programm nennt aber keine Größenordnung. Kitaausbau und Integration brauchen Länder, Kommunen und Zeit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'belegt', '2026-09-29', false, true),
  (6197, 7, 13, null, 'Mindestlohn erneut anheben, Minijobs abbauen', '{702}', 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true),
  (6198, 7, 13, null, 'Gesetzliche Rente zur Bürgerversicherung: Abgeordnete und perspektivisch Beamte einbeziehen', '{701}', 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true),
  (6199, 7, 13, null, 'Nicht anderweitig abgesicherte Selbstständige einbeziehen', '{702}', 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true),
  (6200, 7, 13, null, 'Weiterarbeit neben dem Rentenbezug: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true),
  (6201, 7, 13, null, 'Ergänzende Kapitaldeckung in der gesetzlichen Rente aus Bundesmitteln (Bürger*innenfonds)', '{701}', 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true),
  (6202, 7, 13, null, 'Öffentlich verwalteter Bürger*innenfonds für die private Vorsorge mit Widerspruchslösung', '{703}', 2, 2, null, 'Automatische Teilnahme mit Widerspruchsrecht hat in Großbritannien und Neuseeland die Beteiligung an Zusatzvorsorge stark erhöht; wie hoch die Zusatzrente wird, hängt von den Beiträgen ab. Der öffentliche Fonds muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'belegt', '2026-09-29', false, true),
  (6203, 7, 13, null, 'Bürger*innenfonds auch für Betriebsrenten öffnen, vor allem für kleine und mittlere Unternehmen', '{703}', 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=99', null, 'gemischt', '2026-09-29', false, true),
  (6204, 7, 14, null, 'Flexibler Renteneintritt nach schwedischem Vorbild mit Zu- und Abschlägen', '{701}', 1, 3, null, 'Ein flexibler Renteneintritt mit fairen Zu- und Abschlägen kann längeres Arbeiten attraktiver machen; wie viele dadurch später in Rente gehen, ist unsicher, wer früher geht, bekommt weniger. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6205, 7, 14, null, 'Gesetzliche Aktienrente: kleiner Teil der Rentenbeiträge in einen unabhängig verwalteten Fonds', '{701}', 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6206, 7, 14, null, 'Steuerlich gefördertes Altersvorsorgedepot für die private Vorsorge', '{703}', 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6207, 7, 14, null, 'Reine Beitragszusage allen Betrieben ermöglichen, vor allem Kleinstbetrieben', '{703}', 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6208, 7, 15, null, 'Verbeamtung nur für Hoheitsaufgaben, Politiker in die gesetzliche Rente', '{701}', 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true),
  (6209, 7, 15, null, 'Alle nicht beitragsgedeckten Leistungen aus dem Bundeshaushalt finanzieren', '{701}', 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true),
  (6210, 7, 15, null, 'Elternschaft in der Rente höher bewerten', '{702}', 1, 2, null, 'Höhere Rentenansprüche für Eltern gleichen Lücken im Erwerbsleben durch Kindererziehung teilweise aus; das Programm nennt weder Umfang noch Finanzierung. Per Bundesgesetz umsetzbar, zuletzt bei der Mütterrente mit hohen Kosten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6211, 7, 15, null, 'Private und betriebliche Vorsorge mit Aktien, ETFs und Fonds systematisch steuerlich fördern', '{703}', 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6212, 7, 15, null, 'Junior-Spardepot: 100 Euro im Monat aus Steuermitteln bis zum 18. Lebensjahr für jedes Kind mit deutscher Staatsangehörigkeit', '{703}', 2, 1, null, '100 Euro im Monat über 18 Jahre ergeben einen spürbaren Kapitalstock für das Alter; die Kosten von grob 15 Milliarden Euro im Jahr sind nicht gegenfinanziert, und die Beschränkung auf deutsche Kinder ist verfassungsrechtlich fraglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'offen', '2026-09-29', false, true),
  (6213, 7, 15, null, 'Zusätzlicher Steuerfreibetrag von 12.000 Euro für arbeitende Rentner', '{701}', 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6214, 7, 15, null, 'Mehr Erwerbsanreize durch niedrigere Einkommensteuern und ein weniger attraktives Bürgergeld', '{701}', 1, 2, null, 'Stärkere Arbeitsanreize können die Zahl der Beitragszahlenden etwas erhöhen; wie stark Steuersenkungen und Kürzungen beim Bürgergeld die Beschäftigung steigern, ist in der Forschung umstritten. Steuersenkungen sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6215, 7, 15, null, 'Willkommensprämie von 20.000 Euro für jedes neugeborene Kind', '{701}', 1, 1, null, 'Mehr Geburten würden das Verhältnis von Beitragszahlenden zu Rentnern erst nach rund zwei Jahrzehnten verbessern; ob Geldprämien die Geburtenrate dauerhaft erhöhen, ist umstritten. Die Kosten von rund 13 Milliarden Euro im Jahr sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6216, 7, 16, null, 'Solidarische Erwerbstätigenversicherung für alle mit Erwerbseinkommen', '{701}', 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6217, 7, 16, null, 'Rentenniveau auf 53 Prozent anheben', '{701}', 1, 1, null, 'Ein höheres Rentenniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten von jährlich deutlich über 30 Milliarden Euro sind nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6218, 7, 16, null, 'Niedrige Rentenansprüche von Geringverdienenden, Erwerbslosen, Erziehenden und Pflegenden aufwerten', '{702}', 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6219, 7, 16, null, 'Versicherungsfremde Leistungen nicht mehr aus Beiträgen finanzieren', '{701}', 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6220, 7, 16, null, 'Solidarische Mindestrente bis zur Armutsrisikogrenze (rund 1.400 Euro)', '{702}', 2, 1, null, 'Ein Zuschlag bis zur Armutsrisikogrenze beseitigt Altersarmut nach niedrigen Löhnen und Lücken direkt, setzt aber nicht an den Löhnen selbst an und kann den Anreiz zu eigener Vorsorge schwächen. Die Kosten wären hoch, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6221, 7, 16, null, 'Betriebsrenten mindestens zur Hälfte durch die Arbeitgeber finanzieren', '{703}', 1, 3, null, 'Ein Pflichtanteil der Arbeitgeber erhöht die Leistungen bestehender Betriebsrenten, bringt aber nicht mehr Betriebe dazu, überhaupt eine anzubieten, und könnte kleine Betriebe eher abschrecken. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6222, 7, 16, null, 'Mindestlohn von mindestens 15 Euro, ab 2026 16 Euro', '{702}', 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6236, 10, 11, null, 'Pflegezusatzversicherungen steuerlich besser absetzbar machen (Prüfauftrag)', '{1002}', 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true),
  (6237, 10, 11, null, 'Pflegebudget, das flexibel für pflegerische Leistungen eingesetzt werden kann', '{1004}', 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true),
  (6238, 10, 11, null, 'Pflegebedürftigkeit durch Prävention und Reha aufschieben', '{1003}', 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6239, 10, 11, null, 'Planbare Einsatzzeiten, Springerpools, Aufstiegsmöglichkeiten', '{1001}', 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6240, 10, 11, null, 'Pflegekräfte im Ausland anwerben', '{1001}', 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6241, 10, 11, null, 'Rolle der Pflegefachpersonen stärken, Dokumentation vereinfachen', '{1001}', 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6242, 10, 12, null, 'Pflegekosten-Deckel: Eigenanteile in der stationären Pflege auf 1.000 Euro im Monat begrenzen', '{1002}', 2, 2, null, 'Ein Deckel senkt die pflegebedingten Eigenanteile direkt und für alle Heimbewohner; Unterkunft, Verpflegung und Investitionskosten bleiben aber, und die Mehrkosten von mehreren Milliarden Euro im Jahr müssen über Beiträge oder Steuern finanziert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6243, 10, 12, null, 'Investitionskosten der Heime nicht mehr vollständig auf die Bewohner umlegen', '{1005}', 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6244, 10, 12, null, 'Private Pflegeversicherungen in den Risikostrukturausgleich einbeziehen', '{1002}', 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6245, 10, 12, null, 'Familienpflegezeit und Familienpflegegeld analog zum Elterngeld', '{1004}', 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6246, 10, 12, null, 'Beratung und Anlaufstellen, Tages- und Nachtpflege ausbauen', '{1004}', 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6247, 10, 12, null, 'Bundeseinheitliche bedarfsgerechte Personalausstattung', '{1001}', 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6248, 10, 12, null, 'Tarifgebundene Gehälter refinanzieren', '{1001}', 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6249, 10, 12, null, 'Befugnisse von Pflegefachpersonen erweitern', '{1001}', 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6250, 10, 12, null, 'Weltweite Anwerbung und Integration von Fachkräften ausbauen', '{1001}', 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6251, 10, 12, null, 'Praxisnahe und kostenfreie Ausbildung in den Gesundheitsfachberufen', '{1001}', 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6252, 10, 13, null, 'Angebote im Quartier fördern, um Pflegebedürftigkeit hinauszuzögern', '{1003}', 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=91', null, 'gemischt', '2026-09-29', false, true),
  (6253, 10, 13, null, 'Zeitlich begrenzter Lohnersatz und Rentenbeiträge für Angehörige, die für die Pflege Arbeitszeit reduzieren', '{1004}', 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6254, 10, 13, null, 'Tages- und Kurzzeitpflege stärken und ausbauen', '{1004}', 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6255, 10, 13, null, 'Leistungen flexibel kombinieren, etwa über ein Pflegebudget', '{1004}', 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6256, 10, 13, null, 'Rückkehroffensive für ausgestiegene Pflegekräfte', '{1001}', 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6257, 10, 13, null, 'Höhere Personalschlüssel', '{1001}', 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6258, 10, 13, null, 'Mehr Kompetenzen und Aufstiegschancen für den Pflegeberuf', '{1001}', 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6259, 10, 13, null, 'Ausbildungsbedingungen verbessern, Pflegeassistenz bundesweit einheitlich regeln', '{1001}', 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true),
  (6260, 10, 13, null, 'Ausgleich zwischen gesetzlicher und privater Pflegeversicherung auf dem Weg zur Pflegebürgerversicherung', '{1002}', 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', null, 'gemischt', '2026-09-29', false, true),
  (6261, 10, 14, null, 'Pflegeanbieter von doppelten Prüfungen und unnötigen Dokumentationspflichten befreien', '{1001}', 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (6262, 10, 14, null, 'Niedrigschwellige Beratung ausbauen, auch für pflegende Kinder und Jugendliche', '{1004}', 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (6263, 10, 14, null, 'Mehr Pflegefachkräfte im In- und Ausland gewinnen, Anerkennung drastisch vereinfachen', '{1001}', 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (6264, 10, 14, null, 'Pflegepersonal durch digitale Anwendungen, Automatisierung und Robotik entlasten', '{1001}', 1, 3, null, 'Digitale Dokumentation und Assistenzsysteme können Pflegekräfte von Routinearbeit entlasten; wie viel Zeit das spart und ob Robotik in der Pflege breit einsetzbar ist, ist bisher kaum untersucht. Der Bund kann es fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'offen', '2026-09-29', false, true),
  (6265, 10, 14, null, 'Soziale Pflegeversicherung um eine kapitalgedeckte Komponente ergänzen', '{1003}', 1, 2, null, 'Ein Kapitalstock kann die Beitragssätze dämpfen, wenn die Zahl der Pflegebedürftigen steigt; der bestehende Pflegevorsorgefonds ist klein, und ein neuer Kapitalstock wirkt erst langfristig. Per Bundesgesetz umsetzbar, der Aufbau braucht zusätzliche Mittel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6266, 10, 14, null, 'Anreize für private Pflegevorsorge, betriebliche Pflegevorsorge der Betriebsrente gleichstellen', '{1002}', 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6267, 10, 15, null, 'Häusliche Pflege durch Angehörige deutlich höher honorieren', '{1004}', 1, 2, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Das Programm nennt keinen Betrag; die Mehrkosten trägt die Pflegeversicherung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (6268, 10, 15, null, 'Ambulante und befristete stationäre Angebote für pflegende Angehörige ausweiten', '{1004}', 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (6269, 10, 15, null, 'Ausgebildete Pflegekräfte durch bessere Bedingungen in den Beruf zurückholen', '{1001}', 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=113', null, 'gemischt', '2026-09-29', false, true),
  (6270, 10, 16, null, 'Solidarische Pflegevollversicherung, die alle pflegerischen Leistungen abdeckt', '{1002}', 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, die Finanzierung über eine Bürgerversicherung ist politisch und rechtlich offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'belegt', '2026-09-29', false, true),
  (6271, 10, 16, null, 'Bundesweite Offensive zur Rückanwerbung von Pflegekräften', '{1001}', 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (6272, 10, 16, null, 'Ausbildungsoffensive', '{1001}', 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true),
  (6273, 10, 16, null, 'Gute Arbeitsbedingungen und Entlastung der Beschäftigten in Pflegeeinrichtungen', '{1001}', 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6274, 10, 16, null, 'Länder verpflichten, Investitions- und Ausbildungskosten zu übernehmen; Kosten für Unterkunft und Verpflegung deckeln', '{1002,1005}', 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6275, 10, 16, null, 'Schonvermögen für Pflegebedürftige erhöhen', '{1002}', 1, 3, null, 'Ein höheres Schonvermögen schützt Erspartes, bevor die Sozialhilfe einspringt; die Eigenanteile selbst sinken dadurch nicht. Per Bundesgesetz umsetzbar, die Mehrkosten tragen die Sozialhilfeträger.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6276, 10, 16, null, 'Lohnlücke zwischen Alten- und Krankenpflege von rund 300 Euro schließen', '{1001}', 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6277, 10, 16, null, 'Sechs Wochen Freistellung mit vollem, arbeitgeberfinanziertem Lohnausgleich beim ersten Pflegefall in der Familie', '{1004}', 1, 2, null, 'Eine bezahlte Freistellung hilft Angehörigen, einen neuen Pflegefall zu organisieren; die langfristige Belastung bleibt. Die Kosten tragen die Arbeitgeber, was vor allem kleine Betriebe belastet.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6278, 10, 16, null, 'Wohnortnahe, nichtkommerzielle Tages- und Kurzzeitpflege', '{1004}', 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6302, 9, 11, null, 'Videoschutz an Gefahrenorten ausbauen, Gesichtserkennung an Bahnhöfen und Kriminalitätsschwerpunkten', '{901}', 1, 2, null, 'Videoüberwachung kann an einzelnen Orten Straftaten aufklären und manche verhindern; Studien finden Wirkung vor allem auf Parkplätzen, im öffentlichen Raum kaum. An Bahnhöfen ist die Bundespolizei zuständig, an anderen Orten die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6303, 9, 11, null, 'Mindestalter für die Strafmündigkeit wissenschaftlich prüfen lassen', '{903}', 1, 3, null, 'Eine niedrigere Strafmündigkeit setzt an der steigenden Zahl tatverdächtiger Kinder an; Studien finden aber keine abschreckende Wirkung früherer Strafen, und Jugendhilfe kann schon heute eingreifen. Der Bund ist für das Strafrecht zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6304, 9, 11, null, 'Auf alle Heranwachsenden das allgemeine Strafrecht anwenden', '{903}', 1, 3, null, 'Härtere Strafen für junge Erwachsene sollen abschrecken; die Forschung findet dafür kaum Belege, erzieherische Maßnahmen senken Rückfälle eher. Der Bund ist für das Jugendgerichtsgesetz zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6305, 9, 11, null, 'Neuer Pakt für den Rechtsstaat: mehr Personal, Digitalisierung, schnellere Verfahren', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6306, 9, 12, null, 'Personalaufbau bei den Sicherheitsbehörden fortsetzen, Polizei sichtbarer machen', '{901}', 1, 3, null, 'Mehr Bundespolizei kann an Bahnhöfen für mehr Präsenz sorgen; an den übrigen Orten, an denen sich Unsicherheit ballt, sind die Landespolizeien zuständig. Der Bund kann die Stellen selbst schaffen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6307, 9, 12, null, 'Erneuter Pakt für den Rechtsstaat mit den Ländern', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6308, 9, 12, null, 'Strafprozessordnung auf Effektivität reformieren', '{902}', 1, 3, null, 'Einfachere Verfahrensregeln können Strafverfahren beschleunigen; wie stark, hängt von der Ausgestaltung ab, und Beschuldigtenrechte setzen Grenzen. Der Bund ist für das Strafverfahrensrecht zuständig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6309, 9, 13, null, 'Neuauflage des Pakts für den Rechtsstaat; mehr Richter und Staatsanwälte, Digitalisierung', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=113', null, 'gemischt', '2026-09-29', false, true),
  (6310, 9, 13, null, 'Geringfügige Delikte außerhalb des Strafrechts regeln, um die Justiz zu entlasten', '{902}', 1, 3, null, 'Wenn etwa Fahren ohne Fahrschein oder Drogenbesitz keine Straftat mehr ist, entfallen jährlich viele Verfahren bei Polizei, Staatsanwaltschaften und Gerichten; die Entlastung trifft aber vor allem einfache Verfahren. Der Bund ist zuständig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=114', null, 'gemischt', '2026-09-29', false, true),
  (6311, 9, 13, null, 'Bundespolizei personell und technisch stärken', '{901}', 1, 3, null, 'Mehr Bundespolizei kann an Bahnhöfen für mehr Präsenz sorgen; an den übrigen Orten, an denen sich Unsicherheit ballt, sind die Landespolizeien zuständig. Der Bund kann die Stellen selbst schaffen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'gemischt', '2026-09-29', false, true),
  (6312, 9, 13, null, 'Sonderprogramm über zehn Jahre für Kinder- und Jugendarbeit in den Kommunen', '{903}', 1, 2, null, 'Offene Jugendarbeit bietet Orte und Ansprechpersonen und kann Gewalt vorbeugen; ihre Wirkung auf Jugendgewalt ist schwer nachzuweisen. Der Bund kann mit einem Förderprogramm beitragen, zuständig sind Länder und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'gemischt', '2026-09-29', false, true),
  (6313, 9, 14, null, 'Gerichte und Staatsanwaltschaften gut ausstatten, KI in der Justiz nutzen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6314, 9, 14, null, 'Überholte Straftatbestände streichen, Schwarzfahren als Ordnungswidrigkeit', '{902}', 1, 3, null, 'Wenn etwa Fahren ohne Fahrschein oder Drogenbesitz keine Straftat mehr ist, entfallen jährlich viele Verfahren bei Polizei, Staatsanwaltschaften und Gerichten; die Entlastung trifft aber vor allem einfache Verfahren. Der Bund ist zuständig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6315, 9, 15, null, 'Staatsanwaltschaften und Gerichte der Länder über einen höheren Steueranteil unterstützen; Justizpersonal aufstocken', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=118', null, 'gemischt', '2026-09-29', false, true),
  (6316, 9, 15, null, 'Prozessordnung modernisieren', '{902}', 1, 3, null, 'Einfachere Verfahrensregeln können Strafverfahren beschleunigen; wie stark, hängt von der Ausgestaltung ab, und Beschuldigtenrechte setzen Grenzen. Der Bund ist für das Strafverfahrensrecht zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', null, 'gemischt', '2026-09-29', false, true),
  (6317, 9, 15, null, 'Strafmündigkeit auf 12 Jahre senken', '{903}', 1, 3, null, 'Eine niedrigere Strafmündigkeit setzt an der steigenden Zahl tatverdächtiger Kinder an; Studien finden aber keine abschreckende Wirkung früherer Strafen, und Jugendhilfe kann schon heute eingreifen. Der Bund ist für das Strafrecht zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6318, 9, 15, null, 'Jugendstrafrecht nur noch bis zum 18. Lebensjahr', '{903}', 1, 3, null, 'Härtere Strafen für junge Erwachsene sollen abschrecken; die Forschung findet dafür kaum Belege, erzieherische Maßnahmen senken Rückfälle eher. Der Bund ist für das Jugendgerichtsgesetz zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6319, 9, 15, null, 'Mehrfach- und Intensivtäter zeitnah inhaftieren', '{903}', 1, 2, null, 'Schnelle Haft kann einzelne Intensivtäter stoppen; Haft ist aber an enge rechtliche Voraussetzungen gebunden, und Jugendhaft erhöht laut Studien eher das Rückfallrisiko. Der Bund kann Haftgründe ändern, vollziehen müssen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6320, 9, 16, null, 'Drogenkonsum vollständig entkriminalisieren', '{902}', 1, 3, null, 'Wenn etwa Fahren ohne Fahrschein oder Drogenbesitz keine Straftat mehr ist, entfallen jährlich viele Verfahren bei Polizei, Staatsanwaltschaften und Gerichten; die Entlastung trifft aber vor allem einfache Verfahren. Der Bund ist zuständig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6321, 9, 16, null, 'Hilfen und Sozialarbeit statt Verdrängung von Obdachlosen und Suchtkranken aus den Innenstädten', '{901}', 1, 2, null, 'Hilfsangebote können Konflikte an Plätzen und Bahnhöfen entschärfen; die Wirkung auf das Sicherheitsgefühl ist wenig untersucht. Der Bund kann Hilfen mitfinanzieren, zuständig sind Länder und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (6322, 9, 11, 'ST', 'Landespolizei auf weit mehr als 8.100 Bedienstete aufstocken, Sichtbarkeit in den Revieren erhöhen', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', null, 'gemischt', '2026-09-29', false, true),
  (6323, 9, 11, 'ST', 'Videoschutz im öffentlichen Raum ausweiten', '{901}', 1, 3, null, 'Videoüberwachung hilft bei der Aufklärung und kann an einzelnen Orten Straftaten verhindern; Studien finden im öffentlichen Raum nur kleine Effekte und keine deutliche Wirkung auf das Sicherheitsgefühl. Per Polizeigesetz des Landes umsetzbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'gemischt', '2026-09-29', false, true),
  (6324, 9, 11, 'ST', 'KI-gestützten Videoschutz landesweit ermöglichen', '{901}', 1, 2, null, 'Automatische Erkennung auffälliger Situationen kann Einsatzkräfte schneller alarmieren; die Wirkung ist kaum untersucht, und EU-KI-Verordnung und Grundrechte setzen enge Grenzen. Erste Modellprojekte gibt es.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-09-29', false, true),
  (6325, 9, 11, 'ST', 'Beschleunigte Verfahren, Zielzeiten für zentrale Verfahrensarten', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (6326, 9, 11, 'ST', 'Nachwuchs für die Justiz gewinnen, Justizberufe attraktiver machen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (6327, 9, 11, 'ST', 'Vollständige elektronische Aktenführung, KI in der Justiz', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'gemischt', '2026-09-29', false, true),
  (6328, 9, 11, 'ST', 'Schülergremien gegen beginnende Jugendkriminalität stärken', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (6329, 9, 12, 'ST', 'Häuser des Jugendrechts ermöglichen', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6330, 9, 12, 'ST', 'Ausreichende Personalstärke der Polizei sichern', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (6331, 9, 12, 'ST', 'Städtebauliche Maßnahmen und gute Beleuchtung für mehr Sicherheitsgefühl', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=30', null, 'belegt', '2026-09-29', false, true),
  (6332, 9, 12, 'ST', 'Kommunale Präventionsräte und soziale Präventionsangebote unterstützen', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true),
  (6333, 9, 12, 'ST', 'Gerichte und Staatsanwaltschaften personell stärken, kein Einstellungsstopp', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6334, 9, 12, 'ST', 'Verbindliches Digitalisierungskonzept für die Justiz, E-Akte', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6335, 9, 13, 'ST', 'Personalausbau auf 7.000 Vollzugsstellen, Fahrradstreifen', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6336, 9, 13, 'ST', 'Sichere Haltestellen schaffen, Angsträume beseitigen', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=28', null, 'belegt', '2026-09-29', false, true),
  (6337, 9, 13, 'ST', 'Digitalisierung der Justiz, E-Akte mit Priorität', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6338, 9, 13, 'ST', 'Gerichte und Staatsanwaltschaften personell so ausstatten, dass Verfahren zügig bearbeitet werden', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6339, 9, 14, 'ST', 'E-Akte in der ganzen Justiz bis spätestens 2030', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6340, 9, 14, 'ST', 'Justiz als attraktiver Arbeitgeber', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6341, 9, 14, 'ST', 'Sichtbar mehr Polizei, 7.000 Vollzugsstellen, Entlastung durch Verwaltungspersonal', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (6342, 9, 14, 'ST', 'Sicherheitspartnerschaften von Polizei und Ordnungsämtern, gemeinsame Einsätze als Regelfall', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (6343, 9, 15, 'ST', 'Landespolizei auf mindestens 7.500 Vollzugsbeamte aufstocken', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true),
  (6344, 9, 15, 'ST', 'Freiwillige Bürgerwacht unter dem Ordnungsamt', '{901}', 1, 2, null, 'Ehrenamtliche Streifen können die Präsenz im öffentlichen Raum erhöhen; ihre Wirkung ist kaum untersucht, und Befugnisse sowie Ausbildung müssen klar begrenzt sein. Das Land kann es gesetzlich regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=112', null, 'offen', '2026-09-29', false, true),
  (6345, 9, 15, 'ST', 'Warnschussarrest bei jeder Form der Jugendkriminalität', '{903}', 1, 1, null, 'Kurzer Arrest soll jugendliche Täter warnen; Studien finden nach Jugendarrest hohe Rückfallquoten. Ob Arrest verhängt wird, entscheiden unabhängige Gerichte nach Bundesrecht, eine Landesregierung kann es nicht anordnen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=109', null, 'gemischt', '2026-09-29', false, true),
  (6346, 9, 15, 'ST', 'Beschleunigtes Verfahren nach § 417 StPO stärker nutzen', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6347, 9, 15, 'ST', 'Neuköllner Modell: jugendliche Täter schnell aburteilen', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6348, 9, 15, 'ST', 'Engpässe der Justiz durch Investitionen und Personal auflösen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6349, 9, 15, 'ST', 'Auf Bundesebene Strafmündigkeit auf 12 Jahre senken, Heranwachsende nach Erwachsenenstrafrecht', '{903}', 1, 1, null, 'Eine niedrigere Strafmündigkeit oder Erwachsenenstrafrecht für Heranwachsende soll abschrecken; die Forschung findet dafür kaum Belege. Ein Land kann es nur über den Bundesrat anstoßen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=124', null, 'gemischt', '2026-09-29', false, true),
  (6350, 9, 16, 'ST', '500 neue Polizeistellen bis 2030, mobile Polizeistationen', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', null, 'gemischt', '2026-09-29', false, true),
  (6351, 9, 16, 'ST', 'Mehr Streetwork, offene Jugendtreffs und Jugendzentren; Präventionspolizei an Schulen', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=134', null, 'gemischt', '2026-09-29', false, true),
  (6352, 9, 16, 'ST', 'Langfristige Personalstrategie, Stellen schnell besetzen, mehr Assistenzkräfte', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'gemischt', '2026-09-29', false, true),
  (6353, 9, 16, 'ST', 'Funktionstüchtige, flächendeckende E-Akte', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'gemischt', '2026-09-29', false, true),
  (6354, 9, 16, 'ST', 'Auf Bundesebene Fahren ohne Fahrschein entkriminalisieren', '{902}', 1, 1, null, 'Weniger Bagatellverfahren würden Staatsanwaltschaften und Gerichte entlasten, vor allem bei einfachen Fällen; ein Land kann es nur über den Bundesrat anstoßen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=139', null, 'gemischt', '2026-09-29', false, true),
  (6355, 9, 16, 'ST', 'Häuser des Jugendrechts einrichten', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', null, 'gemischt', '2026-09-29', false, true),
  (6356, 9, 17, 'ST', 'Mehr Sozialarbeiter in der Jugendarbeit, Gewaltprävention weiter fördern', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', null, 'gemischt', '2026-09-29', false, true),
  (6357, 9, 17, 'ST', 'Landespolizei bis 2028 auf rund 7.000 Stellen aufstocken, mehr sichtbare Präsenz', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=68', null, 'gemischt', '2026-09-29', false, true),
  (6358, 9, 17, 'ST', 'Bessere Besoldung, Einstellungsstopp im Justizdienst aufheben', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=71', null, 'gemischt', '2026-09-29', false, true),
  (6359, 9, 11, 'MV', 'Landespolizei dauerhaft stärken und personell aufstocken, Soll-Stärke erreichen', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6360, 9, 11, 'MV', 'Videobeobachtung in Angsträumen', '{901}', 1, 3, null, 'Videoüberwachung hilft bei der Aufklärung und kann an einzelnen Orten Straftaten verhindern; Studien finden im öffentlichen Raum nur kleine Effekte und keine deutliche Wirkung auf das Sicherheitsgefühl. Per Polizeigesetz des Landes umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6361, 9, 11, 'MV', 'Mehr Polizei in den Innenstädten und an Kriminalitätsschwerpunkten', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', null, 'belegt', '2026-09-29', false, true),
  (6362, 9, 11, 'MV', 'Enge Zusammenarbeit mit den kommunalen Ordnungsdiensten', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6363, 9, 11, 'MV', 'Modernes Beleuchtungsmanagement und bauliche Maßnahmen', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=32', null, 'belegt', '2026-09-29', false, true),
  (6364, 9, 11, 'MV', '50 zusätzliche Stellen bei den Staatsanwaltschaften, Gerichte nach Personalbedarf ausstatten', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=33', null, 'gemischt', '2026-09-29', false, true),
  (6365, 9, 11, 'MV', 'Digitalisierung der Justiz, E-Akte in allen Rechtsgebieten, KI als Hilfsmittel', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=34', null, 'gemischt', '2026-09-29', false, true),
  (6366, 9, 11, 'MV', 'Beschleunigte Verfahren im Jugendstrafrecht, Häuser des Jugendrechts prüfen', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6367, 9, 11, 'MV', 'Jugendlichen Mehrfach- und Intensivtätern wirksamer begegnen, bessere Kooperation und Datenaustausch', '{903}', 2, 3, null, 'Abgestimmte Programme für jugendliche Intensivtäter setzen an der kleinen Gruppe an, die viele Taten begeht; Auswertungen berichten weniger Rückfälle, die Befunde sind aber nicht einheitlich. Das Land kann es mit Polizei, Justiz und Jugendhilfe umsetzen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6368, 9, 12, 'MV', 'Sicherheit und Ordnung an Bahnhöfen, Haltestellen, in Bussen und Bahnen gemeinsam stärken', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6369, 9, 12, 'MV', 'Personalaufwuchs auf mindestens 6.183 Polizeibeamte, Präsenz in der Fläche', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6370, 9, 12, 'MV', 'Personalausstattung der Justiz auf hohem Niveau halten', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (6371, 9, 12, 'MV', 'Digitalisierung der Justiz vorantreiben, E-Akte als Standard', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (6372, 9, 13, 'MV', 'Soziale Präventionsarbeit in den Kommunen stärken (Streetwork, Jugendclubs)', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', null, 'gemischt', '2026-09-29', false, true),
  (6373, 9, 13, 'MV', 'Bürger*innen-Polizei mit mehr Präsenz zu Fuß in den Quartieren, ausreichende Neueinstellungen', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', null, 'gemischt', '2026-09-29', false, true),
  (6374, 9, 13, 'MV', 'Deutlich mehr Richter*innen, Staatsanwält*innen und Justizbedienstete einstellen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://gruene-mv.de/?wpdmdl=33772#page=78', null, 'gemischt', '2026-09-29', false, true),
  (6375, 9, 14, 'MV', 'Mehr Polizeibeamte im operativen Dienst, Entlastung von Verwaltungsaufgaben', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-09-29', false, true),
  (6376, 9, 14, 'MV', 'Zahl der Richter, Staatsanwälte und Justizmitarbeitenden bedarfsgerecht erhöhen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'gemischt', '2026-09-29', false, true),
  (6377, 9, 14, 'MV', 'Digitalisierung der Justiz, elektronische Ermittlungsakte mit Schnittstelle zur Polizei', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'gemischt', '2026-09-29', false, true),
  (6378, 9, 15, 'MV', 'Am Ziel von 6.200 Beamten der Landespolizei festhalten', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (6379, 9, 15, 'MV', 'Freiwillige Sicherheitshelfer prüfen', '{901}', 1, 2, null, 'Ehrenamtliche Helfer können die Präsenz im öffentlichen Raum erhöhen und Polizei und Ordnungsämter entlasten; ihre Wirkung ist kaum untersucht, Befugnisse und Ausbildung müssen eng begrenzt sein. Das Land kann es gesetzlich regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'offen', '2026-09-29', false, true),
  (6380, 9, 15, 'MV', 'Beschleunigtes Verfahren in einfachen Fällen stärker nutzen', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6381, 9, 15, 'MV', 'Vereinfachtes Jugendverfahren anwenden', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6382, 9, 15, 'MV', 'Bundesratsinitiative: Strafmündigkeit auf 12 Jahre senken', '{903}', 1, 1, null, 'Eine niedrigere Strafmündigkeit oder Erwachsenenstrafrecht für Heranwachsende soll abschrecken; die Forschung findet dafür kaum Belege. Ein Land kann es nur über den Bundesrat anstoßen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6383, 9, 16, 'MV', 'Polizei personell und sachlich ausreichend ausstatten', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true),
  (6384, 9, 16, 'MV', 'Arbeitsbedingungen in Gerichten und Staatsanwaltschaften verbessern', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6385, 9, 16, 'MV', 'E-Akte und Schnittstellen zu Polizei und weiteren Stellen interoperabel gestalten', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6386, 9, 17, 'MV', 'Mehr Personal im Streifendienst für Präsenz in Problem- und Brennpunktbereichen', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', null, 'belegt', '2026-09-29', false, true),
  (6387, 9, 17, 'MV', 'Mehr Richter, Staatsanwälte und Servicekräfte', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true),
  (6388, 9, 17, 'MV', 'Schnellere Verfahren und Vollstreckung im Strafrecht', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true),
  (6389, 9, 11, 'BE', 'Videoüberwachung an allen kriminalitätsbelasteten Orten ausbauen', '{901}', 1, 3, null, 'Videoüberwachung hilft bei der Aufklärung und kann an einzelnen Orten Straftaten verhindern; Studien finden im öffentlichen Raum nur kleine Effekte und keine deutliche Wirkung auf das Sicherheitsgefühl. Per Polizeigesetz des Landes umsetzbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', null, 'gemischt', '2026-09-29', false, true),
  (6390, 9, 11, 'BE', 'Polizeiwachen an Kriminalitätsschwerpunkten, etwa am Leopoldplatz', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', null, 'belegt', '2026-09-29', false, true),
  (6391, 9, 11, 'BE', 'Angsträume abbauen: Beleuchtung, übersichtliche Wege, gepflegte Unterführungen', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', null, 'belegt', '2026-09-29', false, true),
  (6392, 9, 11, 'BE', 'Waffen- und Messerverbotszonen an Kriminalitätsschwerpunkten', '{901}', 1, 3, null, 'Verbotszonen erlauben Kontrollen an Brennpunkten; ob sie Gewalt dort senken, ist kaum belegt, und anlassarme Kontrollen sind umstritten. Die Länder können sie per Verordnung einrichten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=6', null, 'gemischt', '2026-09-29', false, true),
  (6393, 9, 11, 'BE', 'Neue Wege bei der Personalgewinnung der Polizei', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'gemischt', '2026-09-29', false, true),
  (6394, 9, 11, 'BE', 'Beschleunigte Strafverfahren bei Straßenkriminalität zum Regelfall machen', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6395, 9, 11, 'BE', 'Digitale Justiz, die IT und Künstliche Intelligenz nutzt', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6396, 9, 11, 'BE', 'Ruhestand von Richterinnen und Richtern freiwillig bis 68 hinausschieben', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6397, 9, 11, 'BE', 'Auf Bundesebene Strafmündigkeit von 14 auf 12 Jahre senken', '{903}', 1, 1, null, 'Eine niedrigere Strafmündigkeit oder Erwachsenenstrafrecht für Heranwachsende soll abschrecken; die Forschung findet dafür kaum Belege. Ein Land kann es nur über den Bundesrat anstoßen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6398, 9, 12, 'BE', 'Mehr Fuß- und Fahrradstreifen, Sicherheitspersonal auf U- und S-Bahnhöfen', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'belegt', '2026-09-29', false, true),
  (6399, 9, 12, 'BE', 'Präventionsräte stärken, Gewaltpräventionsgesetz', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6400, 9, 12, 'BE', 'Haltestellen überdachen und beleuchten', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'belegt', '2026-09-29', false, true),
  (6401, 9, 12, 'BE', 'Verfahren durch bessere Abläufe, Digitalisierung und zusätzliche Stellen verkürzen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6402, 9, 12, 'BE', 'Schnelle Reaktion auf Straftaten Jugendlicher und Heranwachsender', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6403, 9, 13, 'BE', 'Kontaktbereichsbeamte, Fahrradstreifen und mobile Wachen an Hotspots', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', null, 'belegt', '2026-09-29', false, true),
  (6404, 9, 13, 'BE', 'Jugendsozial- und Jugendkulturarbeit absichern, besonders für junge Männer', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', null, 'gemischt', '2026-09-29', false, true),
  (6405, 9, 13, 'BE', 'Bezirkliche Ordnungsämter stärken', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'gemischt', '2026-09-29', false, true),
  (6406, 9, 13, 'BE', 'Personaloffensive für die Justiz', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=240', null, 'gemischt', '2026-09-29', false, true),
  (6407, 9, 13, 'BE', 'Digitalisierung der Justiz mit Priorität', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=241', null, 'gemischt', '2026-09-29', false, true),
  (6408, 9, 14, 'BE', 'Wachen nach dem Vorbild der „Kotti-Wache“ an kriminalitätsbelasteten Orten', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', null, 'belegt', '2026-09-29', false, true),
  (6409, 9, 14, 'BE', 'Beleuchtung, offene Sichtachsen, keine dunklen Ecken', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', null, 'belegt', '2026-09-29', false, true),
  (6410, 9, 14, 'BE', 'Mehr Jugend- und Sozialarbeit sowie Streetwork', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'gemischt', '2026-09-29', false, true),
  (6411, 9, 14, 'BE', 'Personalsituation in Gerichten und Staatsanwaltschaft verbessern', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6412, 9, 14, 'BE', 'Schnelle Jugendverfahren (Neuköllner Modell) fortsetzen und verstetigen', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'gemischt', '2026-09-29', false, true),
  (6413, 9, 15, 'BE', 'Vollständige Videoüberwachung in Brennpunktbereichen', '{901}', 1, 3, null, 'Videoüberwachung hilft bei der Aufklärung und kann an einzelnen Orten Straftaten verhindern; Studien finden im öffentlichen Raum nur kleine Effekte und keine deutliche Wirkung auf das Sicherheitsgefühl. Per Polizeigesetz des Landes umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (6414, 9, 15, 'BE', 'Mobile Polizeiwachen in Problemvierteln, dichteres Wachennetz', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'belegt', '2026-09-29', false, true),
  (6415, 9, 15, 'BE', 'Mehr Personal bei der Polizei', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (6416, 9, 15, 'BE', 'Mehr Personal bei der Justiz', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (6417, 9, 15, 'BE', 'Bezirkspolizei bei den Ordnungsämtern einführen', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=12', null, 'gemischt', '2026-09-29', false, true),
  (6418, 9, 15, 'BE', 'Beschleunigte Jugendverfahren (Neuköllner Modell) ausweiten', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6419, 9, 15, 'BE', 'Strafmündigkeit von 14 auf 12 Jahre senken', '{903}', 1, 1, null, 'Eine niedrigere Strafmündigkeit oder Erwachsenenstrafrecht für Heranwachsende soll abschrecken; die Forschung findet dafür kaum Belege. Ein Land kann es nur über den Bundesrat anstoßen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6420, 9, 15, 'BE', 'Rechtsgrundlage für nächtliche Ausgangssperren für jugendliche Intensivtäter', '{903}', 1, 1, null, 'Ausgangssperren sollen einzelne Intensivtäter nachts von der Straße fernhalten; ihre Wirkung ist kaum untersucht, und sie greifen tief in Grundrechte ein. Ob ein Land sie im Polizeirecht regeln darf, ist rechtlich offen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-09-29', false, true),
  (6421, 9, 16, 'BE', 'Straßensozialarbeit und Parkläufer ausbauen', '{901}', 1, 2, null, 'Aufsuchende Sozialarbeit, Sucht- und Wohnungslosenhilfe können Konflikte an Plätzen und Bahnhöfen entschärfen; die Wirkung auf Kriminalität und Sicherheitsgefühl ist wenig untersucht. Sie braucht dauerhafte Finanzierung durch Land und Kommunen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', null, 'gemischt', '2026-09-29', false, true),
  (6422, 9, 16, 'BE', 'Kiezorientierte Gewalt- und Kriminalitätsprävention ausweiten', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', null, 'gemischt', '2026-09-29', false, true),
  (6423, 9, 16, 'BE', 'Mehr richterliche Stellen und Personal für die Auswertung von Beweismitteln', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'gemischt', '2026-09-29', false, true),
  (6424, 9, 16, 'BE', 'Digitalisierung der Berliner Justiz vorantreiben', '{902}', 1, 3, null, 'Die elektronische Akte und digitale Abläufe können Verfahren mittelfristig beschleunigen; in der Umstellungsphase belasten sie das Personal eher zusätzlich. Die E-Akte ist bundesrechtlich ohnehin vorgeschrieben, das Land setzt sie um.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'gemischt', '2026-09-29', false, true),
  (6425, 9, 16, 'BE', 'Armutsdelikte wie Fahren ohne Fahrschein entkriminalisieren', '{902}', 1, 1, null, 'Weniger Bagatellverfahren würden Staatsanwaltschaften und Gerichte entlasten, vor allem bei einfachen Fällen; ein Land kann es nur über den Bundesrat anstoßen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=311', null, 'gemischt', '2026-09-29', false, true),
  (6426, 9, 17, 'BE', 'Einstellungsoffensive bei der Polizei', '{901}', 2, 2, null, 'Mehr Polizei auf der Straße kann Straftaten verhindern und das Sicherheitsgefühl stärken; Studien finden Effekte vor allem, wenn die Präsenz auf Brennpunkte gerichtet ist. Neue Stellen kosten Geld und Ausbildungszeit, der Nachwuchs ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6427, 9, 17, 'BE', 'Flächendeckende Präventions- und Anti-Gewaltprogramme', '{903}', 2, 2, null, 'Präventionsprogramme an Schulen und aufsuchende Jugendarbeit setzen früh an; gut evaluierte Programme senken Gewalt, viele Angebote sind aber nicht untersucht. Land und Kommunen müssen sie dauerhaft finanzieren.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6428, 9, 17, 'BE', 'Mehr Streifen an Bahnhöfen, Parks und Plätzen', '{901}', 3, 2, null, 'Streifen und Wachen an Orten, an denen sich Straftaten ballen, senken dort nachweislich die Kriminalität, ohne sie im großen Stil zu verdrängen (Hot-Spot-Policing). Das Land kann es selbst organisieren, braucht aber Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'belegt', '2026-09-29', false, true),
  (6429, 9, 17, 'BE', 'Beleuchtung und städtebauliche Kriminalprävention ausbauen', '{901}', 2, 3, null, 'Bessere Beleuchtung und übersichtliche Gestaltung senken laut Studien Straftaten und stärken das Sicherheitsgefühl an den betroffenen Orten; die Wirkung bleibt örtlich begrenzt. Land und Kommunen können es mit Förderprogrammen umsetzen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'belegt', '2026-09-29', false, true),
  (6430, 9, 17, 'BE', 'Deutlich mehr Richter- und Staatsanwaltsstellen', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und Justizpersonal setzen direkt an der Überlastung an; der Nachwuchs ist knapp und die Besoldung im Wettbewerb der Länder entscheidend. Das Land kann einstellen, braucht dafür aber Haushaltsmittel.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6431, 9, 17, 'BE', 'Beschleunigte Verfahren bei Alltagskriminalität', '{902}', 1, 3, null, 'Das beschleunigte Verfahren nach § 417 StPO und feste Zielzeiten sorgen bei einfachen Fällen für schnelle Urteile; für die Masse komplexer Verfahren ändert sich wenig. Staatsanwaltschaften und Gerichte des Landes können es stärker nutzen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6432, 9, 17, 'BE', 'Beschleunigte Verfahren bei Jugendkriminalität', '{903}', 2, 3, null, 'Wenn Polizei, Staatsanwaltschaft und Jugendhilfe gemeinsam und schnell reagieren, folgt eine Reaktion kurz auf die Tat; Auswertungen berichten schnellere Verfahren, ein Effekt auf Rückfälle ist nicht eindeutig belegt. Das Land kann es einrichten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6433, 9, 17, 'BE', 'Videoüberwachung an besonders kriminalitätsbelasteten Orten', '{901}', 1, 3, null, 'Videoüberwachung hilft bei der Aufklärung und kann an einzelnen Orten Straftaten verhindern; Studien finden im öffentlichen Raum nur kleine Effekte und keine deutliche Wirkung auf das Sicherheitsgefühl. Per Polizeigesetz des Landes umsetzbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6434, 9, 17, 'BE', 'Gemeinsame Kontrollen von Ordnungsamt, Polizei und Zoll', '{901}', 1, 3, null, 'Gemeinsame Streifen und Sicherheitspartnerschaften erhöhen die Präsenz an Plätzen und Bahnhöfen und bündeln Zuständigkeiten; eigene Wirkungsstudien gibt es wenige. Land und Kommunen können es vereinbaren.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6435, 7, 17, null, 'Alle Erwerbstätigen, auch Abgeordnete und Minister, zahlen in die gesetzliche Rente ein', '{701}', 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6436, 7, 17, null, 'Alle Selbstständigen in die Sozialversicherungen einbeziehen', '{702}', 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6437, 7, 17, null, 'Mindestlohn sofort auf 15 Euro anheben', '{702}', 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
  (6438, 7, 17, null, 'Mindestrente von 1.500 Euro nach 40 Versicherungsjahren, gestaffelt nach Versicherungsjahren', '{702}', 2, 1, null, 'Eine Mindestrente hebt niedrige Renten nach langen Versicherungszeiten direkt an; wer große Lücken im Erwerbsleben hat, erreicht die Stufen oft nicht. Die Kosten wären hoch, die Finanzierung nennt das Programm nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
  (6439, 7, 17, null, 'Leistungsniveau von mindestens 75 Prozent des früheren Nettoeinkommens', '{701}', 1, 1, null, 'Ein deutlich höheres Leistungsniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten wären sehr hoch und sind nicht geklärt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true),
  (6440, 10, 17, null, 'Pflegevollversicherung, überwiegend aus Steuermitteln finanziert', '{1002}', 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, eine Finanzierung überwiegend aus Steuern ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'belegt', '2026-09-29', false, true),
  (6441, 10, 17, null, 'Mehr Pflegepersonal ausbilden', '{1001}', 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6442, 10, 17, null, 'Bessere Bezahlung in der Pflege', '{1001}', 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true),
  (6443, 10, 17, null, 'Pflegegeld deutlich erhöhen, orientiert an der Bezahlung professioneller Pflegekräfte', '{1004}', 1, 1, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Eine Orientierung am Lohn von Pflegekräften würde ein Vielfaches kosten, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-09-29', false, true),
  (6444, 9, 17, null, 'Sichtbare Polizeipräsenz auf Straßen und Plätzen mit ausreichend Personal', '{901}', 1, 3, null, 'Mehr Bundespolizei kann an Bahnhöfen für mehr Präsenz sorgen; an den übrigen Orten, an denen sich Unsicherheit ballt, sind die Landespolizeien zuständig. Der Bund kann die Stellen selbst schaffen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6445, 9, 17, null, 'Deutlich mehr Personal in den Justizbehörden', '{902}', 2, 2, null, 'Mehr Richter, Staatsanwälte und eine digitale Justiz setzen direkt an der Überlastung an; der erste Pakt für den Rechtsstaat hat Stellen geschaffen, die Rückstände aber nicht beseitigt. Der Bund kann nur mitfinanzieren, einstellen müssen die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true),
  (6446, 9, 17, null, 'Verfahrenszahlen durch Reformen im Strafrecht senken', '{902}', 1, 3, null, 'Wenn etwa Fahren ohne Fahrschein oder Drogenbesitz keine Straftat mehr ist, entfallen jährlich viele Verfahren bei Polizei, Staatsanwaltschaften und Gerichten; die Entlastung trifft aber vor allem einfache Verfahren. Der Bund ist zuständig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true),
  (6450, 10, 11, 'MV', 'Landesbeteiligung an Investitionskosten und Ausbildungsumlage, Landesinvestitionsprogramm für Pflegeeinrichtungen', '{1005}', 1, 3, null, 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true),
  (6451, 10, 12, 'ST', 'Investitionen in Pflegeeinrichtungen fördern, wo die Versorgung sonst nicht gesichert wäre', '{1005}', 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=13', null, 'gemischt', '2026-09-29', false, true),
  (6452, 10, 13, 'ST', 'Land übernimmt Investitions- und Ausbildungskosten aus dem Eigenanteil', '{1005}', 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=86', null, 'gemischt', '2026-09-29', false, true),
  (6453, 10, 15, 'BE', 'Investitionskostenzuschuss des Landes auf 300 Euro je Person und Monat erhöhen; 40.000 Euro je neuem Heimplatz', '{1005}', 2, 2, null, 'Ein Zuschuss von 300 Euro im Monat deckt einen großen Teil der Investitionskosten und senkt den Eigenanteil spürbar; das Programm nennt keine Finanzierung, und Berlin müsste dafür dauerhaft einen dreistelligen Millionenbetrag im Jahr aufbringen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=71', null, 'gemischt', '2026-09-29', false, true),
  (6454, 10, 16, 'ST', 'Land übernimmt die Investitionskosten der Pflegeeinrichtungen vollständig', '{1005}', 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=56', null, 'gemischt', '2026-09-29', false, true),
  (6455, 10, 16, 'MV', 'Sanierungen vollstationärer Einrichtungen durch ein Investitionsprogramm unterstützen', '{1005}', 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', null, 'gemischt', '2026-09-29', false, true),
  (6456, 10, 16, 'BE', 'Pflegewohngeld: Land übernimmt Investitionskosten für Heimbewohner', '{1005}', 2, 2, null, 'Ein Pflegewohngeld übernimmt die Investitionskosten für Bewohner, die sie nicht selbst tragen können, und entlastet sie direkt; wer mehr Einkommen oder Vermögen hat, zahlt weiter. Das Land kann es selbst einführen, die Kosten muss es dauerhaft tragen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=140', null, 'gemischt', '2026-09-29', false, true),
  (6457, 10, 17, 'MV', 'Eigenanteile senken: Land übernimmt die Investitionskosten auf Grundlage der Landespflegeplanung', '{1005}', 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=66', null, 'gemischt', '2026-09-29', false, true),
  (6467, 9, 11, null, 'Elektronische Fußfessel verstärkt einsetzen, Frauenhäuser stärken', '{904}', 2, 3, null, 'Elektronisch überwachte Kontakt- und Näherungsverbote warnen Betroffene, wenn sich der Täter nähert, und Täterprogramme sollen Wiederholungen verhindern; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6468, 9, 12, null, 'Gewaltschutzgesetz verschärfen: Fußfessel, verpflichtende Anti-Gewalt-Trainings, Aufenthaltsverbote', '{904}', 2, 3, null, 'Elektronisch überwachte Kontakt- und Näherungsverbote warnen Betroffene, wenn sich der Täter nähert, und Täterprogramme sollen Wiederholungen verhindern; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6469, 9, 12, null, 'Bundesweiter Rechtsanspruch auf Schutz und Beratung', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Der Bund kann sich finanziell beteiligen, wie mit dem Gewalthilfegesetz; Ausbau und Betrieb liegen bei Ländern und Kommunen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6470, 9, 13, null, 'Rechtsanspruch auf Schutz und Beratung, Bundesbeteiligung an Frauenhäusern und Beratungsstellen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Der Bund kann sich finanziell beteiligen, wie mit dem Gewalthilfegesetz; Ausbau und Betrieb liegen bei Ländern und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', null, 'gemischt', '2026-09-29', false, true),
  (6471, 9, 13, null, 'Annäherungsverbote wirksam durchsetzen, auch mit elektronischer Fußfessel', '{904}', 2, 3, null, 'Elektronisch überwachte Kontakt- und Näherungsverbote warnen Betroffene, wenn sich der Täter nähert, und Täterprogramme sollen Wiederholungen verhindern; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', null, 'gemischt', '2026-09-29', false, true),
  (6472, 9, 14, null, 'Länder und Kommunen sollen Frauenhausplätze ausfinanzieren; bundesweite Online-Plattform freier Plätze', '{904}', 1, 3, null, 'Eine Plattform mit freien Plätzen verkürzt die Suche im Notfall; mehr Plätze entstehen dadurch nicht, deren Finanzierung überlässt das Programm Ländern und Kommunen. Die Plattform kann der Bund selbst aufbauen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, 'gemischt', '2026-09-29', false, true),
  (6473, 9, 16, null, 'Frauenhäuser bedarfsgerecht und verlässlich finanzieren', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Der Bund kann sich finanziell beteiligen, wie mit dem Gewalthilfegesetz; Ausbau und Betrieb liegen bei Ländern und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (6474, 9, 11, null, 'Ausreisepflichtige Straftäter nach der Haft in unbefristeten Ausreisearrest', '{905}', 1, 1, null, 'Arrest bis zur Ausreise verhindert, dass straffällige Ausreisepflichtige untertauchen; die meisten nichtdeutschen Tatverdächtigen sind aber nicht ausreisepflichtig. Eine zeitlich unbegrenzte Freiheitsentziehung ist mit Grundgesetz und EU-Rückführungsrichtlinie kaum vereinbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true),
  (6475, 9, 12, null, 'Rasche und konsequente Abschiebungen, insbesondere bei Straftätern', '{905}', 1, 2, null, 'Abschiebungen verurteilter ausländischer Straftäter verhindern weitere Taten dieser Personen hier; die meisten nichtdeutschen Tatverdächtigen sind aber nicht ausreisepflichtig, und Abschiebungen scheitern oft an Papieren oder Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', null, 'gemischt', '2026-09-29', false, true),
  (6476, 9, 13, null, 'Ausreisepflichtige nach schweren Straftaten vorrangig zurückführen', '{905}', 1, 2, null, 'Abschiebungen verurteilter ausländischer Straftäter verhindern weitere Taten dieser Personen hier; die meisten nichtdeutschen Tatverdächtigen sind aber nicht ausreisepflichtig, und Abschiebungen scheitern oft an Papieren oder Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'gemischt', '2026-09-29', false, true),
  (6477, 9, 15, null, 'Zwingende Ausweisung verurteilter ausländischer Straftäter konsequent vollziehen, schon im Strafurteil feststellen', '{905}', 1, 1, null, 'Ausweisung verhindert weitere Taten der Betroffenen hier, scheitert aber oft an Papieren und Herkunftsstaaten. Eine zwingende Ausweisung ohne Einzelfallabwägung verträgt sich kaum mit Art. 8 EMRK; seit 2016 verlangt das Aufenthaltsrecht deshalb eine Abwägung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=117', null, 'gemischt', '2026-09-30', false, true),
  (6478, 9, 17, null, 'Straftäter ausweisen und abschieben, Verfahren dazu vorrangig betreiben', '{905}', 1, 2, null, 'Abschiebungen verurteilter ausländischer Straftäter verhindern weitere Taten dieser Personen hier; die meisten nichtdeutschen Tatverdächtigen sind aber nicht ausreisepflichtig, und Abschiebungen scheitern oft an Papieren oder Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true),
  (6479, 9, 11, 'ST', 'Finanzierung von Beratungsstellen und Frauenhäusern sichern', '{904}', 1, 3, null, 'Eine gesicherte Finanzierung erhält bestehende Frauenhäuser und Beratungsstellen, schafft aber keine zusätzlichen Plätze, die vielerorts fehlen. Das Land kann es im Haushalt absichern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', null, 'gemischt', '2026-09-29', false, true),
  (6480, 9, 11, 'MV', 'Polizeiliche Kontakt- und Näherungsverbote ausweiten, verpflichtende Gewaltpräventionsberatung für Gefährder', '{904}', 2, 3, null, 'Elektronisch überwachte oder konsequent durchgesetzte Kontakt- und Näherungsverbote schützen Betroffene vor erneuten Angriffen; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Die Länder können es über ihr Polizeirecht regeln, mehrere tun es bereits.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true),
  (6481, 9, 11, 'BE', 'Elektronische Fußfessel bei Hochrisiko-Gefährdern ausweiten, Warngeräte für Opfer', '{904}', 2, 3, null, 'Elektronisch überwachte oder konsequent durchgesetzte Kontakt- und Näherungsverbote schützen Betroffene vor erneuten Angriffen; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Die Länder können es über ihr Polizeirecht regeln, mehrere tun es bereits.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', null, 'gemischt', '2026-09-29', false, true),
  (6482, 9, 11, 'BE', 'Zusätzliche Schutzplätze, zehntes Frauenhaus', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', null, 'gemischt', '2026-09-29', false, true),
  (6483, 9, 12, 'ST', 'Frauenhäuser und Schutzwohnungen im ganzen Land ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6484, 9, 12, 'ST', 'Land übernimmt die Tagessätze in Frauenschutzhäusern', '{904}', 1, 3, null, 'Müssen Betroffene den Aufenthalt nicht selbst zahlen, sinkt eine Hürde, Schutz zu suchen; an der Zahl der fehlenden Plätze ändert das nichts. Das Land kann die Kosten übernehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-09-29', false, true),
  (6485, 9, 12, 'MV', 'Frauenhäuser modernisieren und bedarfsgerecht ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', null, 'gemischt', '2026-09-29', false, true),
  (6486, 9, 12, 'BE', 'Systematische Risikoanalysen bei der Polizei zur Früherkennung von Hochrisikofällen', '{904}', 2, 3, null, 'Standardisierte Gefährdungsanalysen und Fallkonferenzen von Polizei, Justiz und Hilfesystem sollen gefährliche Fälle früh erkennen; sie gehören zu den Vorgaben der Istanbul-Konvention, ihre Wirkung auf schwere Gewalt ist aber wenig untersucht. Das Land kann es selbst einführen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6487, 9, 12, 'BE', 'Frauenhäuser, Schutzwohnungen und Täterarbeit stadtweit ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-09-29', false, true),
  (6488, 9, 13, 'ST', 'Bedarfsgerechter Ausbau von Frauenhäusern, Eigenanteil der Bewohnerinnen abschaffen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6489, 9, 13, 'ST', 'Fachstellen für Täterarbeit auch im ländlichen Raum fördern', '{904}', 1, 3, null, 'Täterprogramme sollen Wiederholungstaten verhindern; Studien finden eher kleine und uneinheitliche Effekte. Das Land kann Angebote fördern, als Auflage anordnen können sie Gerichte und Staatsanwaltschaften nach Bundesrecht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6490, 9, 13, 'MV', 'Beratungsstellen und Frauenhäuser stärken, Finanzierung dauerhaft sichern', '{904}', 1, 3, null, 'Eine gesicherte Finanzierung erhält bestehende Frauenhäuser und Beratungsstellen, schafft aber keine zusätzlichen Plätze, die vielerorts fehlen. Das Land kann es im Haushalt absichern.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'gemischt', '2026-09-29', false, true),
  (6491, 9, 13, 'BE', 'Zwei neue Frauenhäuser, mehr Beratung und Zweite-Stufe-Wohnungen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'gemischt', '2026-09-29', false, true),
  (6492, 9, 14, 'ST', 'Eigenanteile für die Übernachtung in Frauenhäusern abschaffen', '{904}', 1, 3, null, 'Müssen Betroffene den Aufenthalt nicht selbst zahlen, sinkt eine Hürde, Schutz zu suchen; an der Zahl der fehlenden Plätze ändert das nichts. Das Land kann die Kosten übernehmen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=39', null, 'offen', '2026-09-29', false, true),
  (6493, 9, 14, 'MV', 'Elektronische Fußfessel bei häuslicher Gewalt im Landespolizeirecht', '{904}', 2, 3, null, 'Elektronisch überwachte oder konsequent durchgesetzte Kontakt- und Näherungsverbote schützen Betroffene vor erneuten Angriffen; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Die Länder können es über ihr Polizeirecht regeln, mehrere tun es bereits.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-09-29', false, true),
  (6494, 9, 14, 'MV', 'Finanzierung des Beratungs- und Hilfenetzes stärken', '{904}', 1, 3, null, 'Eine gesicherte Finanzierung erhält bestehende Frauenhäuser und Beratungsstellen, schafft aber keine zusätzlichen Plätze, die vielerorts fehlen. Das Land kann es im Haushalt absichern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=53', null, 'gemischt', '2026-09-29', false, true),
  (6495, 9, 14, 'BE', 'Schutzplätze in Frauenhäusern und Zufluchtswohnungen ausweiten', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=80', null, 'gemischt', '2026-09-29', false, true),
  (6496, 9, 14, 'BE', 'Täterarbeit deutlich ausbauen', '{904}', 1, 3, null, 'Täterprogramme sollen Wiederholungstaten verhindern; Studien finden eher kleine und uneinheitliche Effekte. Das Land kann Angebote fördern, als Auflage anordnen können sie Gerichte und Staatsanwaltschaften nach Bundesrecht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', null, 'gemischt', '2026-09-29', false, true),
  (6497, 9, 16, 'ST', 'Eigenanteil im Frauenschutzhaus abschaffen, Frauenberatungsstellen stärken', '{904}', 1, 3, null, 'Müssen Betroffene den Aufenthalt nicht selbst zahlen, sinkt eine Hürde, Schutz zu suchen; an der Zahl der fehlenden Plätze ändert das nichts. Das Land kann die Kosten übernehmen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=21', null, 'offen', '2026-09-29', false, true),
  (6498, 9, 16, 'MV', 'Mehr Plätze in Frauenhäusern, Beratung und Täterarbeit ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (6499, 9, 16, 'MV', 'Landesweites Hochrisikomanagement bei häuslicher Gewalt', '{904}', 2, 3, null, 'Standardisierte Gefährdungsanalysen und Fallkonferenzen von Polizei, Justiz und Hilfesystem sollen gefährliche Fälle früh erkennen; sie gehören zu den Vorgaben der Istanbul-Konvention, ihre Wirkung auf schwere Gewalt ist aber wenig untersucht. Das Land kann es selbst einführen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (6500, 9, 16, 'BE', 'Fraueninfrastruktur sichern und ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=213', null, 'gemischt', '2026-09-29', false, true),
  (6501, 9, 16, 'BE', 'Verpflichtende Täter*innenkurse', '{904}', 1, 3, null, 'Täterprogramme sollen Wiederholungstaten verhindern; Studien finden eher kleine und uneinheitliche Effekte. Das Land kann Angebote fördern, als Auflage anordnen können sie Gerichte und Staatsanwaltschaften nach Bundesrecht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', null, 'gemischt', '2026-09-29', false, true),
  (6502, 9, 17, 'ST', 'Mehr Plätze in Frauenhäusern und Schutzwohnungen, dauerhafte Finanzierung', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', null, 'gemischt', '2026-09-29', false, true),
  (6503, 9, 17, 'MV', 'Frauenhausplätze und Schutzwohnungen ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6504, 9, 17, 'MV', 'Wegweisungen und Annäherungsverbote konsequent durchsetzen', '{904}', 2, 3, null, 'Elektronisch überwachte oder konsequent durchgesetzte Kontakt- und Näherungsverbote schützen Betroffene vor erneuten Angriffen; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Die Länder können es über ihr Polizeirecht regeln, mehrere tun es bereits.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'gemischt', '2026-09-29', false, true),
  (6505, 9, 17, 'BE', 'Spanisches Modell: Fußfessel bei Annäherungsverbot mit Warnsystem', '{904}', 2, 3, null, 'Elektronisch überwachte oder konsequent durchgesetzte Kontakt- und Näherungsverbote schützen Betroffene vor erneuten Angriffen; die Erfahrungen etwa aus Spanien gelten als gut, belastbare Wirkungsstudien sind aber rar. Die Länder können es über ihr Polizeirecht regeln, mehrere tun es bereits.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6506, 9, 17, 'BE', 'Frauenhäuser ausbauen', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Das Land ist zuständig und bekommt Bundesmittel aus dem Gewalthilfegesetz; Plätze und Fachpersonal aufzubauen dauert.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6507, 9, 17, null, 'Schutzwohnungen und Frauenhausplätze deutlich erhöhen, Finanzierung durch den Bund sichern, Aufenthalt kostenfrei', '{904}', 2, 2, null, 'Mehr Schutzplätze und Beratung schützen Betroffene akut und erleichtern die Trennung vom Täter; dass sie die Zahl der Taten senken, ist kaum belegt. Der Bund kann sich finanziell beteiligen, wie mit dem Gewalthilfegesetz; Ausbau und Betrieb liegen bei Ländern und Kommunen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-09-29', false, true),
  (6530, 9, 11, null, 'Telekommunikationsüberwachung und Funkzellenauswertung ausweiten, etwa gegen den Enkeltrick', '{906}', 1, 3, null, 'Mehr Befugnisse zur Überwachung von Telefonen und Funkzellen können helfen, Abholer und Helfer bei Enkeltrick und Schockanrufen zu fassen; die Hintermänner sitzen oft in Callcentern im Ausland und bleiben meist unerreichbar. Der Bund regelt die Strafprozessordnung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6531, 9, 11, null, 'Sicherheitsbehörden für Cybersicherheit mit Befugnissen, Fachpersonal und Infrastruktur ausstatten', '{906}', 1, 2, null, 'Mehr Fachleute und Technik verbessern die Aufklärung von Taten im Inland; ein wachsender Teil von Betrug und Cyberkriminalität wird aber aus dem Ausland begangen, wo deutsche Ermittler wenig ausrichten. Der Bund kann das BKA stärken, die meisten Ermittlungen führen die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6532, 9, 11, null, 'Europol zur europäischen Zentralstelle ausbauen, auch gegen Cyberkriminalität', '{906}', 2, 1, null, 'Gemeinsame europäische Ermittlungen setzen daran an, dass Betrug und Cyberkriminalität zunehmend aus dem Ausland kommen; Taten aus Staaten außerhalb der EU erreicht auch Europol nur mit deren Hilfe. Eigene Befugnisse für Europol muss die EU beschließen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (6533, 9, 11, null, 'Gesetz zur Bekämpfung des Extremismus: Werben für Terrororganisationen strafbar, Regelausweisung', '{907}', 1, 2, null, 'Neue Straftatbestände, etwa für das Werben für Terrororganisationen, erfassen mehr Taten; dass sie Gewalt verhindern, ist kaum belegt. Grenzen setzt die Meinungsfreiheit, der Bund ist für das Strafrecht zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6534, 9, 11, null, 'Antisemitische Straftat führt zum Verlust des Schutzstatus und zur Abschiebung', '{907}', 1, 2, null, 'Wer ausgewiesen wird, begeht hier keine weiteren Taten; der größere Teil der politisch motivierten Straftaten geht aber von Deutschen aus, und Abschiebungen scheitern oft an Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'gemischt', '2026-09-29', false, true),
  (6535, 9, 11, null, 'Moscheen schließen, in denen Hass und Antisemitismus gepredigt wird', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6536, 9, 11, null, 'Extremisten entwaffnen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Der Bund regelt das Waffenrecht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6537, 9, 11, null, 'Nachrichtendiensten die nötigen Befugnisse geben, um Gefahren für die Grundordnung früh zu erkennen', '{907}', 1, 3, null, 'Mehr Personal, Technik und Befugnisse können Anschlagspläne und Netzwerke früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Der Bund kann seine Behörden selbst ausstatten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6538, 9, 11, null, 'Gruppenvergewaltigungen deutlich härter bestrafen', '{908}', 1, 3, null, 'Höhere Strafen schrecken nach der Forschung kaum ab; das größere Problem ist, dass nur wenige Taten angezeigt und verurteilt werden. Der Bund ist für das Strafrecht zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'gemischt', '2026-09-29', false, true),
  (6539, 9, 12, null, 'Kompetenzen der Sicherheitsbehörden gegen Cybercrime stärken', '{906}', 1, 2, null, 'Mehr Fachleute und Technik verbessern die Aufklärung von Taten im Inland; ein wachsender Teil von Betrug und Cyberkriminalität wird aber aus dem Ausland begangen, wo deutsche Ermittler wenig ausrichten. Der Bund kann das BKA stärken, die meisten Ermittlungen führen die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6540, 9, 12, null, 'IP-Adressen und Portnummern zur Strafverfolgung sichern, ergänzt um die Login-Falle', '{906}', 1, 2, null, 'Gespeicherte IP-Adressen machen es leichter, Täter im Internet einem Anschluss zuzuordnen; bei Tätern im Ausland oder mit Verschleierung hilft das wenig. Eine Speicherpflicht muss die engen Vorgaben des Europäischen Gerichtshofs einhalten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6541, 9, 12, null, 'Demokratiefördergesetz: Initiativen wie „Demokratie leben!“ nachhaltig fördern', '{907}', 1, 3, null, 'Präventions- und Ausstiegsprogramme können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Der Bund kann eigene Programme wie „Demokratie leben!“ gesetzlich absichern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'gemischt', '2026-09-29', false, true),
  (6542, 9, 12, null, 'Finanzquellen rechtsextremistischer Netzwerke offenlegen und austrocknen', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6543, 9, 12, null, 'Extremistische Bestrebungen intensiv überwachen, früher eingreifen', '{907}', 1, 3, null, 'Mehr Personal, Technik und Befugnisse können Anschlagspläne und Netzwerke früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Der Bund kann seine Behörden selbst ausstatten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6544, 9, 12, null, 'Hasskriminalität im Netz bekämpfen, Plattformen zum Entfernen illegaler Inhalte verpflichten', '{907}', 1, 2, null, 'Bessere Ermittlungsbefugnisse im Netz, etwa die Login-Falle, und Pflichten für Plattformen können mehr Täter erreichen; ein großer Teil der Plattformregeln liegt inzwischen bei der EU (Digital Services Act).', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'gemischt', '2026-09-29', false, true),
  (6545, 9, 12, null, 'Jede sexuelle Handlung ohne eindeutiges Einverständnis unter Strafe stellen', '{908}', 1, 3, null, 'Eine Zustimmungslösung macht mehr Übergriffe strafbar als das seit 2016 geltende „Nein heißt Nein“; Beweisprobleme im Verfahren bleiben. Erfahrungen etwa aus Schweden zeigen mehr Verurteilungen, die Wirkung auf die Zahl der Taten ist offen. Der Bund ist zuständig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'gemischt', '2026-09-29', false, true),
  (6546, 9, 13, null, 'Polizeiliche Ermittlungen im digitalen Raum stärken', '{906}', 1, 2, null, 'Mehr Fachleute und Technik verbessern die Aufklärung von Taten im Inland; ein wachsender Teil von Betrug und Cyberkriminalität wird aber aus dem Ausland begangen, wo deutsche Ermittler wenig ausrichten. Der Bund kann das BKA stärken, die meisten Ermittlungen führen die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'gemischt', '2026-09-29', false, true),
  (6547, 9, 13, null, 'Quick-Freeze-Verfahren für die Strafverfolgung im digitalen Raum', '{906}', 1, 3, null, 'Im Verdachtsfall lassen sich vorhandene Verbindungsdaten auf Anordnung einfrieren; sind sie beim Anbieter schon gelöscht, hilft das Verfahren nicht. Der Bund kann es in der Strafprozessordnung regeln.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', null, 'gemischt', '2026-09-29', false, true),
  (6548, 9, 13, null, 'Europol zu einem Europäischen Kriminalamt mit operativen Möglichkeiten weiterentwickeln', '{906}', 2, 1, null, 'Gemeinsame europäische Ermittlungen setzen daran an, dass Betrug und Cyberkriminalität zunehmend aus dem Ausland kommen; Taten aus Staaten außerhalb der EU erreicht auch Europol nur mit deren Hilfe. Eigene Befugnisse für Europol muss die EU beschließen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'gemischt', '2026-09-29', false, true),
  (6549, 9, 13, null, 'Prävention, Aussteiger- und Deradikalisierungsprogramme stärken und mit einem Demokratiefördergesetz absichern', '{907}', 1, 3, null, 'Präventions- und Ausstiegsprogramme können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Der Bund kann eigene Programme wie „Demokratie leben!“ gesetzlich absichern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'gemischt', '2026-09-29', false, true),
  (6550, 9, 13, null, 'Extremistische Netzwerke beobachten, Vereinsverbote konsequent aussprechen', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'gemischt', '2026-09-29', false, true),
  (6551, 9, 13, null, 'Verfassungsfeinde konsequent entwaffnen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Der Bund regelt das Waffenrecht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'gemischt', '2026-09-29', false, true),
  (6552, 9, 13, null, 'BKA und Verfassungsschutz gegen Terrorismus mit Personal, Technik und Befugnissen ausstatten', '{907}', 1, 3, null, 'Mehr Personal, Technik und Befugnisse können Anschlagspläne und Netzwerke früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Der Bund kann seine Behörden selbst ausstatten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'gemischt', '2026-09-29', false, true),
  (6553, 9, 13, null, 'Strafverfolgung von Hasskriminalität im Netz stärken, Login-Falle', '{907}', 1, 2, null, 'Bessere Ermittlungsbefugnisse im Netz, etwa die Login-Falle, und Pflichten für Plattformen können mehr Täter erreichen; ein großer Teil der Plattformregeln liegt inzwischen bei der EU (Digital Services Act).', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', null, 'gemischt', '2026-09-29', false, true),
  (6554, 9, 13, null, 'Sexualstrafrecht mit der Zustimmungslösung reformieren', '{908}', 1, 3, null, 'Eine Zustimmungslösung macht mehr Übergriffe strafbar als das seit 2016 geltende „Nein heißt Nein“; Beweisprobleme im Verfahren bleiben. Erfahrungen etwa aus Schweden zeigen mehr Verurteilungen, die Wirkung auf die Zahl der Taten ist offen. Der Bund ist zuständig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6555, 9, 13, null, 'Einsatz von K.-o.-Tropfen bei sexuellen Übergriffen als strafverschärfend aufnehmen', '{908}', 1, 3, null, 'Höhere Strafen schrecken nach der Forschung kaum ab; das größere Problem ist, dass nur wenige Taten angezeigt und verurteilt werden. Der Bund ist für das Strafrecht zuständig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', null, 'gemischt', '2026-09-29', false, true),
  (6556, 9, 13, null, 'Flächendeckende medizinische Notfallversorgung nach Vergewaltigung mit anonymer Spurensicherung', '{908}', 1, 2, null, 'Eine vertrauliche Spurensicherung erlaubt Betroffenen, Beweise zu sichern und sich später für eine Anzeige zu entscheiden; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Die Krankenkassen zahlen sie bereits, das Angebot vor Ort organisieren die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', null, 'offen', '2026-09-29', false, true),
  (6557, 9, 14, null, 'Europol zu einem Europäischen Kriminalamt ausbauen, auch gegen Cyberkriminalität', '{906}', 2, 1, null, 'Gemeinsame europäische Ermittlungen setzen daran an, dass Betrug und Cyberkriminalität zunehmend aus dem Ausland kommen; Taten aus Staaten außerhalb der EU erreicht auch Europol nur mit deren Hilfe. Eigene Befugnisse für Europol muss die EU beschließen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
  (6558, 9, 14, null, 'Quick Freeze: Daten im Verdachtsfall auf richterliche Anordnung sichern', '{906}', 1, 3, null, 'Im Verdachtsfall lassen sich vorhandene Verbindungsdaten auf Anordnung einfrieren; sind sie beim Anbieter schon gelöscht, hilft das Verfahren nicht. Der Bund kann es in der Strafprozessordnung regeln.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6559, 9, 14, null, 'Wissenschaftliche Expertise der Sicherheitsbehörden gegen Extremismus ausbauen, gefährdete Gruppen schützen', '{907}', 1, 3, null, 'Mehr Personal, Technik und Befugnisse können Anschlagspläne und Netzwerke früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Der Bund kann seine Behörden selbst ausstatten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'gemischt', '2026-09-29', false, true),
  (6560, 9, 14, null, 'Mehr Betätigungs- und Organisationsverbote für antisemitische Organisationen', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=51', null, 'gemischt', '2026-09-29', false, true),
  (6561, 9, 14, null, 'Beim Waffenrecht den Fokus auf Gefährder und Extremisten legen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Der Bund regelt das Waffenrecht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6562, 9, 14, null, 'Präventions- und Deradikalisierungsprogramme auf ihre Wirksamkeit überprüfen', '{907}', 1, 3, null, 'Eine Überprüfung kann Geld zu wirksamen Programmen lenken; eine Wirkung auf Straftaten hat sie nur mittelbar. Der Bund kann seine Programme selbst evaluieren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-09-29', false, true),
  (6563, 9, 15, null, 'Organisationen des gewaltsamen Linksextremismus verbieten; islamistische Vereine verbieten', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=121', null, 'gemischt', '2026-09-29', false, true),
  (6564, 9, 15, null, 'Öffentliche Forderung nach einem Kalifat unter Strafe stellen', '{907}', 1, 2, null, 'Neue Straftatbestände, etwa für das Werben für Terrororganisationen, erfassen mehr Taten; dass sie Gewalt verhindern, ist kaum belegt. Grenzen setzt die Meinungsfreiheit, der Bund ist für das Strafrecht zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'gemischt', '2026-09-29', false, true),
  (6565, 9, 15, null, 'Ausländische Gefährder und Extremisten vorrangig zurückführen', '{907}', 1, 2, null, 'Wer ausgewiesen wird, begeht hier keine weiteren Taten; der größere Teil der politisch motivierten Straftaten geht aber von Deutschen aus, und Abschiebungen scheitern oft an Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', null, 'gemischt', '2026-09-29', false, true),
  (6566, 9, 15, null, 'Ausweisung ausländischer Straftäter bei Sexualdelikten deutlich erleichtern', '{908}', 1, 2, null, 'Abschiebungen verurteilter ausländischer Straftäter verhindern weitere Taten dieser Personen hier; die meisten nichtdeutschen Tatverdächtigen sind aber nicht ausreisepflichtig, und Abschiebungen scheitern oft an Papieren oder Herkunftsstaaten. Der Bund regelt das Aufenthaltsrecht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', null, 'gemischt', '2026-09-29', false, true),
  (6567, 9, 16, null, 'Kriminalpolizei und Staatsanwaltschaft in die Lage versetzen, mit Cyber-Kriminalität Schritt zu halten', '{906}', 1, 2, null, 'Mehr Fachleute und Technik verbessern die Aufklärung von Taten im Inland; ein wachsender Teil von Betrug und Cyberkriminalität wird aber aus dem Ausland begangen, wo deutsche Ermittler wenig ausrichten. Der Bund kann das BKA stärken, die meisten Ermittlungen führen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'gemischt', '2026-09-29', false, true),
  (6568, 9, 16, null, 'Mobile Beratung gegen Rechtsextremismus und Opferberatungen mit einem Demokratiefördergesetz absichern', '{907}', 1, 3, null, 'Präventions- und Ausstiegsprogramme können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Der Bund kann eigene Programme wie „Demokratie leben!“ gesetzlich absichern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'gemischt', '2026-09-29', false, true),
  (6569, 9, 16, null, 'Militante, bewaffnete neonazistische Organisationen verbieten', '{907}', 1, 3, null, 'Verbote und Finanzermittlungen schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen, und Einzeltäter erreichen sie nicht. Das Bundesinnenministerium kann bundesweit tätige Vereine verbieten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'gemischt', '2026-09-29', false, true),
  (6570, 9, 16, null, 'Prinzip „Nur Ja heißt Ja“ gesetzlich verankern', '{908}', 1, 3, null, 'Eine Zustimmungslösung macht mehr Übergriffe strafbar als das seit 2016 geltende „Nein heißt Nein“; Beweisprobleme im Verfahren bleiben. Erfahrungen etwa aus Schweden zeigen mehr Verurteilungen, die Wirkung auf die Zahl der Taten ist offen. Der Bund ist zuständig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'gemischt', '2026-09-29', false, true),
  (6571, 9, 16, null, 'Awareness-Konzepte gegen sexualisierte Gewalt bei Großveranstaltungen verpflichtend', '{908}', 1, 1, null, 'Ansprechpersonen und Schutzkonzepte bei Veranstaltungen können Übergriffe verhindern und Betroffenen schnell helfen; belastbare Studien fehlen. Das Veranstaltungs- und Ordnungsrecht liegt bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-09-29', false, true),
  (6572, 9, 11, 'ST', 'Sicherheitsbehörden und Verfassungsschutz gegen zunehmenden Extremismus stärken', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'gemischt', '2026-09-29', false, true),
  (6573, 9, 12, 'ST', 'Verfassungsschutz bei Ausrüstung und Personal verbessern', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=33', null, 'gemischt', '2026-09-29', false, true),
  (6574, 9, 12, 'ST', 'Landesprogramm für Demokratie fortführen und ausbauen, Beratungsstellen und Aussteigerprogramme verlässlich unterstützen', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6575, 9, 12, 'ST', 'Schwerpunktstaatsanwaltschaft Rechtsextremismus', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=35', null, 'offen', '2026-09-29', false, true),
  (6576, 9, 12, 'ST', 'Opferschutz für Opfer von Hasskriminalität und Extremismus ausbauen', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-09-29', false, true),
  (6577, 9, 13, 'ST', 'Erkenntnisse über rechtsextreme Netzwerke nutzen und Strukturen zerschlagen', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6578, 9, 13, 'ST', 'Zivilgesellschaft und Beratungsstellen in der Extremismusprävention stärker unterstützen', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6579, 9, 13, 'ST', 'Waffenbesitz für Extremisten verbieten, Waffenbehörden stärken', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Den Vollzug des Waffenrechts organisieren die Länder.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', null, 'gemischt', '2026-09-29', false, true),
  (6580, 9, 13, 'ST', 'Niedrigschwellige Beratung und psychosoziale Hilfe für Betroffene rechter Gewalt', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', null, 'offen', '2026-09-29', false, true),
  (6581, 9, 13, 'ST', 'Alle Kliniken ins „Netzwerk Evidence“ für anonymisierte Spurensicherung nach sexueller Gewalt', '{908}', 1, 3, null, 'Beratung und eine vertrauliche Spurensicherung helfen Betroffenen und erlauben eine spätere Anzeige; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Das Land kann die Angebote selbst finanzieren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=83', null, 'offen', '2026-09-29', false, true),
  (6582, 9, 15, 'ST', 'Nachrichtendienstlichen und polizeilichen Verfolgungsdruck auf die linksextreme Szene erhöhen', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=112', null, 'gemischt', '2026-09-29', false, true),
  (6583, 9, 15, 'ST', 'Auf Bundesebene Antifa-Organisationen zu Terrororganisationen erklären lassen', '{907}', 1, 1, null, 'Neue Straftatbestände oder Befugnisse können mehr Taten erfassen; dass sie Gewalt verhindern, ist kaum belegt. Das Land kann nur über den Bundesrat darauf hinwirken.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=112', null, 'gemischt', '2026-09-29', false, true),
  (6584, 9, 16, 'ST', 'Mobile Beratungsteams unterstützen Kommunen gegen rechtsextreme Umtriebe', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6585, 9, 16, 'ST', 'Schwerpunktstaatsanwaltschaften für rechtsextrem motivierte Straftaten, spezialisierte Ansprechpersonen für Hasskriminalität', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', null, 'offen', '2026-09-29', false, true),
  (6586, 9, 17, 'ST', 'Islamismusprävention der Halleschen Jugendwerkstatt weiter fördern', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6587, 9, 11, 'MV', 'Auf Bundesebene eine Vorratsdatenspeicherung gegen Hasskriminalität im Internet einfordern', '{907}', 1, 1, null, 'Neue Straftatbestände oder Befugnisse können mehr Taten erfassen; dass sie Gewalt verhindern, ist kaum belegt. Das Land kann nur über den Bundesrat darauf hinwirken.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true),
  (6588, 9, 11, 'MV', 'Extremismus bekämpfen, flankiert von politischer Bildung und Prävention', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', null, 'gemischt', '2026-09-29', false, true),
  (6589, 9, 12, 'MV', 'Rechtsextreme Strukturen durch verschärfte Waffenkontrollen, Entwaffnung, Prävention und Repression zerschlagen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Den Vollzug des Waffenrechts organisieren die Länder.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6590, 9, 12, 'MV', 'Landesprogramm „Demokratie und Toleranz“ mit Opferberatung und Aussteigerhilfe weiter fördern', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=42', null, 'gemischt', '2026-09-29', false, true),
  (6591, 9, 12, 'MV', 'Interventions- und Beratungsstellen für sexualisierte Gewalt besser ausstatten', '{908}', 1, 3, null, 'Beratung und eine vertrauliche Spurensicherung helfen Betroffenen und erlauben eine spätere Anzeige; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Das Land kann die Angebote selbst finanzieren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', null, 'offen', '2026-09-29', false, true),
  (6592, 9, 13, 'MV', 'Landesprogramm „Demokratie und Toleranz“ gesetzlich verankern', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=68', null, 'gemischt', '2026-09-29', false, true),
  (6593, 9, 13, 'MV', 'Polizei und Staatsanwaltschaften gegen politisch motivierte Straftaten im digitalen Raum ausstatten', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'offen', '2026-09-29', false, true),
  (6594, 9, 13, 'MV', 'Beratung für Betroffene von Gewalt und Diskriminierung ausbauen und dauerhaft finanzieren', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', null, 'offen', '2026-09-29', false, true),
  (6595, 9, 13, 'MV', 'Präventionskonzepte gegen sexualisierte Gewalt an Schulen, Hochschulen und am Arbeitsplatz', '{908}', 1, 3, null, 'Präventionsprogramme können Wissen und Haltungen verändern; ob sie Übergriffe messbar verringern, zeigen Studien uneinheitlich. Das Land kann sie selbst fördern.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'gemischt', '2026-09-29', false, true),
  (6596, 9, 14, 'MV', 'Bestehende Präventionsprogramme überprüfen und anpassen', '{907}', 1, 3, null, 'Eine Überprüfung kann Geld zu wirksamen Programmen lenken; eine Wirkung auf Straftaten hat sie nur mittelbar. Das Land kann seine Programme selbst evaluieren.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=145', null, 'offen', '2026-09-29', false, true),
  (6597, 9, 14, 'MV', 'Öffentlichkeitsarbeit und Prävention zu sexualisierter Gewalt ausbauen', '{908}', 1, 3, null, 'Präventionsprogramme können Wissen und Haltungen verändern; ob sie Übergriffe messbar verringern, zeigen Studien uneinheitlich. Das Land kann sie selbst fördern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=53', null, 'gemischt', '2026-09-29', false, true),
  (6598, 9, 15, 'MV', 'Verfassungsschutz reformieren und auf Cybercrime, Spionageabwehr und politische Militanz ausrichten', '{907}', 1, 3, null, 'Ein Fokus auf Gewalt kann Kräfte dort bündeln, wo die größte Gefahr ausgeht; ob sich dadurch Straftaten verringern, ist nicht untersucht. Das Land kann seinen Verfassungsschutz selbst ausrichten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=41', null, 'offen', '2026-09-29', false, true),
  (6599, 9, 15, 'MV', 'Islamverbände verpflichten, Meldestellen für radikale und extremistische Tendenzen vorzuhalten', '{907}', 1, 1, null, 'Hinweise aus dem Umfeld können Radikalisierung früh sichtbar machen; eine Wirkung ist nicht untersucht. Eine Pflicht für Religionsgemeinschaften fehlt im Landesrecht und stößt an die Religionsfreiheit.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=53', null, 'offen', '2026-09-29', false, true),
  (6600, 9, 16, 'MV', 'Präventive Programme gegen Radikalisierung stärken', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', null, 'gemischt', '2026-09-29', false, true),
  (6601, 9, 16, 'MV', 'Gegen militant-rechte Netzwerke vorgehen, Verbote prüfen, Neonazis entwaffnen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Den Vollzug des Waffenrechts organisieren die Länder.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=8', null, 'gemischt', '2026-09-29', false, true),
  (6602, 9, 16, 'MV', 'Projekte gegen sexualisierte Gewalt unterstützen', '{908}', 1, 3, null, 'Präventionsprogramme können Wissen und Haltungen verändern; ob sie Übergriffe messbar verringern, zeigen Studien uneinheitlich. Das Land kann sie selbst fördern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true),
  (6603, 9, 17, 'MV', 'Verfassungsschutz auf gewaltbereiten Extremismus ausrichten, mit Aussteigerprogrammen zusammenarbeiten', '{907}', 1, 3, null, 'Ein Fokus auf Gewalt kann Kräfte dort bündeln, wo die größte Gefahr ausgeht; ob sich dadurch Straftaten verringern, ist nicht untersucht. Das Land kann seinen Verfassungsschutz selbst ausrichten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=70', null, 'offen', '2026-09-29', false, true),
  (6604, 9, 11, 'BE', 'Verfassungsschutz erweiterte Befugnisse zur Extremismusbekämpfung geben', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=21', null, 'gemischt', '2026-09-29', false, true),
