  (6606, 9, 11, 'BE', 'Abteilung für Staatsschutzdelikte und Hasskriminalität bei der Staatsanwaltschaft ausbauen', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-09-29', false, true),
  (6607, 9, 11, 'BE', 'Radikalen Trägerverein der Al-Nur-Moschee verbieten, weitere Verbote prüfen', '{907}', 1, 2, null, 'Verbote schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen. Das Land kann Vereine verbieten, die nur in seinem Gebiet tätig sind, bundesweit tätige Vereine verbietet der Bund.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
  (6608, 9, 11, 'BE', 'Auf Bundesebene Forderungen nach Gottesstaat oder Kalifat strafbar machen', '{907}', 1, 1, null, 'Neue Straftatbestände oder Befugnisse können mehr Taten erfassen; dass sie Gewalt verhindern, ist kaum belegt. Das Land kann nur über den Bundesrat darauf hinwirken.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'gemischt', '2026-09-29', false, true),
