  (6610, 9, 12, 'BE', 'Spezialisierte Beratungsstellen bei Hasskriminalität stärken', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-09-29', false, true),
  (6611, 9, 12, 'BE', 'Staatsanwaltschaft durch Fortbildungen zur organisierten extremen Rechten stärken', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-09-29', false, true),
  (6612, 9, 12, 'BE', 'Gewaltschutzambulanzen ausbauen, vertrauliche Spurensicherung in allen gynäkologischen Notfallkliniken', '{908}', 1, 3, null, 'Beratung und eine vertrauliche Spurensicherung helfen Betroffenen und erlauben eine spätere Anzeige; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Das Land kann die Angebote selbst finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-09-29', false, true),
  (6613, 9, 13, 'BE', 'Landesprogramm gegen Rechtsextremismus, Rassismus und Antisemitismus erweitern', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=159', null, 'gemischt', '2026-09-29', false, true),
  (6614, 9, 13, 'BE', 'Opferberatungsstellen stärken', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'offen', '2026-09-29', false, true),
  (6615, 9, 13, 'BE', 'Staatsschutz stärken, offene Haftbefehle gegen Rechtsextreme vollstrecken', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'gemischt', '2026-09-29', false, true),
  (6616, 9, 13, 'BE', 'Rechtsextremisten und Reichsbürger systematisch entwaffnen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Den Vollzug des Waffenrechts organisieren die Länder.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'gemischt', '2026-09-29', false, true),
  (6617, 9, 13, 'BE', 'Vereinsverbote gegen verfassungsfeindliche Vereinigungen nutzen', '{907}', 1, 2, null, 'Verbote schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen. Das Land kann Vereine verbieten, die nur in seinem Gebiet tätig sind, bundesweit tätige Vereine verbietet der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=230', null, 'gemischt', '2026-09-29', false, true),
  (6618, 9, 13, 'BE', 'Sonderzuständigkeit für Sexualdelikte an den Strafgerichten', '{908}', 1, 3, null, 'Spezialisierte Richterinnen und Richter können Verfahren sachkundiger und für Betroffene schonender führen; belastbare Auswertungen fehlen. Das Land kann die Geschäftsverteilung seiner Gerichte entsprechend gestalten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'offen', '2026-09-29', false, true),
  (6619, 9, 13, 'BE', 'Auf Bundesebene Catcalling unter Strafe stellen', '{908}', 1, 1, null, 'Neue Straftatbestände wie für „Catcalling“ erfassen mehr Übergriffe, ihre abschreckende Wirkung ist offen. Das Land kann nur über den Bundesrat darauf hinwirken.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'gemischt', '2026-09-29', false, true),
  (6620, 9, 14, 'BE', 'Ursachenorientierte Prävention: Aufklärung, Aussteigerprogramme, Vernetzung', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', null, 'gemischt', '2026-09-29', false, true),
  (6621, 9, 14, 'BE', 'Verfassungsschutzämter Berlin und Brandenburg fusionieren', '{907}', 1, 2, null, 'Ein gemeinsames Amt kann Kräfte bündeln; ob es Extremismus wirksamer bekämpft, ist nicht untersucht. Die Fusion braucht einen Staatsvertrag mit dem Nachbarland.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'offen', '2026-09-29', false, true),
  (6622, 9, 14, 'BE', 'Polizei, Staatsanwaltschaft und Gerichte für antisemitische Straftaten sensibilisieren', '{907}', 1, 3, null, 'Schwerpunktstaatsanwaltschaften und geschulte Ermittler bündeln Fachwissen und können Verfahren beschleunigen; belastbare Auswertungen dazu fehlen. Das Land kann seine Justiz selbst so organisieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=78', null, 'offen', '2026-09-29', false, true),
  (6623, 9, 14, 'BE', 'Gewaltschutzambulanz stärken und ausbauen', '{908}', 1, 3, null, 'Beratung und eine vertrauliche Spurensicherung helfen Betroffenen und erlauben eine spätere Anzeige; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Das Land kann die Angebote selbst finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=69', null, 'offen', '2026-09-29', false, true),
  (6624, 9, 15, 'BE', 'Stärkere Beobachtung und Überwachung links- und islamistisch-extremistischer Strukturen', '{907}', 1, 3, null, 'Mehr Personal und Befugnisse können extremistische Netzwerke und Anschlagspläne früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Das Land kann seine Behörden selbst ausstatten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=17', null, 'gemischt', '2026-09-29', false, true),
  (6625, 9, 15, 'BE', 'Islamistische Gefährder konsequent abschieben', '{907}', 1, 2, null, 'Wer abgeschoben wird, begeht hier keine weiteren Taten; der größere Teil der politisch motivierten Straftaten geht aber von Deutschen aus. Das Land vollzieht Abschiebungen, ist aber auf Bundesrecht und die Herkunftsstaaten angewiesen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=17', null, 'gemischt', '2026-09-29', false, true),
  (6626, 9, 15, 'BE', 'Verfassungsfeindliche Moscheen schließen, Vereinsverbote', '{907}', 1, 2, null, 'Verbote schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen. Das Land kann Vereine verbieten, die nur in seinem Gebiet tätig sind, bundesweit tätige Vereine verbietet der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', null, 'gemischt', '2026-09-29', false, true),
  (6627, 9, 15, 'BE', 'Sexualstraftäter im Justizvollzug über chemische Kastration aufklären', '{908}', 1, 3, null, 'Eine freiwillige medikamentöse Behandlung kann bei einzelnen Tätern Rückfälle senken, Studien kommen zu unterschiedlichen Ergebnissen; sie erreicht nur bereits verurteilte Täter. Das Land kann im Justizvollzug darüber informieren.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', null, 'gemischt', '2026-09-29', false, true),
  (6628, 9, 15, 'BE', 'Über den Bundesrat Doppelstaatlern nach schweren Sexualstraftaten die Staatsangehörigkeit aberkennen', '{908}', 1, 1, null, 'Der Entzug soll eine spätere Abschiebung ermöglichen und betrifft nur wenige Täter; ob er Taten verhindert, ist nicht untersucht. Das Grundgesetz verbietet den Entzug der Staatsangehörigkeit weitgehend, das Land kann nur über den Bundesrat darauf hinwirken.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=26', null, 'offen', '2026-09-29', false, true),
  (6629, 9, 16, 'BE', 'Demokratie-Projekte über ein Demokratiefördergesetz langfristig absichern, Aussteigerprogramme ausbauen', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=270', null, 'gemischt', '2026-09-29', false, true),
  (6630, 9, 16, 'BE', 'Alle militanten neonazistischen Organisationen verbieten', '{907}', 1, 2, null, 'Verbote schwächen Strukturen, die Straftaten organisieren; oft entstehen Nachfolgegruppen. Das Land kann Vereine verbieten, die nur in seinem Gebiet tätig sind, bundesweit tätige Vereine verbietet der Bund.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=328', null, 'gemischt', '2026-09-29', false, true),
  (6631, 9, 16, 'BE', 'Rechte Strukturen konsequent entwaffnen', '{907}', 1, 3, null, 'Wer als Extremist bekannt ist, soll keine legalen Waffen besitzen; das verringert das Risiko schwerer Taten, die meisten politisch motivierten Straftaten werden aber ohne Schusswaffe begangen. Den Vollzug des Waffenrechts organisieren die Länder.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=329', null, 'gemischt', '2026-09-29', false, true),
  (6632, 9, 16, 'BE', 'Projekte stärken, die antisemitische Vorfälle erfassen, Opfer beraten und vorbeugen', '{907}', 1, 3, null, 'Opferberatung hilft Betroffenen und kann dazu beitragen, dass mehr Taten angezeigt werden; weniger Taten folgen daraus nicht unmittelbar. Das Land kann sie selbst finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=271', null, 'offen', '2026-09-29', false, true),
  (6633, 9, 16, 'BE', 'Anonyme und vertrauliche Spurensicherung flächendeckend und rund um die Uhr', '{908}', 1, 3, null, 'Beratung und eine vertrauliche Spurensicherung helfen Betroffenen und erlauben eine spätere Anzeige; ob dadurch mehr Taten verfolgt werden, ist kaum untersucht. Das Land kann die Angebote selbst finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=142', null, 'offen', '2026-09-29', false, true),
  (6634, 9, 17, 'BE', 'Entradikalisierungsprogramme', '{907}', 1, 3, null, 'Mobile Beratung, Aussteigerhilfe und Präventionsprojekte können einzelne Menschen von Gewalt abhalten; wie stark sie Straftaten insgesamt senken, ist kaum untersucht. Das Land kann sie selbst finanzieren.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=38', null, 'gemischt', '2026-09-29', false, true),
  (6635, 9, 17, null, 'Polizei mit modernen Einsatzmitteln und IT ausstatten, auch gegen Cyberkriminalität', '{906}', 1, 2, null, 'Mehr Fachleute und Technik verbessern die Aufklärung von Taten im Inland; ein wachsender Teil von Betrug und Cyberkriminalität wird aber aus dem Ausland begangen, wo deutsche Ermittler wenig ausrichten. Der Bund kann das BKA stärken, die meisten Ermittlungen führen die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'gemischt', '2026-09-30', false, true),
  (6636, 9, 17, null, 'Polizei in die Lage versetzen, Terroristen und Extremisten wirksamer das Handwerk zu legen', '{907}', 1, 3, null, 'Mehr Personal, Technik und Befugnisse können Anschlagspläne und Netzwerke früher aufdecken; auf die große Zahl einzelner Straftaten wie Propaganda oder Sachbeschädigung wirkt das kaum. Der Bund kann seine Behörden selbst ausstatten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'gemischt', '2026-09-30', false, true),
  (6643, 2, 13, null, 'Mietwucher leichter ahnden (§ 5 Wirtschaftsstrafgesetz), Indexmieten durch Obergrenzen begrenzen', '{202,204}', 1, 3, '{"mieter":{"wert":1,"begruendung":"Stärkt die Rechte von Mieterinnen und Mietern unmittelbar."}}'::jsonb, 'Erleichtert es, überhöhte Mieten zurückzufordern, und begrenzt Erhöhungen bei Indexmieten; wirkt nur für einen Teil der Verträge und schafft keine Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'offen', '2026-09-30', false, true),
  (6644, 2, 15, null, 'Keine Zuweisung von Asylberechtigten und Asylbewerbern mehr in angespannte Wohnungsmärkte', '{205}', 1, 2, null, 'Verringert die Nachfrage in angespannten Märkten nur für eine kleine Gruppe und verlagert sie in andere Regionen; anerkannte Flüchtlinge dürfen nur befristet und zur Integration an einen Wohnort gebunden werden (§ 12a AufenthG).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=111', null, 'offen', '2026-09-30', false, true),
  (6651, 2, 11, 'ST', 'Sozialen Wohnungsbau fördern, Wohnraumförderprogramme des Bundes weiter kofinanzieren', '{206}', 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=65', null, 'belegt', '2026-09-30', false, true),
  (6652, 2, 12, 'ST', 'Sozialen Wohnungsbau stärken, Bundesmittel nutzen und kofinanzieren', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', null, 'belegt', '2026-09-30', false, true),
  (6653, 2, 13, 'ST', 'Sozialen Wohnungsbau und die Bundesmittel dafür in Sachsen-Anhalt nutzbar machen', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=91', null, 'belegt', '2026-09-30', false, true),
  (6654, 2, 15, 'ST', '1:1-Kofinanzierung der Bundesmittel für den sozialen Wohnungsbau wiederbeleben', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=190', null, 'belegt', '2026-09-30', false, true),
  (6655, 2, 16, 'ST', 'Wohnungsbauförderung nur noch für unbefristet gebundenen sozialen Mietwohnungsbau', '{206}', 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=83', null, 'gemischt', '2026-09-30', false, true),
  (6656, 2, 16, 'ST', 'Landeswohnungsbaugesellschaft gründen, deren Wohnungen nicht aus der Sozialbindung fallen', '{206}', 2, 2, null, 'Eine eigene Gesellschaft kann dauerhaft gebundene Wohnungen bauen, wo andere nicht investieren; Aufbau und Eigenkapital kosten Zeit und Geld, und in vielen Regionen Sachsen-Anhalts fehlt eher Nachfrage als Angebot.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=84', null, 'offen', '2026-09-30', false, true),
  (6657, 2, 17, 'ST', 'Sozialen und gemeinnützigen Wohnungsbau deutlich ausweiten', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=30', null, 'belegt', '2026-09-30', false, true),
  (6658, 2, 11, 'MV', 'Eigenes Landesprogramm zur Förderung des Mietwohnungsbaus, vor allem für kommunale und genossenschaftliche Wohnungsunternehmen', '{206}', 1, 3, null, 'Mehr geförderte Mietwohnungen kommunaler und genossenschaftlicher Unternehmen können günstige Wohnungen sichern; das Programm nennt aber weder Miet- noch Belegungsbindungen noch einen Umfang.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-09-30', false, true),
  (6659, 2, 12, 'MV', 'Landesförderprogramm für sozialen Wohnungsneubau fortführen', '{206}', 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=54', null, 'belegt', '2026-09-30', false, true),
  (6660, 2, 13, 'MV', 'Landesprogramm „Wohnungsbau Sozial“ aufstocken, höhere Zuschüsse für Sozialwohnungen', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', null, 'belegt', '2026-09-30', false, true),
  (6661, 2, 13, 'MV', 'Sozialbindung entfristen', '{206}', 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true),
  (6662, 2, 13, 'MV', 'Höhere Quote für Sozialwohnungen bei Neubauten', '{206}', 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true),
  (6663, 2, 16, 'MV', 'Förderprogramme für den sozialen Wohnungsbau reformieren und attraktiver machen', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'belegt', '2026-09-30', false, true),
  (6664, 2, 17, 'MV', 'Sozialen Wohnungsbau mit verlässlichen Landesprogrammen bedarfsgerecht ausbauen', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=21', null, 'belegt', '2026-09-30', false, true),
  (6665, 2, 11, 'BE', 'Wohnraumförderung fortführen (rund 5.000 neue Sozialwohnungen im Jahr, Wohnraumförderfonds)', '{206}', 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=29', null, 'belegt', '2026-09-30', false, true),
  (6666, 2, 11, 'BE', 'Einkommensprüfung in Sozialwohnungen mit Mietzuschlag, Einnahmen für neue Sozialwohnungen', '{206}', 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=31', null, 'gemischt', '2026-09-30', false, true),
  (6667, 2, 12, 'BE', 'Quote für Sozialwohnungen im kooperativen Baulandmodell von 30 auf 50 Prozent erhöhen', '{206}', 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=18', null, 'gemischt', '2026-09-30', false, true),
  (6668, 2, 12, 'BE', 'Eigentümer ab 50 Wohnungen verpflichten, einen Anteil an Haushalte mit Wohnberechtigungsschein zu vermieten', '{206}', 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=21', null, 'offen', '2026-09-30', false, true),
  (6669, 2, 13, 'BE', 'Quote für mietpreisgebundene Wohnungen in der kooperativen Baulandentwicklung auf 50 Prozent erhöhen', '{206}', 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=60', null, 'gemischt', '2026-09-30', false, true),
  (6670, 2, 14, 'BE', 'Fehlbelegungsabgabe am Marktpreis orientiert', '{206}', 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=42', null, 'gemischt', '2026-09-30', false, true),
  (6671, 2, 15, 'BE', 'Fehlbelegungsabgabe wieder einführen', '{206}', 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=6', null, 'gemischt', '2026-09-30', false, true),
  (6672, 2, 16, 'BE', 'Bestände mit auslaufenden Bindungen ankaufen, Förderprogramm zur Verlängerung auslaufender Bindungen', '{206}', 2, 2, null, 'Setzt direkt am Auslaufen der Bindungen an; Ankäufe und Verlängerungen sind teuer und schaffen keine zusätzlichen Wohnungen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=33', null, 'gemischt', '2026-09-30', false, true),
  (6673, 2, 16, 'BE', 'Kooperative Baulandentwicklung: mindestens zwei Drittel mietpreis- und belegungsgebundene Wohnungen', '{206}', 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=36', null, 'gemischt', '2026-09-30', false, true),
  (6674, 2, 16, 'BE', 'Sicher-Wohnen-Gesetz: große Vermieter müssen einen Teil frei werdender Wohnungen zu Sozialmieten vermieten', '{206}', 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=23', null, 'offen', '2026-09-30', false, true),
  (6675, 2, 17, 'BE', 'Mindestens 6.000 neue Sozialwohnungen pro Jahr', '{206}', 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'belegt', '2026-09-30', false, true),
  (6676, 2, 17, 'BE', 'Öffentlich geförderte Wohnungen dauerhaft binden', '{206}', 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'gemischt', '2026-09-30', false, true),
  (6682, 1, 11, null, 'Hausarztpraxen sollen Patientinnen und Patienten stärker steuern, um Wartezeiten zu senken', '{102}', 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', null, 'gemischt', '2026-09-30', false, true),
  (6683, 1, 11, null, 'Andere Gesundheitsberufe sollen mehr Verantwortung für die Versorgung übernehmen', '{102}', 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=69', null, 'belegt', '2026-09-30', false, true),
  (6684, 1, 12, null, 'Gründung kommunaler MVZ erleichtern', '{101}', 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'gemischt', '2026-09-30', false, true),
  (6685, 1, 12, null, 'Advanced Practice Nurses und Gemeindeschwestern einführen', '{102}', 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'belegt', '2026-09-30', false, true),
  (6686, 1, 12, null, 'Termingarantie: Gesetzlich Versicherte sollen so schnell wie Privatversicherte einen Termin bekommen, sonst sinkt ihr Beitrag', '{102,103}', 1, 2, null, 'Setzt Krankenkassen und Kassenärztliche Vereinigungen unter Druck, Termine zu vermitteln, schafft aber selbst keine zusätzlichen Termine; Terminservicestellen gibt es bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'offen', '2026-09-30', false, true),
  (6687, 1, 12, null, 'Bürgerversicherung mit einheitlichem Vergütungssystem', '{103}', 2, 1, null, 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'gemischt', '2026-09-30', false, true),
  (6688, 1, 13, null, 'Hausärztlich-zentrierte Primärversorgung stärken', '{102}', 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'gemischt', '2026-09-30', false, true),
  (6689, 1, 13, null, 'Zusammenarbeit mit anderen Gesundheitsberufen wie Community Health Nurses ausbauen', '{102}', 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'belegt', '2026-09-30', false, true),
  (6690, 1, 13, null, 'Gründung kommunaler MVZ und Primärversorgungszentren fördern', '{101}', 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'gemischt', '2026-09-30', false, true),
  (6691, 1, 13, null, 'Mehr Sprechstunden für gesetzlich Versicherte', '{103}', 1, 3, null, 'Verschiebt Termine zu gesetzlich Versicherten; Mindestsprechstunden gibt es schon, und ohne mehr Ärztinnen und Ärzte entstehen insgesamt kaum zusätzliche Termine.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'offen', '2026-09-30', false, true),
  (6692, 1, 13, null, 'Anspruch auf Patientenlotsen', '{102}', 1, 2, null, 'Lotsen können Wege durch das System verkürzen, vor allem für chronisch Kranke; für die Terminlage insgesamt ist die Wirkung klein, und es braucht zusätzliches Personal.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=89', null, 'offen', '2026-09-30', false, true),
  (6693, 1, 14, null, 'Primärarztsystem: Haus- und Kinderärzte als erste Anlaufstelle', '{102}', 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-09-30', false, true),
  (6694, 1, 14, null, 'Ungekürzte Vergütung, Behandlung ohne Budgetierung', '{101,103}', 1, 2, null, 'Voll bezahlte Leistungen machen Kassenpatienten für Praxen attraktiver und verringern den Vergütungsabstand zu Privatversicherten; ob dadurch spürbar mehr Termine entstehen, ist nicht belegt, und die Mehrkosten tragen die Beitragszahlenden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-09-30', false, true),
  (6695, 1, 15, null, 'Budgetierung ärztlicher Leistungen beenden', '{101,103}', 1, 2, null, 'Voll bezahlte Leistungen machen Kassenpatienten für Praxen attraktiver und verringern den Vergütungsabstand zu Privatversicherten; ob dadurch spürbar mehr Termine entstehen, ist nicht belegt, und die Mehrkosten tragen die Beitragszahlenden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true),
  (6696, 1, 15, null, 'Gestaffelte Bonus- und Rückvergütungssysteme gegen Bagatellbehandlungen', '{102}', 1, 2, null, 'Finanzielle Anreize können Arztbesuche etwas senken; die Praxisgebühr von 2004 bis 2012 hatte nur kurz Wirkung und belastete vor allem Menschen mit geringem Einkommen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true),
  (6697, 1, 15, null, 'Finanzielle und organisatorische Niederlassungshilfen für Ärzte auf dem Land', '{101}', 1, 3, null, 'Zuschüsse für die Niederlassung gibt es bereits bei Kassenärztlichen Vereinigungen und Ländern; sie wirken bisher nur begrenzt, weil viele junge Ärztinnen und Ärzte eine Anstellung bevorzugen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true),
  (6698, 1, 15, null, 'Mehr Studienplätze in Human- und Zahnmedizin', '{101}', 2, 2, null, 'Mehr Absolventinnen und Absolventen setzen am Nachwuchsmangel an, wirken aber erst nach etwa zwölf Jahren Studium und Weiterbildung; ob sie Hausärzte auf dem Land werden, ist offen. Studienplätze finanzieren die Länder, der Bund kann nur mitfinanzieren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=34', null, 'gemischt', '2026-09-30', false, true),
  (6699, 1, 16, null, 'Kommunale Versorgungszentren als Rückgrat der wohnortnahen Versorgung fördern', '{101}', 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'gemischt', '2026-09-30', false, true),
  (6700, 1, 16, null, 'Kleinere Versorgungsbezirke, von Ländern und Kommunen bestimmt', '{101}', 1, 2, null, 'Kleinere Planungsbereiche machen Unterversorgung in einzelnen Stadtteilen und Dörfern sichtbar und können Niederlassungen dorthin lenken; zusätzliche Ärztinnen und Ärzte entstehen dadurch nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-09-30', false, true),
  (6701, 1, 16, null, 'Befugnisse der Heilberufe ausweiten', '{102}', 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'belegt', '2026-09-30', false, true),
  (6702, 1, 16, null, 'Privatversicherte in die gesetzliche Krankenversicherung übernehmen', '{103}', 2, 1, null, 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-30', false, true),
  (6710, 3, 11, null, 'Netzentgelte senken und neu regeln', '{301}', 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true),
  (6711, 3, 11, null, 'Stromsteuer für alle senken', '{302}', 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true),
  (6712, 3, 11, null, 'Klimabonus als sozialer Ausgleich für den CO₂-Preis', '{302}', 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'belegt', '2026-09-30', false, true),
  (6713, 3, 11, null, 'Prüfen, ob die zuletzt abgeschalteten Kernkraftwerke wieder in Betrieb gehen können', '{304}', 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true),
  (6714, 3, 11, null, 'Smart Meter und Digitalisierung, damit Verbraucher flexibler auf den Strompreis reagieren können', '{304}', 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true),
  (6715, 3, 11, null, 'Investitionen in Energieeffizienz steuerlich schneller absetzbar', '{305}', 1, 2, null, 'Macht Sanierungen und Heizungstausch für Eigentümer günstiger und senkt langfristig den Verbrauch; Mieterinnen und Mieter profitieren nur indirekt, und der Steuervorteil hilft Haushalten mit hohem Einkommen mehr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'gemischt', '2026-09-30', false, true),
  (6716, 3, 12, null, 'Übertragungsnetzentgelte stabilisieren und auf 3 Cent pro Kilowattstunde deckeln', '{301}', 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'belegt', '2026-09-30', false, true),
  (6717, 3, 12, null, 'Klimageld, wenn ab 2027 der europäische CO₂-Preis gilt', '{302}', 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'belegt', '2026-09-30', false, true),
  (6718, 3, 12, null, 'Wind- und Solarenergie konsequent ausbauen, Speicher einbinden', '{304}', 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true),
  (6719, 3, 12, null, 'Soziales Wärmepumpen-Leasing für ärmere Haushalte', '{305}', 1, 2, null, 'Senkt die Hürde, von Gas oder Öl auf eine Wärmepumpe umzusteigen, für Haushalte ohne Ersparnisse; die meisten ärmeren Haushalte wohnen zur Miete und entscheiden nicht über die Heizung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'offen', '2026-09-30', false, true),
  (6720, 3, 13, null, 'Netzentgelte für überregionale Stromleitungen aus dem Deutschlandfonds bezahlen', '{301}', 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true),
  (6721, 3, 13, null, 'Stromsteuer auf das europäische Minimum senken', '{302}', 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true),
  (6722, 3, 13, null, 'Sozial gestaffeltes Klimageld', '{302}', 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'belegt', '2026-09-30', false, true),
  (6723, 3, 13, null, 'Dynamische Stromtarife und flexible Netze', '{304}', 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=42', null, 'gemischt', '2026-09-30', false, true),
  (6724, 3, 13, null, 'Strom in spätestens zehn Jahren vollständig erneuerbar', '{304}', 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, 'gemischt', '2026-09-30', false, true),
  (6725, 3, 13, null, 'Förderung von bis zu 70 Prozent für fossilfreie Heizungen', '{305}', 2, 3, null, 'Macht den Umstieg von Gas und Öl auf Wärmepumpen und Wärmenetze bezahlbarer und koppelt die Heizkosten von fossilen Preisen ab; die Förderung besteht bereits, der Umstieg dauert aber Jahre und hängt vom Strompreis ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true),
  (6726, 3, 14, null, 'Stromsteuer auf das EU-Mindestmaß senken, langfristig abschaffen', '{302}', 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'belegt', '2026-09-30', false, true),
  (6727, 3, 14, null, 'Netzausbau günstiger: Freileitungen statt Erdkabel, dynamische Netzentgelte', '{301}', 2, 2, null, 'Freileitungen sind deutlich billiger als Erdkabel und dämpfen so den Anstieg der Netzentgelte; für viele bereits geplante Leitungen wäre ein Wechsel aufwendig, und Freileitungen stoßen vor Ort häufiger auf Widerstand.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'gemischt', '2026-09-30', false, true),
  (6728, 3, 14, null, 'Klimadividende: Einnahmen aus dem Emissionshandel pro Kopf zurückzahlen', '{302}', 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'belegt', '2026-09-30', false, true),
  (6729, 3, 15, null, 'CO₂-Abgabe abschaffen', '{302,305}', 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true),
  (6730, 3, 15, null, 'Energiesteuer reduzieren, Stromsteuer auf das Minimum senken', '{302}', 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true),
  (6731, 3, 15, null, 'Kohlekraftwerke länger betreiben, Wiedereinstieg in die Kernenergie', '{304}', 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true),
  (6732, 3, 15, null, 'Nord-Stream-Pipelines reparieren und wieder in Betrieb nehmen', '{303}', 1, 0, null, 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true),
  (6733, 3, 15, null, 'Ausbau der Windenergie stoppen, um höhere Netzentgelte zu verhindern', '{301}', 1, 3, null, 'Weniger neue Windparks bedeuten weniger neuen Netzausbau; zugleich fehlt günstiger Windstrom, sodass teurere Kraftwerke den Börsenpreis öfter bestimmen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true),
  (6734, 3, 16, null, 'Soziales Klimageld von 320 Euro pro Person und Jahr', '{302}', 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'belegt', '2026-09-30', false, true),
  (6735, 3, 16, null, 'Neue Netzentgeltstruktur: Stromerzeuger und Stromhandel an den Transportkosten beteiligen', '{301}', 1, 1, null, 'Würde Haushalte bei den Netzentgelten entlasten; Entgelte für Erzeuger begrenzt das EU-Recht eng, und die Kosten würden zum Teil über höhere Strompreise wieder bei den Verbrauchern landen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'offen', '2026-09-30', false, true),
  (6736, 3, 16, null, 'Stromsteuer auf den europäischen Mindeststeuersatz senken', '{302}', 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'belegt', '2026-09-30', false, true),
  (6737, 3, 16, null, 'Schnellstmöglich auf erneuerbare Energien umsteigen', '{304}', 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-09-30', false, true),
  (6738, 3, 16, null, 'Keine CO₂-Preise im Wärmebereich', '{302,305}', 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'belegt', '2026-09-30', false, true),
  (6739, 3, 16, null, 'Heizungstausch nach Einkommen gestaffelt fördern, bis zu 100 Prozent', '{305}', 2, 2, null, 'Ermöglicht auch Eigentümern mit wenig Geld den Umstieg von Gas und Öl und koppelt die Heizkosten von fossilen Preisen ab; das Programm soll 25 Milliarden Euro im Jahr kosten, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true),
  (6755, 8, 11, null, 'Auskömmliche Finanzierung des Nahverkehrs sichern', '{801}', 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true),
  (6756, 8, 11, null, 'Infrastruktur und Transport der Deutschen Bahn stärker trennen', '{802}', 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true),
  (6757, 8, 11, null, 'Dauerhafte, vom Haushalt unabhängige Finanzierung der Infrastruktur', '{802}', 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true),
  (6758, 8, 11, null, 'Berufskraftfahrerqualifikation reformieren gegen den Fahrermangel bei Bus und Lkw', '{803}', 1, 2, null, 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', null, 'gemischt', '2026-09-30', false, true),
  (6759, 8, 12, null, 'Rekordinvestitionen in die Schiene fortsetzen, Generalsanierung wichtiger Strecken', '{802}', 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true),
  (6760, 8, 12, null, 'DB InfraGO und Gesamtkonzern mit mehr Kontrolle und Steuerung des Bundes', '{802}', 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'offen', '2026-09-30', false, true),
  (6761, 8, 12, null, 'Finanzierung des Nahverkehrs mit Ländern und Kommunen dauerhaft stärken', '{801}', 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true),
  (6762, 8, 12, null, 'Personalübernahme beim Betreiberwechsel und Tariftreue in Vergabeverfahren', '{803}', 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true),
  (6763, 8, 13, null, 'Überjährige Finanzierung für Schiene und Nahverkehr über den Deutschlandfonds', '{802}', 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true),
  (6764, 8, 13, null, 'Stillgelegte Bahntrassen auf dem Land reaktivieren', '{801}', 1, 2, null, 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true),
  (6765, 8, 13, null, 'Bundesmittel für den Nahverkehr gemeinsam mit den Ländern steigern', '{801}', 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'gemischt', '2026-09-30', false, true),
  (6766, 8, 13, null, 'Im ganzen Land ein alltagstaugliches Angebot mit verlässlichen Takten garantieren', '{801}', 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'offen', '2026-09-30', false, true),
  (6767, 8, 13, null, 'Marodes Schienennetz mit Hochdruck sanieren', '{802}', 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true),
  (6768, 8, 13, null, 'Bessere Arbeitsbedingungen und gute Bezahlung im Nah- und Fernverkehr', '{803}', 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true),
  (6769, 8, 14, null, 'Netz und Betrieb bei der Deutschen Bahn trennen', '{802}', 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true),
  (6770, 8, 14, null, 'Bus-Führerschein und Berufskraftfahrerqualifikation günstiger machen', '{803}', 1, 2, null, 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true),
  (6771, 8, 14, null, 'Starre Linienverkehre durch flexible, bedarfsgerechte Angebote ergänzen', '{801}', 1, 2, null, 'On-Demand-Angebote können Lücken im ländlichen Raum schließen, befördern aber wenige Menschen je Fahrt und sind teuer; Angebot und Finanzierung liegen bei Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true),
  (6772, 8, 15, null, 'Bahnkonzern in eine GmbH umwandeln, damit der Bund die Infrastruktur wirksam steuern kann', '{802}', 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'offen', '2026-09-30', false, true),
  (6773, 8, 15, null, 'Vernachlässigtes Schienennetz ausbauen, Engpässe beseitigen', '{802}', 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'gemischt', '2026-09-30', false, true),
  (6774, 8, 15, null, 'ÖPNV im ländlichen Raum bedarfsgerecht ausbauen', '{801}', 1, 2, null, 'Benennt das Ziel eines besseren Angebots auf dem Land, aber keinen Weg und keine Finanzierung; Angebot und Bestellung liegen bei Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=40', null, 'offen', '2026-09-30', false, true),
  (6775, 8, 16, null, 'Verkehrsträgerübergreifender Infrastrukturfonds nach Schweizer Vorbild', '{802}', 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'gemischt', '2026-09-30', false, true),
  (6776, 8, 16, null, 'Jede Ortschaft tagsüber mindestens stündlich an Bus und Bahn anbinden', '{801}', 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'offen', '2026-09-30', false, true),
  (6777, 8, 16, null, 'Mehr Personal durch bessere Bezahlung und Arbeitsbedingungen', '{803}', 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'gemischt', '2026-09-30', false, true),
  (6778, 8, 16, null, 'Netz sanieren, elektrifizieren und ausbauen', '{802}', 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true),
  (6779, 8, 16, null, 'Stillgelegte Strecken reaktivieren', '{801}', 1, 2, null, 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true),
  (6780, 8, 11, 'ST', 'Sachsen-Anhalt-Takt erweitern, alle Ober- und Mittelzentren verbinden', '{801}', 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'belegt', '2026-09-30', false, true),
  (6781, 8, 11, 'ST', 'Rufverkehre, Bürgerbusse und autonome Angebote im ländlichen Raum', '{801}', 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'gemischt', '2026-09-30', false, true),
  (6782, 8, 12, 'ST', 'Mobilitätsgarantie für alle Regionen', '{801}', 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=41', null, 'offen', '2026-09-30', false, true),
  (6783, 8, 12, 'ST', 'Stillgelegte Strecken reaktivieren, zusätzliche Haltepunkte', '{801}', 1, 2, null, 'Verbessert die Anbindung einzelner Orte deutlich, erreicht insgesamt aber wenige Menschen; Planung und Bau dauern Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'gemischt', '2026-09-30', false, true),
  (6784, 8, 12, 'ST', 'ÖPNV-Leistungen nur bei Anwendung der Tarifverträge vergeben', '{803}', 2, 3, null, 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=41', null, 'gemischt', '2026-09-30', false, true),
  (6785, 8, 13, 'ST', 'Busverkehr so ausbauen, dass jedes Dorf mindestens stündlich erreicht wird', '{801}', 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=29', null, 'offen', '2026-09-30', false, true),
  (6786, 8, 14, 'ST', 'Landes-Bus-Netz ausbauen, On-Demand-Shuttles und Rufbusse in Taktverkehre einbinden', '{801}', 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=67', null, 'belegt', '2026-09-30', false, true),
  (6787, 8, 14, 'ST', 'Schülerbeförderung aus dem Landeshaushalt bezahlen, damit mehr Regionalisierungsmittel für das Angebot bleiben', '{801}', 2, 2, null, 'Macht Geld für zusätzliche Fahrten frei, ohne neue Bundesmittel; das Land muss die Schülerbeförderung dafür dauerhaft aus dem eigenen Haushalt bezahlen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=69', null, 'offen', '2026-09-30', false, true),
  (6788, 8, 14, 'ST', 'Offensive für Fahrpersonal: schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse', '{803}', 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=68', null, 'gemischt', '2026-09-30', false, true),
  (6789, 8, 15, 'ST', 'Flächendeckendes Nahverkehrsangebot sichern statt Buslinien kürzen', '{801}', 1, 2, null, 'Sichert das bestehende Angebot gegen Kürzungen, nennt aber weder Umfang noch Finanzierung eines Ausbaus.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=191', null, 'offen', '2026-09-30', false, true),
