  (7121, 12, 16, 'BE', 'Ausbau sicherer Radwege fortführen, lückenloses Netz nach Radnetzplan', '{1204}', 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=65', null, 'gemischt', '2026-09-30', false, true),
  (7122, 12, 16, 'BE', 'Alle Möglichkeiten für Tempo 30 auf Berliner Straßen nutzen', '{1204}', 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=63', null, 'belegt', '2026-09-30', false, true),
  (7123, 12, 17, 'BE', 'Investitionsmittel für die Instandsetzung von Straßen und Brücken, Sondervermögen nutzen', '{1202}', 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=43', null, 'gemischt', '2026-09-30', false, true),
  (7124, 12, 17, 'BE', 'Sicheres, zusammenhängendes Radwegenetz, sichere Kreuzungen mit getrennten Ampelphasen', '{1204}', 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=49', null, 'gemischt', '2026-09-30', false, true),
  (7130, 14, 11, 'ST', 'Verwaltungsmodernisierung an einer zentralen Stelle der Landesverwaltung bündeln', '{1401}', 1, 3, null, 'Klare Zuständigkeit kann Digitalisierungsprojekte beschleunigen; für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich einfacher werden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'offen', '2026-09-30', false, true),
