  (7172, 16, 15, 'MV', 'Tiefengeothermie als kommunale Wärmequelle fördern, Genehmigungen entbürokratisieren', '{1603}', 1, 2, null, 'Kann dort, wo die Geologie passt, Wärmenetze möglich machen und so Klarheit über die künftige Versorgung schaffen; Tiefengeothermie ist teuer, braucht Jahre und kommt nur für einen Teil der Gemeinden in Frage.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=86', null, 'offen', '2026-09-30', false, true),
  (7173, 16, 11, 'BE', 'Kommunale Wärmeplanung als Orientierung fortführen, Fernwärme dekarbonisieren', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=32', null, 'gemischt', '2026-09-30', false, true),
  (7174, 16, 12, 'BE', 'Fernwärme über die Wärmeplanung ausbauen, Förderdarlehen für neue Wärmenetze', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=59', null, 'gemischt', '2026-09-30', false, true),
  (7175, 16, 13, 'BE', 'Wärmewende-Manager in den Bezirken, Förderinstrumente für die Umsetzung der Wärmeplanung', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=13', null, 'gemischt', '2026-09-30', false, true),
  (7176, 16, 14, 'BE', 'Fern- und Nahwärmenetze im Stadtgebiet ausweiten', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=87', null, 'gemischt', '2026-09-30', false, true),
  (7177, 16, 16, 'BE', 'Wärmeagentur, Beratung und Förderung, mehr Personal für die Bezirke', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=195', null, 'gemischt', '2026-09-30', false, true),
  (7178, 16, 17, 'BE', 'Konsequenter Ausbau der Fernwärme, gesteuert über die kommunale Wärmeplanung', '{1603}', 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=46', null, 'gemischt', '2026-09-30', false, true),
  (7188, 9, 13, null, 'Arbeitsverbote abschaffen; arbeitsbezogene Genehmigungen gelten nach kurzer Frist als erteilt', '{905}', 2, 3, null, 'Arbeitsmarktzugang beseitigte in der Schweiz zwei Drittel des erhöhten Gewaltrisikos von Asylsuchenden mit Kriegserfahrung (Couttenier u. a. 2019); Arbeitsverbote wirken bis zu zehn Jahre nach. Für Deutschland fehlen Studien mit verknüpften Daten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'gemischt', '2026-09-30', false, true),
  (7189, 9, 16, null, 'Uneingeschränkte Arbeitserlaubnis für alle Geflüchteten ab dem Tag der Ankunft', '{905}', 2, 3, null, 'Arbeitsmarktzugang beseitigte in der Schweiz zwei Drittel des erhöhten Gewaltrisikos von Asylsuchenden mit Kriegserfahrung (Couttenier u. a. 2019); Arbeitsverbote wirken bis zu zehn Jahre nach. Für Deutschland fehlen Studien mit verknüpften Daten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'gemischt', '2026-09-30', false, true),
  (7190, 9, 11, null, 'Arbeitsvermittlung nicht wegen laufender Sprach- oder Integrationskurse aufschieben; Spracherwerb berufsbegleitend', '{905}', 2, 3, null, 'Arbeitsmarktzugang beseitigte in der Schweiz zwei Drittel des erhöhten Gewaltrisikos von Asylsuchenden mit Kriegserfahrung (Couttenier u. a. 2019); Arbeitsverbote wirken bis zu zehn Jahre nach. Für Deutschland fehlen Studien mit verknüpften Daten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'gemischt', '2026-09-30', false, true),
  (7191, 9, 17, null, 'Job-Turbo für Ukrainer und andere Geflüchtete mit Schutzstatus umsetzen', '{905}', 2, 3, null, 'Arbeitsmarktzugang beseitigte in der Schweiz zwei Drittel des erhöhten Gewaltrisikos von Asylsuchenden mit Kriegserfahrung (Couttenier u. a. 2019); Arbeitsverbote wirken bis zu zehn Jahre nach. Für Deutschland fehlen Studien mit verknüpften Daten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-30', false, true),
  (7192, 9, 12, null, 'Integrationskurse ausbauen und ausreichend finanzieren', '{905}', 1, 3, null, 'Bessere Sprachkurse erhöhten in Dänemark Einkommen und Beschäftigung von Geflüchteten dauerhaft, senkten ihre eigene Kriminalität aber nicht; bei ihren Söhnen sank sie (Foged u. a. 2024). Für Deutschland nicht eigens untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'gemischt', '2026-09-30', false, true),
  (7193, 9, 13, null, 'Ausfinanzierte Integrations- und Sprachkurse direkt nach der Ankunft', '{905}', 1, 3, null, 'Bessere Sprachkurse erhöhten in Dänemark Einkommen und Beschäftigung von Geflüchteten dauerhaft, senkten ihre eigene Kriminalität aber nicht; bei ihren Söhnen sank sie (Foged u. a. 2024). Für Deutschland nicht eigens untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'gemischt', '2026-09-30', false, true),
  (7194, 9, 16, null, 'Geflüchtete dezentral in Wohnungen unterbringen, flächendeckend kostenlose Sprachkurse', '{905}', 1, 3, null, 'Bessere Sprachkurse erhöhten in Dänemark Einkommen und Beschäftigung von Geflüchteten dauerhaft, senkten ihre eigene Kriminalität aber nicht; bei ihren Söhnen sank sie (Foged u. a. 2024). Für Deutschland nicht eigens untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'gemischt', '2026-09-30', false, true),
  (7195, 9, 14, null, 'Sprach- und Integrationskurse trennen; Sprachkurse modular und leistungsdifferenziert', '{905}', 1, 3, null, 'Bessere Sprachkurse erhöhten in Dänemark Einkommen und Beschäftigung von Geflüchteten dauerhaft, senkten ihre eigene Kriminalität aber nicht, wohl die ihrer Söhne (Foged u. a. 2024); die Neuordnung soll die Kurse wirksamer machen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, 'gemischt', '2026-09-30', false, true),
  (7196, 9, 15, null, 'Pflicht zum Spracherwerb auf B2-Niveau in der Regel binnen zwei Jahren; Kosten abgebrochener Kurse erstatten', '{905}', 1, 2, null, 'Sprache öffnet den Weg in Arbeit; eine Pflicht mit Kostenerstattung setzt auf Druck statt auf ein Angebot. Wie sich das auf Straftaten auswirkt, ist nicht untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=110', null, 'offen', '2026-09-30', false, true),
  (7197, 9, 11, null, 'Berufsanerkennung vereinfachen, Deutschlernen „on the job“ stärken', '{905}', 1, 2, null, 'Schnellere Anerkennung verbessert Verdienstmöglichkeiten und damit die Perspektive; auf Kriminalität wirkt das nur mittelbar und ist kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-30', false, true),
  (7198, 9, 14, null, 'Anerkennung ausländischer Abschlüsse beschleunigen und durchgehend digitalisieren', '{905}', 1, 2, null, 'Schnellere Anerkennung verbessert Verdienstmöglichkeiten und damit die Perspektive; auf Kriminalität wirkt das nur mittelbar und ist kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-09-30', false, true),
  (7199, 9, 17, null, 'Erwachsenenbildung zum Nachholen von Schulabschlüssen und Nachqualifikation bei abweichenden Berufsausbildungen', '{905}', 1, 2, null, 'Nachqualifikation verbessert Verdienstmöglichkeiten und damit die Perspektive; auf Kriminalität wirkt das nur mittelbar und ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'offen', '2026-09-30', false, true),
  (7200, 9, 12, null, 'Spurwechsel in die Fachkräfteeinwanderung für integrierte, straffreie Menschen ohne Schutzstatus', '{905}', 2, 3, null, 'Ein legaler Aufenthalt halbierte in Italien etwa die Kriminalität der Betroffenen (Pinotti 2017). Ein Spurwechsel erreicht aber vor allem Menschen, die schon integriert und straffrei sind; der Effekt dürfte kleiner sein.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'gemischt', '2026-09-30', false, true),
  (7201, 9, 13, null, 'Spurwechsel ausgestalten; auf das Chancen-Aufenthaltsrecht weitere Reformen folgen lassen', '{905}', 2, 3, null, 'Ein legaler Aufenthalt halbierte in Italien etwa die Kriminalität der Betroffenen (Pinotti 2017). Ein Spurwechsel erreicht aber vor allem Menschen, die schon integriert und straffrei sind; der Effekt dürfte kleiner sein.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=127', null, 'gemischt', '2026-09-30', false, true),
  (7202, 9, 14, null, 'Spurwechsel für gut integrierte Schutzsuchende, die ohne Transferleistungen leben können', '{905}', 2, 3, null, 'Ein legaler Aufenthalt halbierte in Italien etwa die Kriminalität der Betroffenen (Pinotti 2017). Ein Spurwechsel erreicht aber vor allem Menschen, die schon integriert und straffrei sind; der Effekt dürfte kleiner sein.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-30', false, true),
  (7203, 9, 16, null, 'Legalisierung für Menschen ohne Aufenthaltsstatus; wirksame Bleiberechtsregelungen bei Kettenduldungen', '{905}', 2, 3, null, 'Ein legaler Aufenthalt halbierte in Italien etwa die Kriminalität der Betroffenen (Pinotti 2017), ähnliche Befunde gibt es für die USA. Der Effekt betrifft nur einen Teil der Tatverdächtigen und ist für Deutschland nicht untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'gemischt', '2026-09-30', false, true),
  (7204, 9, 11, null, 'Weitere Länder als sichere Herkunftsstaaten einstufen', '{905}', 1, 2, null, 'Schnellere Entscheidungen schaffen früher Klarheit, gerade für Gruppen mit geringer Bleibeperspektive, unter denen das BKA besonders viele Mehrfachtatverdächtige zählt. Ob das Straftaten verhindert, ist nicht untersucht, und die Einstufung setzt eine belegte Lage im Herkunftsstaat voraus.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-30', false, true),
  (7205, 9, 14, null, 'Geordnetes Verfahren, um mehr sichere Herkunftsstaaten festzustellen', '{905}', 1, 2, null, 'Schnellere Entscheidungen schaffen früher Klarheit, gerade für Gruppen mit geringer Bleibeperspektive, unter denen das BKA besonders viele Mehrfachtatverdächtige zählt. Ob das Straftaten verhindert, ist nicht untersucht, und die Einstufung setzt eine belegte Lage im Herkunftsstaat voraus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-30', false, true),
  (7206, 9, 15, null, 'Zahl der sicheren Herkunftsstaaten deutlich ausweiten', '{905}', 1, 2, null, 'Schnellere Entscheidungen schaffen früher Klarheit, gerade für Gruppen mit geringer Bleibeperspektive, unter denen das BKA besonders viele Mehrfachtatverdächtige zählt. Ob das Straftaten verhindert, ist nicht untersucht, und die Einstufung setzt eine belegte Lage im Herkunftsstaat voraus.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'offen', '2026-09-30', false, true),
  (7207, 9, 12, null, 'Asylverfahren beim Bundesamt und an den Verwaltungsgerichten durch Digitalisierung beschleunigen, Entscheidung in sechs Monaten', '{905}', 1, 2, null, 'Kurze Verfahren verkürzen die Zeit ohne sichere Perspektive, die Kriminologen mit Frust und Gewalt in Verbindung bringen. Ob das Straftaten verhindert, ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-09-30', false, true),
  (7208, 9, 15, null, 'Asylverfahren vor den Verwaltungsgerichten straffen, mehr Personal zum Abbau von Altfällen', '{905}', 1, 2, null, 'Kurze Verfahren verkürzen die Zeit ohne sichere Perspektive, die Kriminologen mit Frust und Gewalt in Verbindung bringen. Ob das Straftaten verhindert, ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'offen', '2026-09-30', false, true),
  (7209, 9, 17, null, 'Behörden und Gerichte vorrangig mit Personal ausstatten, Asylverfahren in drei Monaten', '{905}', 1, 2, null, 'Kurze Verfahren verkürzen die Zeit ohne sichere Perspektive, die Kriminologen mit Frust und Gewalt in Verbindung bringen. Ob das Straftaten verhindert, ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'offen', '2026-09-30', false, true),
  (7210, 9, 11, null, 'Zentrale Asylverfahren für beschleunigte Verfahren und Bundesausreisezentren', '{905}', 1, 2, null, 'Zentrale Verfahren können Entscheidungen beschleunigen; das Leben in großen Sammelunterkünften gilt in der kriminologischen Forschung dagegen eher als Risiko für Konflikte. Die Wirkung auf Straftaten ist nicht untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-30', false, true),
  (7211, 9, 15, null, 'Bundesprogramme zur Förderung der freiwilligen Rückkehr ausweiten', '{905}', 1, 3, null, 'Rückkehrprogramme geben Menschen ohne Bleibeperspektive eine Perspektive im Herkunftsland, was Kriminologen gegen Frust und Straftaten empfehlen; ob sie Straftaten verhindern, ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=109', null, 'offen', '2026-09-30', false, true),
  (7212, 9, 14, null, 'Wohnsitzauflage stärker nutzen', '{905}', 1, 3, null, 'Der Wohnort erklärt laut ifo einen großen Teil der Überrepräsentation, und eine Wohnsitzauflage steuert ihn; sie kann aber Arbeitssuche und Anschluss an Familie erschweren. Die Wirkung auf Straftaten ist nicht untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-30', false, true),
  (7213, 9, 13, null, 'Periodischen Sicherheitsbericht gesetzlich verankern', '{909}', 1, 3, null, 'Ein regelmäßiger Bericht ordnet die Kriminalstatistik mit Forschung und Dunkelfeldstudien ein und kann Fehlwahrnehmungen entgegenwirken; ob er das Sicherheitsgefühl verändert, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-09-30', false, true),
  (7214, 9, 13, 'ST', 'Kriminalstatistik durch Studien ergänzen und einordnen, um das subjektive Sicherheitsempfinden einzuordnen', '{909}', 1, 3, null, 'Ein regelmäßiger Bericht ordnet die Kriminalstatistik mit Forschung und Dunkelfeldstudien ein und kann Fehlwahrnehmungen entgegenwirken; ob er das Sicherheitsgefühl verändert, ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=42', null, 'offen', '2026-09-30', false, true),
  (7215, 9, 13, 'MV', 'Periodischer Sicherheitsbericht, der die Kriminalstatistik allgemeinverständlich ergänzt', '{909}', 1, 3, null, 'Ein regelmäßiger Bericht ordnet die Kriminalstatistik mit Forschung und Dunkelfeldstudien ein und kann Fehlwahrnehmungen entgegenwirken; ob er das Sicherheitsgefühl verändert, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-09-30', false, true),
  (7216, 9, 13, 'BE', 'Berliner Periodischen Sicherheitsbericht einführen, der auch die Ursachen der Taten analysiert', '{909}', 1, 3, null, 'Ein regelmäßiger Bericht ordnet die Kriminalstatistik mit Forschung und Dunkelfeldstudien ein und kann Fehlwahrnehmungen entgegenwirken; ob er das Sicherheitsgefühl verändert, ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'offen', '2026-09-30', false, true),
  (7217, 9, 15, 'MV', 'Mehr Angaben zur Ausländerkriminalität auch für Landkreise und kreisfreie Städte veröffentlichen', '{909}', 1, 3, null, 'Mehr veröffentlichte Angaben machen die Lage nachprüfbar. Laut einer Studie baut die Nennung der Herkunft aller Tatverdächtigen, auch der deutschen, Fehlwahrnehmungen ab; zusätzliche Angaben nur zu Ausländern können die ungleiche Aufmerksamkeit dagegen verstärken.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'gemischt', '2026-09-30', false, true),
  (7218, 9, 15, 'MV', 'Regelmäßige landesweite Dunkelfeldbefragungen, auch zur Furcht vor Kriminalität', '{909}', 1, 3, null, 'Befragungen zeigen, wie viel Kriminalität Menschen tatsächlich erleben und wie sehr sie sich fürchten, und machen den Abstand zwischen Gefühl und Risiko sichtbar. Allein ändern sie das Sicherheitsgefühl nicht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-09-30', false, true),
  (7219, 9, 12, 'BE', 'Regelmäßige Dunkelfeldforschung zu den wichtigsten Kriminalitätsphänomenen fördern', '{909}', 1, 3, null, 'Befragungen zeigen, wie viel Kriminalität Menschen tatsächlich erleben und wie sehr sie sich fürchten, und machen den Abstand zwischen Gefühl und Risiko sichtbar. Allein ändern sie das Sicherheitsgefühl nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-09-30', false, true),
  (7220, 9, 13, null, 'Anerkennung ausländischer Abschlüsse und Qualifikationen vereinfachen', '{905}', 1, 2, null, 'Schnellere Anerkennung verbessert Verdienstmöglichkeiten und damit die Perspektive; auf Kriminalität wirkt das nur mittelbar und ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=129', null, 'offen', '2026-09-30', false, true),
  (7221, 2, 12, null, 'Kurzzeitvermietung in Ballungsgebieten auf ein Mindestmaß reduzieren', '{201,205}', 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-30', false, true),
  (7222, 2, 11, null, 'Ballungsräume entlasten: Verkehrswege und Nahverkehr ins Umland bedarfsgerecht ausbauen', '{205}', 1, 2, null, 'Bessere Verbindungen machen das Umland als Wohnort attraktiver und können die Nachfrage in den Großstädten dämpfen; wie stark, ist kaum untersucht, und der Ausbau dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, 'offen', '2026-09-30', false, true),
  (7223, 2, 16, null, 'Wohngeld-Antrag stark vereinfachen, Anträge binnen drei Monaten bescheiden', '{202}', 1, 3, null, 'Entlastet Haushalte mit geringem Einkommen direkt, wenn mehr Berechtigte das Wohngeld tatsächlich erhalten; zusätzliche Wohnungen entstehen dadurch nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-30', false, true),
  (7224, 9, 15, null, 'Polizei bundeseinheitlich besser besolden, Zulagen erhöhen, Bewaffnung und Ausrüstung verbessern', '{901}', 1, 1, null, 'Bessere Bezahlung und Ausrüstung können helfen, Personal zu gewinnen und zu halten, und so mehr Präsenz ermöglichen; mehr Stellen sieht die Maßnahme nicht vor. Die Besoldung der Landespolizeien regeln seit 2006 die Länder, eine bundeseinheitliche Regel bräuchte eine Grundgesetzänderung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', null, 'offen', '2026-09-30', false, true),
  (7225, 14, 14, null, 'Vorausgefüllte Steuererklärung bis zur vollautomatisierten Einkommensteuerveranlagung („Easy Tax“)', '{1401,1402}', 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'gemischt', '2026-09-30', false, true),
  (7226, 14, 14, null, 'Elterngeld und Familienleistungen digitalisieren und automatisieren, KI-basierte Beantragung', '{1401,1402}', 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', null, 'gemischt', '2026-09-30', false, true),
  (7227, 16, 11, null, 'Investitionen in Klimatechnologien und Energieeffizienz steuerlich schneller absetzbar, auch für Vermieter', '{1604}', 1, 2, null, 'Macht den Heizungstausch auch für Vermieter steuerlich attraktiver, sodass mehr Mietwohnungen umgestellt werden können; ob Mieterinnen und Mieter dabei sparen, hängt von der Umlage ab, und die Maßnahme ist nicht auf Mietwohnungen zugeschnitten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'offen', '2026-09-30', false, true),
  (7229, 11, 11, null, 'Menschen in Helfertätigkeiten auf dem Weg zur Fachkraft fördern', '{1105}', 1, 2, null, 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', null, 'gemischt', '2026-09-30', false, true),
  (7230, 11, 16, null, 'Anspruch auf verlängerte Umschulung und erleichterte Externenprüfung für Menschen ohne Ausbildung', '{1105}', 1, 2, null, 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', null, 'gemischt', '2026-09-30', false, true),
  (7231, 10, 12, null, 'Digitale Produkte und Beratung in der Pflege nutzen, um Prävention zu fördern und Pflegebedürftigkeit vorzubeugen', '{1003}', 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-30', false, true),
  (7233, 2, 17, null, 'Umwandlung von Wohnungen in Ferienwohnungen und Leerstand strenger regulieren', '{201}', 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-30', false, true),
  (7234, 9, 17, null, 'Nach schweren Straftaten Anspruch auf Asylverfahren entziehen, Abschiebungsschutz nur bei drohender Todesstrafe', '{905}', 1, 0, null, 'Wer keinen Schutz mehr hat, kann eher abgeschoben werden; Abschiebungen scheitern aber oft an Papieren und Herkunftsstaaten. Das Verbot, in Folter oder unmenschliche Behandlung abzuschieben (Art. 3 EMRK, Art. 19 EU-Grundrechtecharta), gilt absolut und lässt sich nicht auf die Todesstrafe begrenzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-30', false, true),
  (7240, 9, 11, null, 'Asylsuchende an den deutschen Grenzen zurückweisen, wenn sie aus einem EU- oder Schengen-Staat einreisen', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Zurückweisungen von Asylsuchenden an Binnengrenzen sind nach EU-Recht nur in engen Ausnahmen zulässig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=42', null, 'gemischt', '2026-10-01', false, true),
  (7241, 9, 14, null, 'Zurückweisungen an den deutschen Grenzen modellhaft erproben', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Zurückweisungen von Asylsuchenden an Binnengrenzen sind nach EU-Recht nur in engen Ausnahmen zulässig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-10-01', false, true),
  (7242, 9, 15, null, 'Grenzen selbst kontrollieren, illegal Einreisende an der Grenze zurückweisen', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Zurückweisungen von Asylsuchenden an Binnengrenzen sind nach EU-Recht nur in engen Ausnahmen zulässig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'gemischt', '2026-10-01', false, true),
  (7243, 9, 11, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, freiwillige Aufnahmeprogramme beenden', '{910}', 1, 3, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Kriminologen sehen im Familiennachzug zugleich einen Schutz vor Straffälligkeit junger Männer (Baier/Pfeiffer/Kliem 2018).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-10-01', false, true),
  (7244, 9, 14, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, Aufnahmeprogramme pausieren', '{910}', 1, 3, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Kriminologen sehen im Familiennachzug zugleich einen Schutz vor Straffälligkeit junger Männer (Baier/Pfeiffer/Kliem 2018).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-10-01', false, true),
  (7245, 9, 15, null, 'Grundsätzlichen Anspruch auf Familiennachzug zu subsidiär Schutzberechtigten streichen', '{910}', 1, 3, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Kriminologen sehen im Familiennachzug zugleich einen Schutz vor Straffälligkeit junger Männer (Baier/Pfeiffer/Kliem 2018).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-10-01', false, true),
  (7246, 9, 11, null, 'Asylverfahren in sicheren Drittstaaten außerhalb Europas', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Solche Verfahren hängen von Abkommen mit Drittstaaten ab und sind rechtlich umstritten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=44', null, 'gemischt', '2026-10-01', false, true),
  (7247, 9, 14, null, 'Asylverfahren auch in Drittstaaten', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Solche Verfahren hängen von Abkommen mit Drittstaaten ab und sind rechtlich umstritten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-10-01', false, true),
  (7248, 9, 15, null, 'Asylanträge künftig außerhalb Deutschlands stellen und bearbeiten', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Solche Verfahren hängen von Abkommen mit Drittstaaten ab und sind rechtlich umstritten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'gemischt', '2026-10-01', false, true),
  (7249, 9, 17, null, 'Asylverfahren möglichst außerhalb der EU in sicheren Drittstaaten', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Solche Verfahren hängen von Abkommen mit Drittstaaten ab und sind rechtlich umstritten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=38', null, 'gemischt', '2026-10-01', false, true),
  (7250, 9, 12, null, 'Solidarische Verteilung von Schutzsuchenden unter allen EU-Staaten', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Eine verbindliche Verteilung braucht die Zustimmung der übrigen EU-Staaten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-10-01', false, true),
  (7251, 9, 13, null, 'Faire, verbindliche und solidarische Verteilung von Schutzsuchenden in Europa', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Eine verbindliche Verteilung braucht die Zustimmung der übrigen EU-Staaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'gemischt', '2026-10-01', false, true),
  (7252, 9, 16, null, 'Europäische Fluchtumlage: EU-Geld für aufnahmebereite Länder, Regionen und Städte', '{910}', 1, 1, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Eine verbindliche Verteilung braucht die Zustimmung der übrigen EU-Staaten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'gemischt', '2026-10-01', false, true),
  (7253, 9, 17, null, 'Wer aus einem sicheren Drittstaat einreist, bekommt kein Asylverfahren und keinen Aufenthalt', '{910}', 1, 0, null, 'Weniger Zuzug bedeutet nach den Studien zu Deutschland 2014–2016 etwas weniger Taten in den aufnehmenden Kreisen; internationale Studien finden keinen solchen Zusammenhang. Ein pauschaler Ausschluss vom Asylverfahren bei Einreise über sichere Drittstaaten ist mit EU-Recht nicht vereinbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-10-01', false, true),
  (7254, 9, 12, null, 'Ausländerbehörden stärken, Datenaustausch verbessern, Verfahren aus einer Hand', '{910}', 1, 2, null, 'Bessere Aufnahmebedingungen können die Belastungen verringern, die Kriminologen für den Anstieg 2015/16 mitverantwortlich machen; ob sie Straftaten verhindern, ist nicht untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-10-01', false, true),
  (7255, 9, 13, null, 'Kommunen mit einer Integrationsoffensive stärker und verlässlicher finanziell unterstützen', '{910}', 1, 2, null, 'Bessere Aufnahmebedingungen können die Belastungen verringern, die Kriminologen für den Anstieg 2015/16 mitverantwortlich machen; ob sie Straftaten verhindern, ist nicht untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'offen', '2026-10-01', false, true),
  (7256, 9, 16, null, 'Fonds für Willkommenskommunen; der Bund erstattet die Unterbringungskosten vollständig pro Person', '{910}', 1, 2, null, 'Bessere Aufnahmebedingungen können die Belastungen verringern, die Kriminologen für den Anstieg 2015/16 mitverantwortlich machen; ob sie Straftaten verhindern, ist nicht untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'offen', '2026-10-01', false, true),
  (7257, 9, 15, null, 'Asylsuchende für die Dauer des Verfahrens in zentralen Aufnahmeeinrichtungen unterbringen', '{910}', 1, 2, null, 'Zentrale Unterbringung kann Verfahren und Rückführungen erleichtern; große Sammelunterkünfte gelten in der kriminologischen Forschung aber eher als Risiko für Konflikte. Die Wirkung auf Straftaten ist nicht untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'offen', '2026-10-01', false, true),
  (7261, 15, 12, null, 'Befristeter Steuerabzugsbetrag für in Deutschland produzierte E-Autos, auch Gebrauchte und Leasing', '{1501}', 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true),
  (7262, 15, 13, null, 'Staatliche Unterstützung beim Kauf verbrauchsarmer E-Autos, Social Leasing, Ladekarte', '{1501}', 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true),
  (7263, 15, 16, null, 'Sozial gestaffelte Förderung kleiner E-Fahrzeuge für Pendelnde auf dem Land', '{1501}', 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true),
  (7264, 15, 17, null, 'Volksleasing für umweltfreundliche Fahrzeuge aus europäischer Produktion, Kaufprämien im niedrigen Preissegment', '{1501}', 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true),
  (7265, 15, 11, null, 'Technologieoffenheit: E-Fuels, Wasserstoff und nachhaltige Biokraftstoffe neben der Elektromobilität nutzen', '{1501}', 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true),
  (7266, 15, 14, null, 'Statt eines Verbrennerverbots alternative Kraftstoffe wie E-Fuels ermöglichen', '{1501}', 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true),
  (7267, 15, 15, null, 'Synthetische Kraftstoffe berücksichtigen und bei den Abgaben wie Elektrofahrzeuge behandeln', '{1501}', 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=44', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true),
  (7268, 15, 17, null, 'Verbrauchsarme Verbrenner und alternative Kraftstoffe fördern', '{1501}', 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true),
  (7269, 15, 11, null, 'In angespannter Lage Energie- und Umsatzsteuer für Güter des täglichen Bedarfs schnell senken dürfen', '{1501}', 1, 1, null, 'Senkt den Preis sofort, aber nur befristet; der Tankrabatt 2026 kam laut Monopolkommission zu einem großen Teil, aber nicht vollständig an. Die schnelle Senkung der Umsatzsteuer braucht EU-Zustimmung. Das Programm nennt Güter des täglichen Bedarfs, nicht nur Kraftstoff.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'gemischt', '2026-10-01', false, true),
  (7270, 15, 11, null, 'Europäischen Energiebinnenmarkt stärken, internationale Energiepartnerschaften ausbauen', '{1501}', 1, 3, null, 'Mehr Lieferländer machen Deutschland weniger anfällig für Preissprünge bei einzelnen Lieferanten; die Maßnahme nennt weder Öl noch konkrete Schritte.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-10-01', false, true),
  (7271, 15, 17, null, 'Langfristige Lieferverträge für Energieimporte nach dem niedrigsten Preis', '{1501}', 1, 2, null, 'Langfristige Verträge können Preisschwankungen dämpfen, binden aber auch an Preise, wenn der Markt fällt; die Maßnahme nennt kein Öl, sondern Energieimporte allgemein.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-01', false, true),
  (7325, 17, 11, null, 'Länder und Kommunen mit einem Investitionsprogramm beim Ausbau von Betreuungsplätzen unterstützen.', '{1701}', 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true),
  (7326, 17, 11, null, 'Die steuerliche Absetzbarkeit von Kinderbetreuungskosten verbessern.', '{1705}', 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true),
  (7327, 17, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit mehr Ausbildungskapazitäten und entlohnter Erzieherausbildung vereinbaren; mehr Fachkräfte sollen mehr Plätze und weniger Schließzeiten ermöglichen.', '{1701,1702,1704}', 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7328, 17, 12, null, 'Kostenfreie Bildung ab der Kita.', '{1705}', 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7329, 17, 13, null, 'Steuerliche Anreize für Unternehmen, die selbst oder gemeinsam mit anderen Betreuungsplätze schaffen.', '{1701}', 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', null, 'offen', '2026-10-01', false, true),
  (7330, 17, 13, null, 'Fachkräfte für Kitas und Kindertagespflege gewinnen und sichern: vergütete, schulgeldfreie Ausbildung, attraktivere Arbeitsplätze, erleichterte Anerkennung und Weiterbildung.', '{1702,1704}', 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=75', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7331, 17, 13, null, 'Einkommensabhängige Kita-Gebühren als Standard einführen.', '{1705}', 2, 2, null, 'Einkommensabhängige Beiträge können die Belastung gezielter bei Familien mit geringem Einkommen senken. Der Bund kann Vorgaben zur Staffelung machen, Höhe und Erhebung der Beiträge liegen aber bei Ländern und Kommunen; die Angebotsknappheit bleibt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7332, 17, 14, null, 'Kindertagespflege als weitere Säule der Kindertagesbetreuung stärken.', '{1701}', 2, 2, null, 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7333, 17, 14, null, 'Startchancen-Programm für Kitas mit akutem Platzmangel oder hohem Anteil sozial benachteiligter Kinder.', '{1701}', 2, 2, null, 'Gezielte Mittel können zusätzliche Kapazitäten und Förderung an Orten mit hohem Bedarf unterstützen. Ob Plätze entstehen, hängt von Umsetzung, Personal und ergänzender kommunaler Finanzierung ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7334, 17, 14, null, 'Ausbau von Betriebskindergärten unterstützen und bürokratische Hürden abbauen.', '{1701}', 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-01', false, true),
  (7335, 17, 14, null, 'Bundeseinheitliche Kita-Qualitätsstandards mit bedarfsgerechtem Betreuungsschlüssel inklusive Ausfallzeiten, weniger Bürokratie und multiprofessionellen Teams.', '{1702,1703,1704}', 2, 2, null, 'Gemeinsame Standards können regionale Mindestqualität und Ausfallberücksichtigung verbessern. Ihre Umsetzung erfordert Abstimmung mit den Ländern und zusätzliche Mittel, wenn sie über bestehende Ausstattung hinausgehen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true),
  (7336, 17, 14, null, 'Erzieherausbildung und Weiterbildung schulgeldfrei und vergütet anbieten, Ausbildungskapazitäten der Länder erhöhen.', '{1702}', 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7337, 17, 14, null, 'Bei Arbeitskämpfen in Kitas verpflichtende Schlichtung, Mindestankündigungsfristen und Notbetrieb vorsehen.', '{1704}', 1, 2, null, 'Vorankündigung und Schlichtung könnten Familien mehr Planungssicherheit geben. Sie verhindern weder krankheitsbedingte Ausfälle noch lösen sie Personalengpässe; arbeitsrechtliche Ausgestaltung ist anspruchsvoll.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=19', null, 'offen', '2026-10-01', false, true),
  (7338, 17, 14, null, 'Kinderbetreuungskosten über ein Lebenschancen-BAföG mitfinanzieren.', '{1705}', 1, 2, null, 'Ein zweckgebundener Zuschuss kann einzelne Familien bei den Kosten entlasten. Seine Reichweite hängt von Anspruchshöhe und Zugang ab und beeinflusst das Platzangebot nicht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=10', null, 'offen', '2026-10-01', false, true),
  (7339, 17, 14, null, 'Steuerlichen Abzug von Kinderbetreuungskosten verbessern.', '{1705}', 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true),
  (7340, 17, 15, null, 'Ausreichend Kindergarten- und Kitaplätze in Wohnraumnähe bereitstellen, mit Vorrang für Familien mit zwei arbeitenden Eltern und arbeitende Alleinerziehende.', '{1701}', 1, 1, null, 'Eine Priorisierung kann Plätze für bestimmte Familien zugänglicher machen, erhöht aber nicht die Zahl der Plätze und kann andere Familien benachteiligen. Ein bundesweiter Eingriff in die Vergabe erfordert Abstimmung mit Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'offen', '2026-10-01', false, true),
  (7341, 17, 15, null, 'Krippen und Kitas ausreichend und qualifiziert besetzen; ein Betreuungsgehalt soll die Nachfrage nach Kitaplätzen und damit den Fachkräftemangel senken.', '{1701,1702}', 1, 2, null, 'Ein Betreuungsgehalt kann einzelne Familien finanziell entlasten, stellt aber keine bedarfsgerechte externe Betreuung sicher. Ob es die Platznachfrage dauerhaft senkt, ist unklar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true),
  (7342, 17, 15, null, 'Betriebskindergärten stärker fördern.', '{1701}', 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true),
  (7343, 17, 16, null, 'Rechtsanspruch auf Ganztagsbetreuung umsetzen und ausreichend Kitaplätze schaffen.', '{1701}', 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true),
  (7344, 17, 16, null, 'Familienentlastende Infrastruktur mit guter Erreichbarkeit ausbauen, Kitas in allen Stadtteilen.', '{1701}', 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true),
  (7345, 17, 16, null, 'Betreuungsschlüssel auf höchstens eine Fachkraft für drei Kinder unter drei Jahren und 7,5 ältere Kinder verbessern, unter Berücksichtigung von Ausfall- und Vorbereitungszeiten.', '{1702,1703}', 2, 2, null, 'Einheitliche Mindeststandards können die Qualität und Berücksichtigung von Ausfällen stärken. Die Länder setzen sie um; Personalverfügbarkeit und Finanzierung bestimmen die tatsächliche Wirkung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7346, 17, 16, null, 'Löhne in den Sozial- und Erziehungsdiensten erhöhen und Refinanzierung der Tarifverträge sichern.', '{1702}', 2, 2, null, 'Die Refinanzierung kann Trägern ermöglichen, tarifliche Löhne zu zahlen und Personal zu halten. Der Bund kann Kosten mittragen, aber die tatsächliche Personalgewinnung ist nicht garantiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7347, 17, 16, null, 'Zugang zur Erzieher*innen-Ausbildung erleichtern und Ausbildungsqualität erhöhen.', '{1702}', 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7348, 17, 16, null, 'Kitas für alle Kinder gebührenfrei machen.', '{1705}', 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7349, 17, 17, null, 'Unternehmen stärker zur Bereitstellung von Kita-Plätzen verpflichten, im Gegenzug steuerliche Vorteile.', '{1701}', 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-01', false, true),
  (7350, 17, 17, null, 'Länder und Kommunen bei der Ausbildung von mehr Erziehern unterstützen, Arbeitsbedingungen in Bildungseinrichtungen verbessern.', '{1702}', 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7351, 17, 17, null, 'Für Kinder ab drei Jahren mit festgestellten Deutschdefiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung.', '{1705}', 1, 1, null, 'Frühe Sprachförderung kann den Förderzugang verbessern, aber eine Pflicht erhöht nicht das knappe Platzangebot. Bedarfsermittlung, Zuständigkeit und Durchsetzung sind anspruchsvoll.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7352, 17, 17, null, 'Kita-Beiträge stabilisieren oder senken, mittelfristig Beitragsfreiheit.', '{1705}', 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7353, 17, 11, 'ST', 'Konzept vorlegen, das den Bedarf erfasst, die Finanzierung stabilisiert und den Personalschlüssel verbessert.', '{1701,1702,1703,1704}', 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7354, 17, 11, 'ST', 'Wohnortnahe Betreuung erhalten und über flexible Modelle, Kooperationen und Zusammenschlüsse an die regionale Nachfrage anpassen.', '{1701}', 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7355, 17, 11, 'ST', 'Dokumentationspflichten abbauen, Arbeitsalltag digital unterstützen, Leitungskräfte entlasten.', '{1702}', 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', null, 'offen', '2026-10-01', false, true),
  (7356, 17, 11, 'ST', 'Kindertagespflege durch faire Vergütung, Beratung und Sachkostenförderung stärken.', '{1701,1702}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7357, 17, 11, 'ST', 'Kitas bedarfsgerecht ausbauen und sanieren, flexible Öffnungszeitenmodelle fördern.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=50', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7358, 17, 12, 'ST', 'Zusätzliche Personalmittel über „Kita STABIL“ bereitstellen und das Programm über 2028 hinaus fortsetzen.', '{1701,1702}', 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7359, 17, 12, 'ST', 'Flexible Öffnungszeiten von Kitas bis in Randzeiten ausbauen.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7360, 17, 12, 'ST', 'Rechtsanspruch auf bis zu zehn Stunden Betreuung von Geburt bis zum 14. Lebensjahr aufrechterhalten.', '{1701}', 1, 1, null, 'Ein Anspruch für ältere Kinder geht über das für dieses Thema erforderliche Kita-Angebot hinaus und schafft keinen Platz. Umfang, Zuständigkeiten und Finanzierung machen die Umsetzung schwierig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-01', false, true),
  (7361, 17, 12, 'ST', 'Tatsächlichen Personalschlüssel in Kitas schrittweise verbessern.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7362, 17, 12, 'ST', 'Kitas mit besonderen sozialen Herausforderungen zusätzlich unterstützen.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7363, 17, 12, 'ST', 'Kurzfristige Entlastung von Eltern mit mehreren Kindern bei den Betreuungskosten sichern.', '{1705}', 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7364, 17, 13, 'ST', 'Nachhaltige kommunale Kitaplanung finanzieren.', '{1701}', 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7365, 17, 13, 'ST', 'Programm „HeimatKita“: wohnortnahe Betreuung zusichern und Kleinst-Kitas unterstützen.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7366, 17, 13, 'ST', 'Befristete Personalsicherung durch „Kita STABIL“ in eine langfristige strukturelle Verbesserung überführen.', '{1702}', 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7367, 17, 13, 'ST', 'Mindestpersonalschlüssel anheben, Sonderförderung für Kitas mit besonderen Bedarfen und Kita-Sozialarbeit ausbauen.', '{1702,1703}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7368, 17, 13, 'ST', 'Bezahlung und Arbeitsbedingungen für Erzieher*innen verbessern, von Bürokratie entlasten.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7369, 17, 13, 'ST', 'Erzieher*innen im Anerkennungsjahr unabhängig von der Trägerschaft angemessen vergüten.', '{1702}', 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7370, 17, 13, 'ST', 'Beitragsermäßigung für Mehrkinderfamilien dauerhaft sichern, Modell zur sozialen Staffelung der Kitabeiträge erarbeiten.', '{1705}', 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7371, 17, 14, 'ST', 'Flexible Öffnungszeiten am tatsächlichen Bedarf der Familien ausrichten.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=23', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7372, 17, 14, 'ST', 'Landesmodellprojekt für Gemeinschaftsbüros mit Kinderbetreuung und mobile Betreuungsreserven.', '{1701,1704}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7373, 17, 14, 'ST', 'Kurzfristig einspringende Betreuungszusammenschlüsse für Zeiten außerhalb der üblichen Öffnungszeiten unterstützen.', '{1701,1704}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7374, 17, 14, 'ST', 'Erzieherinnen und Erzieher entsprechend ausbilden und von Dokumentationspflichten entlasten.', '{1702}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7375, 17, 14, 'ST', 'Betreuungsschlüssel an den Förderbedarf anpassen und unterstützendes Personal einsetzen.', '{1702,1703}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7376, 17, 14, 'ST', 'Geschwisterkindregelung bei den Elternbeiträgen ändern, ohne sie abzuschaffen.', '{1705}', 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7377, 17, 15, 'ST', 'Krippen und Kindergärten ab dem ersten Kind mit dauerhaft gesicherter Landesfinanzierung kostenfrei machen.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=18', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7378, 17, 16, 'ST', 'Uneingeschränkten Rechtsanspruch auf zehn Stunden Betreuung täglich in Kindertageseinrichtungen schaffen.', '{1701}', 2, 1, null, 'Ein längerer Anspruch kann den Betreuungsumfang für Familien mit entsprechendem Bedarf direkt verbessern. Er verlangt zusätzliche Plätze und Personal und ist ohne entsprechende Kapazitäten innerhalb einer Wahlperiode schwer erfüllbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7379, 17, 16, 'ST', 'Multiprofessionelle Teams in Kitas flächendeckend aufbauen und die nötigen personellen und finanziellen Ressourcen sichern.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7380, 17, 16, 'ST', 'Personalschlüssel auf 1:3 in Krippen und 1:7,5 in Kindergärten verbessern.', '{1702,1703}', 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7381, 17, 16, 'ST', 'Für die Kindertagespflege Leistungs-, Entgelt- und Qualitätsvereinbarungen mit den Jugendämtern abschließen.', '{1702}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7382, 17, 16, 'ST', 'Bildung in Kindertageseinrichtungen für alle Eltern beitragsfrei machen.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7383, 17, 16, 'ST', 'Kostenlose Mittagsversorgung für Kinder in Kitas und Kindertagespflege.', '{1705}', 1, 2, null, 'Kostenfreie Mahlzeiten senken einen Teil der Familienausgaben, lassen Elternbeiträge und weitere Zusatzkosten aber bestehen. Die Wirkung auf die Gesamtbelastung ist daher begrenzt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', null, 'offen', '2026-10-01', false, true),
  (7384, 17, 16, 'ST', 'Finanzierung an den tatsächlichen Personalkosten ausrichten; Elternbeiträge und Mehrkosten besserer Personalschlüssel vollständig vom Land finanzieren.', '{1702,1703,1705}', 2, 2, null, 'Eine Finanzierung der tatsächlichen Kosten kann bessere Personalausstattung ermöglichen und Beitragsbelastungen begrenzen. Die Ausgabenhöhe und die Verteilung zwischen Land, Kommunen und Trägern sind anspruchsvoll.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true),
  (7385, 17, 16, 'ST', 'Alle Kita-Standorte im Land erhalten.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7386, 17, 17, 'ST', 'Ausbildungskapazitäten für Erzieher ausweiten und Studienplätze in der Kindheitspädagogik ausbauen.', '{1702}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7387, 17, 17, 'ST', 'Ausbildungs- und Arbeitsbedingungen im frühkindlichen Bereich durch Bezahlung, verlässliche Arbeitszeiten und Ausbildungsvergütung aufwerten.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7388, 17, 17, 'ST', 'Personal-Kind-Betreuungsschlüssel stärken.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7389, 17, 17, 'ST', 'Beitragsfreie Kitas einführen.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7390, 17, 11, 'MV', 'Planungs- und Genehmigungsverfahren für Kitas beschleunigen.', '{1701}', 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', null, 'offen', '2026-10-01', false, true),
  (7391, 17, 11, 'MV', 'Kindertagesbetreuung für Hochschulangehörige schaffen.', '{1701}', 1, 2, null, 'Ein gezieltes Angebot kann den Zugang für Hochschulangehörige verbessern, löst aber nur einen kleinen Teil des allgemeinen Platzmangels. Personal- und Investitionsbedarf bleiben bestehen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=68', null, 'offen', '2026-10-01', false, true),
  (7392, 17, 11, 'MV', 'Freiwerdende Ressourcen für bessere Betreuungsschlüssel einsetzen.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7393, 17, 11, 'MV', 'Mit relevanten Akteuren einen Perspektivplan zur Verbesserung der Erzieher-Kind-Relation entwickeln.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7394, 17, 11, 'MV', 'Multiprofessionelle Teams mit spezialisierten Fachkräften in Kindergärten vorschreiben.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7395, 17, 11, 'MV', 'Mittel aus dem Kita-Qualitätsgesetz in qualitätssteigernde Maßnahmen, insbesondere pädagogische Leitungszeit, investieren.', '{1702}', 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7396, 17, 11, 'MV', 'Pädagogische Teams durch Hauswirtschafts- und Verwaltungskräfte entlasten.', '{1702}', 2, 2, null, 'Zusätzliche Unterstützung kann pädagogischen Fachkräften mehr Zeit für Kinder geben. Sie benötigt weiteres Personal und verbessert nicht automatisch die Fachkraft-Kind-Relation.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', null, 'offen', '2026-10-01', false, true),
  (7397, 17, 12, 'MV', 'Runde Tische mit den Kommunen je Landkreis und kreisfreier Stadt für verlässliche Bedarfsplanung einrichten.', '{1701}', 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7398, 17, 12, 'MV', 'Gruppengröße in Krippen ab 2027 auf fünf, im Kindergarten ab 2028 auf 13 Kinder je Fachkraft senken.', '{1703}', 2, 2, null, 'Die festen Stufen verbessern die Personalausstattung, bleiben aber deutlich hinter den fachlichen Empfehlungen von 1:3 und 1:7,5 zurück. Der Zeitplan ist bestimmt, das zusätzliche Personal muss bei Fachkräftemangel aber erst gewonnen werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7399, 17, 12, 'MV', 'Multiprofessionelle Teams schrittweise als Grundausstattung an Kitas einführen, beginnend bei Kitas mit besonderen Herausforderungen.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=67', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7400, 17, 12, 'MV', 'Beitragsfreiheit der Kitas fortführen.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=64', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7401, 17, 13, 'MV', 'Anspruch auf einen vollen Ganztagsplatz für alle Kinder einführen.', '{1701}', 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7402, 17, 13, 'MV', 'Landesweites Modellprojekt mit flexibler Kinderbetreuung für junge Eltern.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene-mv.de/?wpdmdl=33772#page=84', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7403, 17, 13, 'MV', 'Betreuungsschlüssel deutlich verbessern und sinkende Geburtenzahlen für kleinere Gruppen statt Personalabbau nutzen.', '{1702,1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7404, 17, 13, 'MV', 'Kindertagespflegepersonen, die Fachstandards erfüllen, entsprechend bezahlen.', '{1702}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7405, 17, 13, 'MV', 'Beitragsfreie Kita beibehalten.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7406, 17, 14, 'MV', 'Bestehenden Betreuungsanspruch überall verlässlich erfüllen und passgenaue Angebote sichern.', '{1701,1704}', 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7407, 17, 14, 'MV', 'Landesfinanzierung für Kita und Kindertagespflege an den tatsächlichen Bedarf anpassen.', '{1701}', 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=37', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true),
  (7408, 17, 14, 'MV', 'Private Träger und Betriebskindergärten bei Einhaltung der Qualitätsstandards öffentlich fördern.', '{1701}', 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true),
  (7409, 17, 14, 'MV', 'Kindertagespflege rechtssicher stärken, Bürokratie abbauen, verlässliche Rahmenbedingungen schaffen.', '{1701}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7410, 17, 14, 'MV', 'Tageseltern angemessen vergüten und Betreuung über das dritte Lebensjahr hinaus ermöglichen.', '{1701}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7411, 17, 14, 'MV', 'Fachkraft-Kind-Relation stufenweise, evidenzbasiert und gegenfinanziert verbessern.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7412, 17, 14, 'MV', 'Zusätzliche Mittel vorrangig in Personal, Sprachförderung und Verlässlichkeit investieren.', '{1702,1704}', 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7413, 17, 14, 'MV', 'Mehr Fachkräfte durch niedrigere Ausbildungshürden, stärkere Praxisanteile und bedarfsgerechte Ausbildungskapazitäten gewinnen.', '{1702,1703}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7414, 17, 14, 'MV', 'Erzieherausbildung dual weiterentwickeln, weitere pädagogische und therapeutische Fachkräfte flexibler in Kitas einsetzen.', '{1702}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7415, 17, 14, 'MV', 'Beschäftigte von Kindertageseinrichtungen bei gleicher Qualifikation und Leistung gleich bezahlen.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7416, 17, 14, 'MV', 'Kita-Leitungen durch bessere Arbeitsbedingungen, weniger Berichtspflichten, digitale Verwaltung und klare Zuständigkeiten stärken.', '{1702}', 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', null, 'offen', '2026-10-01', false, true),
  (7417, 17, 15, 'MV', 'Betreuungsschlüssel in Krippen auf 1:4 und in Kindergärten auf 1:10 verbessern.', '{1702,1703}', 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true),
  (7418, 17, 15, 'MV', 'Erzieher angelehnt an den TVöD vergüten und von Dokumentationspflichten entlasten.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7419, 17, 15, 'MV', 'Beitragsfreie Kitas erhalten.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=19', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7420, 17, 15, 'MV', 'Kindertagespflegepersonen stärker unterstützen.', '{1701}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7421, 17, 16, 'MV', 'Beitragsfreiheit in Kitas erhalten.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7422, 17, 16, 'MV', 'Garantie für eine wohnortnahe Tagesbetreuung für jedes Kind.', '{1701}', 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7423, 17, 16, 'MV', 'Gruppengröße in der Krippe schrittweise auf vier Kinder je Gruppe senken.', '{1703}', 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true),
  (7424, 17, 16, 'MV', 'Arbeitszeiten in Kitas und Kindertagespflege an Arbeitswege und -zeiten der Eltern anpassen.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7425, 17, 17, 'MV', 'Erzieherberuf tariflich aufwerten, Arbeitsbedingungen verbessern und verlässliche Personalausstattung sichern.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7426, 17, 17, 'MV', 'Betreuungsschlüssel verbessern, damit mehr Zeit für individuelle Förderung bleibt.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7427, 17, 17, 'MV', 'Beitragsfreie Kita sichern und Kostenbeteiligung des Landes erhöhen.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7428, 17, 11, 'BE', 'Flexiblere und längere Betreuungsangebote ausbauen, etwa Betriebskindergärten und zusätzliche Tagesmütter und -väter.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7429, 17, 11, 'BE', 'Kita-Qualitätsoffensive mit Schwerpunkt Sprachbildung und Qualifizierung des pädagogischen Personals.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7430, 17, 11, 'BE', 'Multiprofessionelle Strukturen und Kita-Sozialarbeit stärken.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7431, 17, 11, 'BE', '24-Stunden-Kitas mit Betreuung zu Rand- und Nachtzeiten ausbauen.', '{1701}', 1, 1, null, 'Nachtbetreuung hilft nur Familien mit entsprechendem Bedarf und löst die allgemeine Angebotslücke kaum. Der hohe Personal- und Organisationsaufwand erschwert eine Umsetzung in der Wahlperiode.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', null, 'offen', '2026-10-01', false, true),
  (7432, 17, 11, 'BE', 'Flexible, kostenfreie Betreuungsangebote, insbesondere zu Randzeiten.', '{1705}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7433, 17, 12, 'BE', 'Sanierung und Neubau von Kitas in den Kiezen als Investitionsschwerpunkt des Sondervermögens.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7434, 17, 12, 'BE', 'Finanzierung landeseigener Kita-Betriebe mit Investitionsmitteln stabilisieren, wohnortnahes Angebot in allen Bezirken.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7435, 17, 12, 'BE', 'Betreuungsschlüssel weiter verbessern und mittelbare pädagogische Arbeit durch mehr Personalzeit stärken.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7436, 17, 12, 'BE', 'Personalschlüssel nur nach tatsächlich anwesendem Personal berechnen; Urlaub, Krankheit und Fortbildung zählen nicht mit.', '{1702,1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7437, 17, 12, 'BE', 'Kitas mit zusätzlichem Fachpersonal für Sprachbildung stärken und den Personalzuschlag für Sprachförderung wieder einführen.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7438, 17, 12, 'BE', 'Personalzuschlag für Integrationskitas erhöhen.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7439, 17, 13, 'BE', 'Allen Familien zum ersten Geburtstag automatisch einen Kitagutschein mit Zugang zu Beratung und Kitaplatzvermittlung zusenden.', '{1701}', 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7440, 17, 13, 'BE', 'Kitaplätze transparent und diskriminierungsfrei vergeben.', '{1701}', 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7441, 17, 13, 'BE', 'Betriebskitas unterstützen und ergänzende Betreuung außerhalb der Öffnungszeiten für Alleinerziehende und Schichtarbeitende ausweiten.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=110', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7442, 17, 13, 'BE', 'Kita-Platzausbau bei der Planung neuer Unterbringungsstandorte berücksichtigen.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7443, 17, 13, 'BE', 'Betreuungsschlüssel in Kitas weiter verbessern.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7444, 17, 14, 'BE', 'Landesweites Fast-Track-Genehmigungsverfahren mit Bearbeitungsgarantie, um Verwaltungshindernisse beim Kita-Ausbau abzubauen.', '{1701}', 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true),
  (7445, 17, 14, 'BE', 'Freie Kitaträger bei der Finanzierung den landeseigenen Kitas gleichstellen.', '{1701}', 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true),
  (7446, 17, 14, 'BE', 'Freien Kitaträgern Beiträge für zusätzliche pädagogische Leistungen außerhalb des Kitagutscheins ermöglichen.', '{1705}', 0, 3, null, 'Zusätzliche kostenpflichtige Leistungen verbessern die Bezahlbarkeit der Grundbetreuung nicht und können die Belastung von Familien erhöhen. Die Erlaubnis ist administrativ umsetzbar, wirkt aber dem Kostenziel nicht entgegen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true),
  (7447, 17, 14, 'BE', 'Sonderqualifikationen pädagogischer Fachkräfte in Kitas zusätzlich vergüten.', '{1702}', 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7448, 17, 14, 'BE', 'Mittelbare pädagogische Arbeit vollständig anerkennen und in die Personalschlüssel einrechnen.', '{1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7449, 17, 14, 'BE', 'Fachkräftemangel im Erziehungssektor bekämpfen und Betreuungsschlüssel in Berliner Kitas deutlich verbessern.', '{1702,1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7450, 17, 14, 'BE', 'Kitagutschein automatisch mit der Geburtsurkunde ausstellen.', '{1701}', 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7451, 17, 14, 'BE', 'Digitale Plattform für Kita- und Schulanmeldungen mit Echtzeit-Anmeldung und Mehrfachanmeldungen schaffen.', '{1701}', 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7452, 17, 14, 'BE', 'Über Anträge auf staatliche Leistungen einschließlich Kitagutscheinen binnen vier Wochen entscheiden und auszahlen.', '{1701}', 1, 3, null, 'Schnellere Bescheide erleichtern die Planung und beseitigen Verzögerungen im Verwaltungszugang. Sie schaffen keinen Platz, wenn das Angebot fehlt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', null, 'offen', '2026-10-01', false, true),
  (7453, 17, 14, 'BE', 'Dauerhaft ausreichend Kita- und Tagespflegeplätze mit flexibleren Öffnungszeiten, Notfallangeboten und 24-Stunden-Kitas schaffen.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7454, 17, 14, 'BE', 'Kinderbetreuung zu Hause für Menschen im Schichtdienst staatlich unterstützen.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7455, 17, 14, 'BE', 'Mobilen Kinderbetreuungsservice für Eltern mit besonderen Arbeitszeiten (MoKiS) deutlich ausbauen.', '{1701}', 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true),
  (7456, 17, 15, 'BE', 'Landeserziehungsgeld für Kinder unter drei Jahren in Höhe der vergleichbaren Kosten eines Kita-Platzes einführen.', '{1705}', 1, 2, null, 'Ein Geldbetrag kann Familien finanziell entlasten, sichert aber keinen Kita-Platz und kann die Nachfrage nach Betreuung sogar senken. Die Kosten hängen von Anspruch und Leistungshöhe ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7457, 17, 15, 'BE', 'Kostenfreiheit der Kita beibehalten.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7458, 17, 15, 'BE', 'Angebot an Kita-Plätzen erhalten und bedarfsgerecht ausbauen.', '{1701}', 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7459, 17, 15, 'BE', '„Blaulicht“-Kita für Polizei, Feuerwehr und Rettungsdienste schaffen; kleine und mittelgroße Kita-Träger sowie Betriebskindergärten fördern.', '{1701}', 2, 2, null, 'Betriebskitas schaffen zusätzliche Plätze und können Arbeitszeiten besser abdecken. Sie erreichen nicht alle Familien und benötigen Personal sowie tragfähige Trägerfinanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', null, 'offen', '2026-10-01', false, true),
  (7460, 17, 15, 'BE', 'Bestehende Hochschul-Kitas ausbauen.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7461, 17, 15, 'BE', 'Betreuungsschlüssel erhöhen und längere Öffnungszeiten für Eltern mit besonderen Arbeitszeiten ermöglichen.', '{1702,1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7462, 17, 16, 'BE', 'Personalschlüssel verbessern; Ziel sind rechnerisch drei Kinder unter drei Jahren bzw. 7,5 Kinder über drei Jahren je Fachkraft.', '{1703}', 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7463, 17, 16, 'BE', 'Fehlzeiten und mittelbare Arbeitszeiten in der Personalzumessung berücksichtigen; nur ausgebildete Fachkräfte voll auf den Personalschlüssel anrechnen.', '{1702,1703}', 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true),
  (7464, 17, 16, 'BE', 'Geltende Personalzuschläge mit Fachwelt und Praxis prüfen, öffnen und verbessern.', '{1702,1703}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7465, 17, 16, 'BE', 'Gesundheits-, Lärm- und Hitzeschutz in allen Kitas einführen, um das Arbeitsfeld für Fachkräfte attraktiv zu halten.', '{1702}', 1, 2, null, 'Bessere Arbeitsbedingungen können Belastungen mindern und die Bindung von Personal unterstützen. Der direkte Beitrag zu mehr verfügbaren Betreuungsstunden ist begrenzt und nicht gut untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', null, 'offen', '2026-10-01', false, true),
  (7466, 17, 16, 'BE', 'Modellprogramm Kita-Sozialarbeit erhalten und ausweiten, mittelfristig für zehn Prozent der Kitakinder, langfristig flächendeckend.', '{1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7467, 17, 16, 'BE', 'Bestehende Kita-Plätze durch planvolle Sanierungen sichern.', '{1701}', 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true),
  (7468, 17, 16, 'BE', 'Raum und Personal trotz sinkender Kinderzahlen im Kita-System halten.', '{1701,1702}', 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7469, 17, 16, 'BE', 'Anteil der landeseigenen Kita-Betriebe am Platzangebot auf ein Drittel erhöhen.', '{1701}', 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true),
  (7470, 17, 16, 'BE', 'Eigenanteil der Kitaträger an der Platzfinanzierung schrittweise abschmelzen.', '{1701}', 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true),
  (7471, 17, 16, 'BE', 'Allen Familien zum ersten Geburtstag einen verständlichen, mehrsprachigen Kita-Gutschein zusenden und aufsuchende Sozialarbeit zum Abbau von Zugangshürden stärken.', '{1701}', 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true),
  (7472, 17, 16, 'BE', 'Jugendämtern Zugriff auf einen Teil der Kitaplätze geben und das Freihalten von Plätzen finanzieren.', '{1701}', 1, 2, null, 'Reservierte Plätze können einzelne Zugangsprobleme abfedern, verringern aber die Zahl regulär verfügbarer Plätze. Der Nutzen hängt von lokaler Nachfrage und verlässlicher Finanzierung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true),
  (7473, 17, 16, 'BE', 'Vergütung in der Kindertagespflege so bemessen, dass sie Lebenshaltungskosten und Mieten deckt.', '{1701}', 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7474, 17, 16, 'BE', 'Verbesserten Kita-Betreuungsschlüssel ohne finanzielle Einbußen auf die Kindertagespflege übertragen.', '{1703}', 2, 2, null, 'Eine bessere Personalausstattung kann die Betreuungsqualität erhöhen. Eine Übertragung ohne Einkommensverluste erfordert zusätzliche Finanzierung und muss zur Struktur der Tagespflege passen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7475, 17, 16, 'BE', 'Ausreichend barrierefreie Kitaplätze in Wohnortnähe schaffen und Kitas mit heil-, sozial- und inklusionspädagogischen Fachkräften ausstatten.', '{1701,1702}', 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true),
  (7476, 17, 16, 'BE', 'Gezielt für das Berufsfeld Kita werben und Quereinsteigende bis zum DQR-Niveau 6 qualifizieren.', '{1702}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7477, 17, 16, 'BE', 'Qualitätsinitiative für die Ausbildung starten und den Anteil staatlicher Schulen an der Erzieher*innenausbildung erhöhen.', '{1702}', 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7478, 17, 16, 'BE', 'Praxisstunden in der Ausbildung vergüten und ausdrückliche Ausbildungsverträge einführen.', '{1702}', 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true),
  (7479, 17, 16, 'BE', 'Gebührenfreiheit der Bildung von der Kita bis zur Hochschule als Grundsatz beibehalten.', '{1705}', 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true),
  (7480, 17, 16, 'BE', 'Verpflichtende Zusatzzahlungen über Kitafördervereine zurückweisen.', '{1705}', 1, 3, null, 'Das Verhindern verpflichtender Zusatzforderungen kann unerwartete Kosten begrenzen. Es senkt nicht automatisch die regulären Elternbeiträge und muss mit der Finanzierung zusätzlicher Leistungen vereinbar sein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true);

